export function terrainPresetProcessProfile(params = {}) {
  const scenic = scenicPresetById(params.scenicPreset || "none");
  const requestedGeomorphology = String(params.geomorphologyPreset || "custom");
  const geomorphologyId =
    requestedGeomorphology !== "custom" || scenic.id === "none" ? requestedGeomorphology : scenic.geomorphologyPreset || "custom";
  const geomorphology = geomorphologyPresetById(geomorphologyId);
  const profile = {
    ...TERRAIN_PROCESS_DEFAULT,
    ...(GEOMORPHOLOGY_PROCESS_PROFILES[geomorphology?.id || "custom"] || {}),
    ...(SCENIC_PROCESS_OVERRIDES[scenic?.id || "none"] || {})
  };
  for (const key of TERRAIN_PROCESS_NUMERIC_KEYS) {
    profile[key] = clamp(Number(profile[key] ?? 0), 0, 1);
  }
  const aeolian = profile.aeolianAlignmentDeg == null ? Number.NaN : Number(profile.aeolianAlignmentDeg);
  profile.aeolianAlignmentDeg = Number.isFinite(aeolian) ? ((aeolian % 360) + 360) % 360 : null;
  profile.geomorphologyPreset = geomorphology?.id || "custom";
  profile.scenicPreset = scenic?.id || "none";
  return profile;
}

function terrainPresetProcessSummary(params = {}) {
  const profile = terrainPresetProcessProfile(params);
  const activeFeatures = TERRAIN_PROCESS_NUMERIC_KEYS
    .filter((key) => profile[key] >= 0.15)
    .map((key) => ({ key, weight: round(profile[key], 3) }))
    .sort((a, b) => b.weight - a.weight || a.key.localeCompare(b.key));
  return {
    primaryProcess: profile.primaryProcess,
    processClass: profile.processClass,
    geomorphologyPreset: profile.geomorphologyPreset,
    scenicPreset: profile.scenicPreset,
    dominantFeature: activeFeatures[0]?.key || "none",
    activeFeatureCount: activeFeatures.length,
    activeFeatures: activeFeatures.slice(0, 10),
    hydrologyCoupling: round(profile.hydrologyCoupling, 3),
    structuralControl: round(profile.structuralControl, 3),
    aeolianAlignmentDeg: profile.aeolianAlignmentDeg,
    method: "parametric-process-signature-linked-to-heightfield-hydrology-materials"
  };
}

export function terrainPresetMaterialPlan(params = {}, stats = null) {
  const scenic = scenicPresetById(params.scenicPreset || "none");
  const requestedGeomorphology = String(params.geomorphologyPreset || "custom");
  const geomorphologyPreset =
    requestedGeomorphology !== "custom" || scenic.id === "none" ? requestedGeomorphology : scenic.geomorphologyPreset || "custom";
  const material = TERRAIN_PRESET_MATERIALS[geomorphologyPreset] || TERRAIN_PRESET_MATERIALS.custom;
  const active = geomorphologyPreset !== "custom" || scenic.id !== "none";
  const processSignature = terrainPresetProcessSummary({ ...params, geomorphologyPreset, scenicPreset: scenic.id || "none" });
  return {
    mode: "terrain-preset-vertex-material",
    active,
    geomorphologyPreset,
    scenicPreset: scenic.id || "none",
    materialClass: material.materialClass,
    materialLabelZh: material.labelZh,
    paletteStopCount: material.stops.length,
    blend: material.blend,
    vertexColorOnly: true,
    extraGeometry: 0,
    extraDrawCalls: 0,
    firstPhaseCompatible: true,
    processSignature,
    colorLayerSignals: ["elevation", "slope", "roughness", "wetness", "vegetation", "terrain-preset"],
    maxElevationM: Number.isFinite(stats?.maxElevation) ? stats.maxElevation : null,
    meanSlopeDeg: Number.isFinite(stats?.meanSlope) ? stats.meanSlope : null,
    meanRoughnessM: Number.isFinite(stats?.meanRoughness) ? stats.meanRoughness : null
  };
}

