export function applyTerrainPresetParams(baseParams = {}, selection = {}) {
  const base = { ...baseParams };
  const scenicId = String(selection.scenicPreset ?? base.scenicPreset ?? "none");
  const scenic = scenicPresetById(scenicId);
  const selectedGeomorphology = selection.geomorphologyPreset ?? base.geomorphologyPreset;
  const geomorphologyId = String(
    selectedGeomorphology && selectedGeomorphology !== "custom"
      ? selectedGeomorphology
      : scenic && scenic.id !== "none"
        ? scenic.geomorphologyPreset
        : selectedGeomorphology || "custom"
  );
  const geomorphology = geomorphologyPresetById(geomorphologyId);
  const geomorphologyInfo = terrainPresetDisplayInfo(geomorphology, "geomorphology");
  const scenicInfo = terrainPresetDisplayInfo(scenic, "scenic");
  const seedBase = Number.isFinite(Number(base.seed)) ? Math.round(Number(base.seed)) : 142857;
  const seedOffset = (geomorphology?.seedOffset || 0) + (scenic?.seedOffset || 0);
  const next = {
    ...base,
    ...(geomorphology?.params || {}),
    ...(scenic?.params || {}),
    seed: seedOffset ? normalizeSeed(seedBase + seedOffset) : seedBase,
    geomorphologyPreset: geomorphology?.id || "custom",
    scenicPreset: scenic?.id || "none",
    terrainPresetLabelZh: geomorphologyInfo?.labelZh || "\u81ea\u5b9a\u4e49\u5730\u5f62",
    scenicPresetLabelZh: scenicInfo?.labelZh || "\u4e0d\u590d\u73b0\u666f\u533a",
    terrainPresetReferenceZh: scenicInfo?.referenceLandformZh || geomorphologyInfo?.referenceLandformZh || "",
    terrainPresetNotesZh: Array.isArray(scenic?.reconstructionNotesZh) ? scenic.reconstructionNotesZh : []
  };
  next.relief = clamp(firstFinite(next.relief, 1450), 300, MAX_TERRAIN_ELEVATION_M);
  next.ridgeWeight = clamp(firstFinite(next.ridgeWeight, 0.56), 0, 1);
  next.tectonics = clamp(firstFinite(next.tectonics, 0.58), 0, 1);
  next.microRelief = clamp(firstFinite(next.microRelief, 18), 0, 60);
  return next;
}

function geomorphologyPresetById(id) {
  return GEOMORPHOLOGY_PRESETS.find((preset) => preset.id === id) || GEOMORPHOLOGY_PRESETS[0];
}

function scenicPresetById(id) {
  return SCENIC_REPRODUCTION_PRESETS.find((preset) => preset.id === id) || SCENIC_REPRODUCTION_PRESETS[0];
}

export function terrainPresetDisplayInfo(presetOrId, kind = "geomorphology") {
  const preset = typeof presetOrId === "string"
    ? kind === "scenic"
      ? scenicPresetById(presetOrId)
      : geomorphologyPresetById(presetOrId)
    : presetOrId;
  if (!preset) return null;
  const overrides = TERRAIN_DISPLAY_TEXT_OVERRIDES[kind]?.[preset.id] || {};
  return { ...preset, ...overrides };
}

function normalizeSeed(value) {
  const seed = Math.abs(Math.round(Number(value) || 1)) % 2_147_483_647;
  return seed || 1;
}

function terrainPresetSummary(params = {}) {
  const geomorphology = geomorphologyPresetById(params.geomorphologyPreset || "custom");
  const scenic = scenicPresetById(params.scenicPreset || "none");
  const geomorphologyInfo = terrainPresetDisplayInfo(geomorphology, "geomorphology");
  const scenicInfo = terrainPresetDisplayInfo(scenic, "scenic");
  const active = (geomorphology?.id || "custom") !== "custom" || (scenic?.id || "none") !== "none";
  return {
    active,
    geomorphologyPreset: geomorphology?.id || "custom",
    scenicPreset: scenic?.id || "none",
    labelZh: geomorphologyInfo?.labelZh || "\u81ea\u5b9a\u4e49\u5730\u5f62",
    scenicLabelZh: scenicInfo?.labelZh || "\u4e0d\u590d\u73b0\u666f\u533a",
    referenceLandformZh: scenic?.id !== "none" ? scenicInfo.referenceLandformZh : geomorphologyInfo?.referenceLandformZh || "",
    reconstructionNotesZh: Array.isArray(scenic?.reconstructionNotesZh) ? scenic.reconstructionNotesZh : [],
    processSignature: terrainPresetProcessSummary(params),
    methodZh: active
      ? "\u53c2\u6570\u5316\u5730\u8c8c\u9884\u8bbe + DEM \u5f62\u6001\u53d8\u5f62 + \u5b8c\u6574\u6c34\u6587\u6c14\u5019\u91cd\u7b97"
      : "\u624b\u52a8\u53c2\u6570\u5730\u5f62",
    seed: Number(params.seed) || null
  };
}

