export function runUncertaintyEnsemble(baseParams, options = {}) {
  const start = performance.now();
  const mapSizeKm = resolveMapSizeKm(baseParams);
  const requestedResolution = clampInteger(baseParams?.resolution, 32, MAX_MODEL_RESOLUTION, 256);
  const maxResolution = clampInteger(options.maxResolution, 32, MAX_MODEL_RESOLUTION, 256);
  const diagnosticResolution = clampInteger(options.resolution ?? Math.min(requestedResolution, maxResolution), 32, MAX_MODEL_RESOLUTION, 256);
  const variants = Array.isArray(options.variants) && options.variants.length ? options.variants : UNCERTAINTY_VARIANTS;
  const base = normalizeEnsembleParams(baseParams, diagnosticResolution);
  const runs = [];

  for (const variant of variants) {
    const variantStart = performance.now();
    const nextParams = normalizeEnsembleParams(
      typeof variant.apply === "function" ? variant.apply({ ...base }) : { ...base, ...(variant.params || {}) },
      diagnosticResolution
    );
    const nextModel = buildModel(nextParams);
    runs.push(uncertaintyRunSnapshot(variant, nextParams, nextModel, performance.now() - variantStart));
  }

  const baseline = runs.find((run) => run.id === "baseline") || runs[0] || null;
  const metrics = summarizeUncertaintyMetrics(runs, baseline);
  const sensitivity = summarizeVariantSensitivity(runs, baseline);
  const warnings = uncertaintyWarnings({ metrics, sensitivity, requestedResolution, diagnosticResolution, baseParams });

  return {
    type: "geolab-uncertainty-ensemble",
    mapSizeKm,
    mapAreaKm2: mapSizeKm * mapSizeKm,
    requestedResolution,
    diagnosticResolution,
    diagnosticCellSizeM: (mapSizeKm / Math.max(1, diagnosticResolution - 1)) * 1000,
    variantCount: runs.length,
    uncertaintyClass: classifyUncertainty(metrics),
    baseline,
    metrics,
    sensitivity,
    runs,
    warnings,
    runtimeMs: performance.now() - start,
    generatedAt: new Date().toISOString()
  };
}

export function buildModel(params) {
  const start = performance.now();
  const n = clampInteger(params.resolution, 8, MAX_MODEL_RESOLUTION, 256);
  const sizeKm = resolveMapSizeKm(params);
  const areaKm2 = sizeKm * sizeKm;
  const scopedParams = {
    ...params,
    mapSizeKm: sizeKm,
    aoi: { ...(params?.aoi || {}), sizeKm },
    spatialContext: getSpatialContext({ ...params, mapSizeKm: sizeKm })
  };
  scopedParams.targetBounds = getTargetBounds(scopedParams);
  const height = createHeightField(n, scopedParams);
  const model = {
    n,
    sizeKm,
    areaKm2,
    cellSizeKm: sizeKm / (n - 1),
    targetBounds: scopedParams.targetBounds,
    spatialContext: scopedParams.spatialContext,
    height,
    brushStamp: 0,
    externalLayers: params.externalLayers || null
  };
  runModel(model, scopedParams);
  model.runtimeMs = performance.now() - start;
  return model;
}

export function runModel(model, params) {
  const start = performance.now();
  const previousWildlife = model.wildlife || null;
  const sizeKm = Number(model.sizeKm) || resolveMapSizeKm(params);
  model.sizeKm = sizeKm;
  model.areaKm2 = sizeKm * sizeKm;
  model.cellSizeKm = sizeKm / Math.max(1, model.n - 1);
  model.cellSupportAreaKm2 = model.areaKm2 / Math.max(1, model.height.length);
  params = {
    ...params,
    mapSizeKm: sizeKm,
    aoi: { ...(params?.aoi || {}), sizeKm },
    spatialContext: model.spatialContext || getSpatialContext({ ...params, mapSizeKm: sizeKm })
  };
  params.targetBounds = model.targetBounds || getTargetBounds(params);
  model.targetBounds = params.targetBounds;
  model.spatialContext = params.spatialContext;
  model.externalLayers = params.externalLayers || model.externalLayers || null;
  prepareExternalLayers(model, params);
  model.slope = computeSlope(model.height, model.n, model.cellSizeKm);
  model.aspect = computeAspect(model.height, model.n, model.cellSizeKm);
  model.terrainDiagnostics = computeTerrainDiagnostics(model.height, model.n, model.cellSizeKm);
  model.surface = computeSurfaceLayers(model, params, null);
  model.wind = computeWindField(model, params);
  let climate = computeClimate(model, params);
  model.temperature = climate.temperature;
  model.precipitation = climate.precipitation;
  model.climate = climate.climate;
  model.windUplift = climate.windUplift;
  model.rainShadow = climate.rainShadow;
  model.surface = computeSurfaceLayers(model, params, climate);
  model.wind = computeWindField(model, params);
  climate = computeClimate(model, params);
  model.temperature = climate.temperature;
  model.precipitation = climate.precipitation;
  model.climate = climate.climate;
  model.windUplift = climate.windUplift;
  model.rainShadow = climate.rainShadow;
  model.windSpeed = climate.windSpeed;
  model.windDirection = climate.windDirection;
  model.windExposure = climate.windExposure;
  model.surface = computeSurfaceLayers(model, params, climate);
  model.filledHeight = priorityFlood(model.height, model.n, params.seaLevel);
  const flow = computeFlow(model.filledHeight, model.height, model.n, model.cellSizeKm, params.seaLevel);
  model.receiver = flow.receiver;
  model.receiverDistance = flow.receiverDistance;
  model.flowDirection = flow.flowDirection;
  model.dInfinityReceiver = flow.dInfinityReceiver;
  model.dInfinitySecondaryReceiver = flow.dInfinitySecondaryReceiver;
  model.dInfinityReceiverDistance = flow.dInfinityReceiverDistance;
  model.dInfinitySecondaryReceiverDistance = flow.dInfinitySecondaryReceiverDistance;
  model.dInfinityPrimaryFraction = flow.dInfinityPrimaryFraction;
  model.dInfinitySecondaryFraction = flow.dInfinitySecondaryFraction;
  model.dInfinityAngleDeg = flow.dInfinityAngleDeg;
  computeAccumulation(model, params);
  model.hydraulics = computeHydraulicDiagnostics(model, params);
  model.wetnessIndex = computeWetnessIndex(model);
  model.subsurface = computeSubsurfaceVolume(model, params);
  model.hazards = computeTimeHazards(model, params);
  refreshInfrastructureAfterEnvironmentalState(model, params);
  model.builtResilience = computeBuiltEnvironmentResilienceState(model, params);
  model.landscapeNetwork = buildLandscapeBlockNetwork(model, params);
  model.wildlife = buildWildlifeState(model, params, model.landscapeNetwork, {
    previousState: previousWildlife,
    elapsedYears: 1
  });
  model.dataConfidence = computeDataConfidence(model, params);
  model.stats = computeStats(model, params);
  model.stats.landscapeNetwork = model.landscapeNetwork.summary;
  model.stats.wildlife = model.wildlife.summary;
  model.runtimeMs = performance.now() - start;
  model.fullRuntimeMs = model.runtimeMs;
  model.lastUpdateMode = "full";
  return model;
}

export function updateTemporalModel(model, params = {}) {
  const start = performance.now();
  if (!model?.height || !model?.surface || !model?.hydraulics || !model?.subsurface || !model?.flowAccumulation) {
    return runModel(model, params);
  }
  const sizeKm = Number(model.sizeKm) || resolveMapSizeKm(params);
  model.sizeKm = sizeKm;
  model.areaKm2 = sizeKm * sizeKm;
  model.cellSizeKm = sizeKm / Math.max(1, model.n - 1);
  model.cellSupportAreaKm2 = model.areaKm2 / Math.max(1, model.height.length);
  params = {
    ...params,
    mapSizeKm: sizeKm,
    aoi: { ...(params?.aoi || {}), sizeKm },
    spatialContext: model.spatialContext || getSpatialContext({ ...params, mapSizeKm: sizeKm })
  };
  params.targetBounds = model.targetBounds || getTargetBounds(params);
  model.targetBounds = params.targetBounds;
  model.spatialContext = params.spatialContext;
  model.externalLayers = params.externalLayers || model.externalLayers || null;
  model.hazards = computeTimeHazards(model, params);
  refreshInfrastructureBlockState(model);
  model.builtResilience = computeBuiltEnvironmentResilienceState(model, params);
  const previousWildlife = model.wildlife || null;
  model.landscapeNetwork = buildLandscapeBlockNetwork(model, params);
  model.wildlife = buildWildlifeState(model, params, model.landscapeNetwork, {
    previousState: previousWildlife,
    elapsedYears: 1
  });
  model.stats = computeStats(model, params);
  model.stats.landscapeNetwork = model.landscapeNetwork.summary;
  model.stats.wildlife = model.wildlife.summary;
  model.temporalRuntimeMs = performance.now() - start;
  model.runtimeMs = model.temporalRuntimeMs;
  model.lastUpdateMode = "temporal";
  return model;
}

export function erodeModel(model, params, passes = 4) {
  const n = model.n;
  const height = model.height;
  const next = new Float32Array(height.length);
  const erosionGain = 0.00034 * Number(params.erosionStrength);
  const talus = 0.11;

  for (let pass = 0; pass < passes; pass += 1) {
    runModel(model, params);
    next.set(height);

    const order = model.sortedByHeight;
    for (const i of order) {
      if (height[i] <= params.seaLevel) continue;
      const receiver = model.receiver[i];
      if (receiver < 0) continue;
      const drop = Math.max(0, model.filledHeight[i] - model.filledHeight[receiver]);
      const slope = drop / Math.max(1, model.receiverDistance[i] * model.cellSizeKm * 1000);
      const discharge = Math.log1p(model.discharge[i] / 1_000_000);
      const rootResistance = clamp(model.surface?.rootCohesion?.[i] ?? 0, 0, 1);
      const incision = erosionGain * discharge * Math.sqrt(Math.max(0, slope)) * 1000 * (1 - rootResistance * 0.42);
      const deposit = incision * (slope < 0.035 ? 0.45 : 0.16);
      next[i] -= incision;
      next[receiver] += deposit;
    }

    for (let y = 1; y < n - 1; y += 1) {
      for (let x = 1; x < n - 1; x += 1) {
        const i = y * n + x;
        if (next[i] <= params.seaLevel) continue;
        let transfer = 0;
        for (const nb of D8) {
          const ni = (y + nb.dy) * n + x + nb.dx;
          const drop = next[i] - next[ni];
          if (drop > talus * nb.distance * model.cellSizeKm * 1000) {
            const rootResistance = clamp(model.surface?.rootCohesion?.[i] ?? 0, 0, 1);
            transfer += (drop - talus * nb.distance * model.cellSizeKm * 1000) * 0.018 * (1 - rootResistance * 0.34);
          }
        }
        next[i] -= transfer;
        height[i] = Math.max(0, next[i]);
      }
    }
  }

  runModel(model, params);
  return model;
}

export function applyBrush(model, params, gx, gy, brush) {
  const n = model.n;
  const radius = Math.max(1, Math.round(Number(brush.radius) || 1));
  const power = Number(brush.power) || 0;
  const mode = brush.mode;
  const height = model.height;
  const ix = Math.round(clamp(gx, 0, n - 1));
  const iy = Math.round(clamp(gy, 0, n - 1));
  const x0 = Math.max(0, ix - radius);
  const x1 = Math.min(n - 1, ix + radius);
  const y0 = Math.max(0, iy - radius);
  const y1 = Math.min(n - 1, iy + radius);
  const copy = mode === "smooth" ? copyBrushWindow(height, n, x0, y0, x1, y1, 1) : null;
  const dirtyBounds = {
    x0,
    y0,
    x1,
    y1,
    paddedX0: Math.max(0, x0 - 1),
    paddedY0: Math.max(0, y0 - 1),
    paddedX1: Math.min(n - 1, x1 + 1),
    paddedY1: Math.min(n - 1, y1 + 1),
    cellCount: (x1 - x0 + 1) * (y1 - y0 + 1)
  };

  model.brushStamp += 1;
  for (let y = y0; y <= y1; y += 1) {
    for (let x = x0; x <= x1; x += 1) {
      const dx = x - ix;
      const dy = y - iy;
      const distance = Math.hypot(dx, dy);
      if (distance > radius) continue;
      const i = y * n + x;
      const w = 0.5 + 0.5 * Math.cos((Math.PI * distance) / Math.max(1, radius));

      if (mode === "raise") {
        height[i] = Math.min(MAX_TERRAIN_ELEVATION_M, height[i] + power * w);
      } else if (mode === "lower") {
        height[i] = Math.max(0, height[i] - power * w);
      } else if (mode === "roughen") {
        const r = hash01(x + model.brushStamp * 17, y - model.brushStamp * 13, params.seed + 991);
        height[i] = clamp(height[i] + (r - 0.5) * power * w * 1.8, 0, MAX_TERRAIN_ELEVATION_M);
      } else if (mode === "smooth") {
        let total = 0;
        let count = 0;
        for (let oy = -1; oy <= 1; oy += 1) {
          for (let ox = -1; ox <= 1; ox += 1) {
            const sx = clamp(x + ox, 0, n - 1);
            const sy = clamp(y + oy, 0, n - 1);
            total += brushWindowValue(copy, sx, sy);
            count += 1;
          }
        }
        height[i] = lerp(height[i], total / count, w * 0.62);
      }
    }
  }
  return dirtyBounds;
}

function copyBrushWindow(height, n, x0, y0, x1, y1, padding = 1) {
  const bx0 = Math.max(0, x0 - padding);
  const by0 = Math.max(0, y0 - padding);
  const bx1 = Math.min(n - 1, x1 + padding);
  const by1 = Math.min(n - 1, y1 + padding);
  const width = bx1 - bx0 + 1;
  const values = new Float32Array(width * (by1 - by0 + 1));
  let cursor = 0;
  for (let y = by0; y <= by1; y += 1) {
    for (let x = bx0; x <= bx1; x += 1) {
      values[cursor] = height[y * n + x];
      cursor += 1;
    }
  }
  return { x0: bx0, y0: by0, x1: bx1, y1: by1, width, values };
}

function brushWindowValue(copy, x, y) {
  const sx = clamp(x, copy.x0, copy.x1);
  const sy = clamp(y, copy.y0, copy.y1);
  return copy.values[(sy - copy.y0) * copy.width + (sx - copy.x0)];
}

export function getCell(model, x, y) {
  const gx = Math.round(clamp(x, 0, model.n - 1));
  const gy = Math.round(clamp(y, 0, model.n - 1));
  const i = gy * model.n + gx;
  const subsurfaceIndex = subsurfaceColumnIndex(model, i);
  const lithology = subsurfaceIndex >= 0 ? model.subsurface?.lithologyCode?.[subsurfaceIndex] : 0;
  const subsurfaceMaterialId = subsurfaceIndex >= 0 ? model.subsurface?.columnMaterialClassCode?.[subsurfaceIndex] ?? 0 : 0;
  const subsurfaceRiskId = subsurfaceIndex >= 0 ? model.subsurface?.columnRiskClassCode?.[subsurfaceIndex] ?? 0 : 0;
  const vegetationType = vegetationTypeRecord(model.surface?.vegetationType?.[i] ?? 0);
  return {
    x: gx,
    y: gy,
    index: i,
    elevation: model.height[i],
    slope: model.slope[i],
    aspect: model.aspect?.[i] ?? 0,
    curvature: model.terrainDiagnostics?.curvature?.[i] ?? 0,
    roughness: model.terrainDiagnostics?.roughness?.[i] ?? 0,
    tpi: model.terrainDiagnostics?.tpi?.[i] ?? 0,
    precipitation: model.precipitation[i],
    temperature: model.temperature[i],
    flowAccumulation: model.flowAccumulation[i],
    discharge: model.discharge[i],
    runoffCoefficient: model.runoffCoefficient?.[i] ?? 0,
    wetnessIndex: model.wetnessIndex?.[i] ?? 0,
    flowVelocity: model.hydraulics?.flowVelocity?.[i] ?? 0,
    channelDepthM: model.hydraulics?.channelDepthM?.[i] ?? 0,
    channelWidthM: model.hydraulics?.channelWidthM?.[i] ?? 0,
    shearStressPa: model.hydraulics?.shearStressPa?.[i] ?? 0,
    streamPowerWm2: model.hydraulics?.streamPowerWm2?.[i] ?? 0,
    sedimentTransportIndex: model.hydraulics?.sedimentTransportIndex?.[i] ?? 0,
    erosionRisk: model.hydraulics?.erosionRisk?.[i] ?? 0,
    depositionRisk: model.hydraulics?.depositionRisk?.[i] ?? 0,
    floodHazard: model.hazards?.currentFloodHazard?.[i] ?? model.hazards?.floodHazard?.[i] ?? 0,
    floodDepthM: model.hazards?.floodDepthM?.[i] ?? 0,
    droughtStress: model.hazards?.currentDroughtStress?.[i] ?? model.hazards?.droughtStress?.[i] ?? 0,
    wildfireRisk: model.hazards?.currentWildfireRisk?.[i] ?? model.hazards?.wildfireRisk?.[i] ?? 0,
    landslideRisk: model.hazards?.currentLandslideRisk?.[i] ?? model.hazards?.landslideRisk?.[i] ?? 0,
    hazardIndex: model.hazards?.currentHazardIndex?.[i] ?? model.hazards?.hazardIndex?.[i] ?? 0,
    cumulativeErosionM: model.hazards?.currentCumulativeErosionM?.[i] ?? model.hazards?.cumulativeErosionM?.[i] ?? 0,
    projectedVegetation: model.hazards?.currentProjectedVegetation?.[i] ?? model.hazards?.projectedVegetation?.[i] ?? 0,
    windSpeed: model.windSpeed?.[i] ?? 0,
    windDirection: model.windDirection?.[i] ?? 0,
    windExposure: model.windExposure?.[i] ?? 0,
    dataConfidence: model.dataConfidence
      ? {
          observedSupport: model.dataConfidence.observedSupport?.[i] ?? 0,
          inferredFraction: model.dataConfidence.inferredFraction?.[i] ?? 1,
          customizedSupport: model.dataConfidence.customizedSupport?.[i] ?? 0,
          sourceCount: model.dataConfidence.sourceCount?.[i] ?? 0,
          sourceMask: model.dataConfidence.sourceMask?.[i] ?? 0,
          sources: dataSourceCodes(model.dataConfidence.sourceMask?.[i] ?? 0)
        }
      : null,
    vegetation: model.surface?.vegetation?.[i] ?? 0,
    canopyHeight: model.surface?.canopyHeight?.[i] ?? 0,
    leafAreaIndex: model.surface?.leafAreaIndex?.[i] ?? 0,
    vegetationType,
    vegetationResilience: model.surface?.vegetationResilience?.[i] ?? 0,
    canopyRoughnessLengthM: model.surface?.canopyRoughnessLengthM?.[i] ?? 0,
    biomassCarbonKgM2: model.surface?.biomassCarbonKgM2?.[i] ?? 0,
    hydraulicConductivityMmHr: model.surface?.hydraulicConductivityMmHr?.[i] ?? 0,
    availableWaterCapacityMm: model.surface?.availableWaterCapacityMm?.[i] ?? 0,
    rootDepthM: model.surface?.rootDepthM?.[i] ?? 0,
    imperviousFraction: model.surface?.imperviousFraction?.[i] ?? 0,
    infiltrationCapacity: model.surface?.infiltrationCapacity?.[i] ?? 0,
    rootCohesion: model.surface?.rootCohesion?.[i] ?? 0,
    actualEvapotranspiration: model.surface?.actualEvapotranspiration?.[i] ?? 0,
    waterBalance: model.surface?.waterBalance?.[i] ?? 0,
    curveNumber: model.surface?.curveNumber?.[i] ?? 0,
    landCover: LAND_COVER[model.surface?.landCover?.[i] ?? 0] || LAND_COVER[0],
    soilGroup: SOIL_GROUPS[model.surface?.soilGroup?.[i] ?? 0] || SOIL_GROUPS[0],
    climate: CLIMATES[model.climate[i]],
    subsurface: model.subsurface
      ? {
          waterTableDepthM: subsurfaceColumnValue(model, "columnWaterTableDepthM", i, 0),
          bedrockDepthM: subsurfaceColumnValue(model, "columnBedrockDepthM", i, 0),
          aquiferPotential: subsurfaceColumnValue(model, "columnAquiferPotential", i, 0),
          fractureRisk: subsurfaceColumnValue(model, "columnFractureRisk", i, 0),
          liquefactionRisk: subsurfaceColumnValue(model, "columnLiquefactionRisk", i, 0),
          storageMm: subsurfaceColumnValue(model, "columnStorageMm", i, 0),
          voxelObservedSupport: subsurfaceColumnValue(model, "columnVoxelObservedSupport", i, 0),
          inferenceReliability: subsurfaceColumnValue(model, "columnInferenceReliability", i, 0),
          engineeringRisk: subsurfaceColumnValue(model, "columnEngineeringRisk", i, 0),
          aquiferVolumeM3: subsurfaceColumnValue(model, "columnAquiferVolumeM3", i, 0),
          highRiskVolumeM3: subsurfaceColumnValue(model, "columnHighRiskVolumeM3", i, 0),
          externalObserved: subsurfaceColumnValue(model, "columnExternalObserved", i, 0) > 0,
          lithology: SUBSURFACE_LITHOLOGY[lithology] || SUBSURFACE_LITHOLOGY[0],
          materialClass: SUBSURFACE_MATERIAL_CLASSES[subsurfaceMaterialId] || SUBSURFACE_MATERIAL_CLASSES[0],
          riskClass: SUBSURFACE_RISK_CLASSES[subsurfaceRiskId] || SUBSURFACE_RISK_CLASSES[0]
        }
      : null
  };
}

export function colorForValue(model, params, mode, i) {
  if (mode === "landscapeConnectivity") {
    const block = landscapeBlockAtCell(model, i);
    return ramp(block?.meanNeighborConnectivity ?? 0, 0.18, 0.96, [
      [126, 69, 65],
      [199, 144, 73],
      [162, 171, 91],
      [67, 142, 104],
      [61, 132, 163]
    ]);
  }
  if (mode === "wildlife") {
    const block = landscapeBlockAtCell(model, i);
    const blockState = block ? model.wildlife?.blockStates?.[block.blockId] : null;
    return ramp(blockState?.richness ?? 0, 0, Math.max(4, model.wildlife?.species?.length || 10), [
      [89, 88, 77],
      [166, 133, 73],
      [112, 151, 83],
      [51, 126, 92],
      [53, 132, 153]
    ]);
  }
  if (model.height[i] <= params.seaLevel) {
    return [34, 82, 125];
  }

  if (mode === "climate") {
    return CLIMATES[model.climate[i]].color;
  }
  if (mode === "precipitation") {
    return ramp(model.precipitation[i], 120, 2800, [
      [128, 95, 65],
      [218, 187, 91],
      [90, 155, 113],
      [63, 131, 174],
      [190, 217, 231]
    ]);
  }
  if (mode === "temperature") {
    return ramp(model.temperature[i], -12, 32, [
      [227, 238, 240],
      [122, 170, 207],
      [91, 155, 111],
      [225, 184, 82],
      [200, 91, 68]
    ]);
  }
  if (mode === "flow") {
    const v = Math.log1p(model.flowAccumulation[i]) / Math.log1p(Math.max(2, model.stats.maxFlowAccumulation));
    return mix3([48, 55, 53], [74, 154, 188], [225, 240, 244], v);
  }
  if (mode === "velocity") {
    return ramp(model.hydraulics?.flowVelocity?.[i] ?? 0, 0, 3.2, [
      [54, 88, 101],
      [59, 140, 158],
      [102, 174, 119],
      [222, 182, 83],
      [194, 91, 75]
    ]);
  }
  if (mode === "shear") {
    return ramp(model.hydraulics?.shearStressPa?.[i] ?? 0, 0, 160, [
      [58, 93, 105],
      [74, 144, 151],
      [151, 171, 92],
      [219, 148, 76],
      [177, 75, 77]
    ]);
  }
  if (mode === "sediment") {
    return ramp(model.hydraulics?.sedimentTransportIndex?.[i] ?? 0, 0, 3, [
      [65, 96, 101],
      [97, 139, 111],
      [183, 163, 88],
      [205, 123, 73],
      [145, 69, 82]
    ]);
  }
  if (mode === "erosion") {
    return ramp(model.hydraulics?.erosionRisk?.[i] ?? 0, 0, 1, [
      [59, 115, 92],
      [147, 159, 91],
      [207, 151, 78],
      [190, 88, 72],
      [114, 54, 70]
    ]);
  }
  if (mode === "deposition") {
    return ramp(model.hydraulics?.depositionRisk?.[i] ?? 0, 0, 1, [
      [65, 91, 109],
      [69, 132, 158],
      [105, 159, 141],
      [189, 172, 95],
      [214, 194, 134]
    ]);
  }
  if (mode === "hazard") {
    return ramp(model.hazards?.currentHazardIndex?.[i] ?? model.hazards?.hazardIndex?.[i] ?? 0, 0, 1, [
      [57, 112, 95],
      [157, 167, 91],
      [218, 157, 78],
      [189, 83, 72],
      [91, 54, 79]
    ]);
  }
  if (mode === "flood") {
    return ramp(model.hazards?.currentFloodHazard?.[i] ?? model.hazards?.floodHazard?.[i] ?? 0, 0, 1, [
      [72, 104, 100],
      [65, 136, 153],
      [79, 161, 190],
      [151, 210, 226],
      [222, 242, 245]
    ]);
  }
  if (mode === "drought") {
    return ramp(model.hazards?.currentDroughtStress?.[i] ?? model.hazards?.droughtStress?.[i] ?? 0, 0, 1, [
      [63, 124, 97],
      [137, 158, 84],
      [204, 164, 79],
      [190, 110, 69],
      [119, 70, 72]
    ]);
  }
  if (mode === "wildfire") {
    return ramp(model.hazards?.currentWildfireRisk?.[i] ?? model.hazards?.wildfireRisk?.[i] ?? 0, 0, 1, [
      [58, 114, 81],
      [151, 155, 75],
      [221, 160, 66],
      [204, 82, 59],
      [83, 55, 65]
    ]);
  }
  if (mode === "landslide") {
    return ramp(model.hazards?.currentLandslideRisk?.[i] ?? model.hazards?.landslideRisk?.[i] ?? 0, 0, 1, [
      [69, 116, 105],
      [126, 151, 92],
      [195, 152, 79],
      [170, 91, 72],
      [93, 62, 70]
    ]);
  }
  if (mode === "builtDamage") {
    return ramp(model.builtResilience?.currentDamageIndex?.[i] ?? model.builtResilience?.combinedDamageIndex?.[i] ?? 0, 0, 1, [
      [70, 121, 104],
      [144, 157, 92],
      [218, 170, 83],
      [189, 93, 70],
      [83, 55, 72]
    ]);
  }
  if (mode === "timechange") {
    const projected = model.hazards?.currentProjectedVegetation?.[i] ?? model.hazards?.projectedVegetation?.[i] ?? model.surface?.vegetation?.[i] ?? 0;
    const current = model.surface?.vegetation?.[i] ?? 0;
    return diverging(projected - current, -0.45, 0.45, [
      [156, 79, 65],
      [213, 213, 184],
      [46, 124, 74]
    ]);
  }
  if (mode === "subsurface") {
    const bedrock = subsurfaceColumnValue(model, "columnBedrockDepthM", i, 0);
    const maxDepth = Math.max(20, model.subsurface?.depthM ?? 240);
    return ramp(bedrock, 0, maxDepth * 0.7, [
      [87, 72, 63],
      [139, 112, 76],
      [178, 154, 104],
      [119, 122, 117],
      [72, 78, 84]
    ]);
  }
  if (mode === "aquifer") {
    return ramp(subsurfaceColumnValue(model, "columnAquiferPotential", i, 0), 0, 1, [
      [81, 68, 62],
      [119, 108, 81],
      [76, 139, 132],
      [55, 158, 190],
      [185, 226, 235]
    ]);
  }
  if (mode === "geostress") {
    const value = Math.max(
      subsurfaceColumnValue(model, "columnFractureRisk", i, 0),
      subsurfaceColumnValue(model, "columnLiquefactionRisk", i, 0)
    );
    return ramp(value, 0, 1, [
      [71, 100, 92],
      [141, 151, 91],
      [214, 157, 78],
      [185, 84, 72],
      [84, 54, 78]
    ]);
  }
  if (mode === "subsurfaceConfidence") {
    const observed = subsurfaceColumnValue(model, "columnVoxelObservedSupport", i, 0);
    const reliability = subsurfaceColumnValue(model, "columnInferenceReliability", i, 0);
    return ramp(observed * 0.7 + reliability * 0.3, 0, 1, [
      [93, 68, 70],
      [170, 117, 73],
      [201, 179, 96],
      [93, 155, 118],
      [71, 150, 197]
    ]);
  }
  if (mode === "undergroundRisk") {
    return ramp(subsurfaceColumnValue(model, "columnEngineeringRisk", i, 0), 0, 1, [
      [66, 119, 103],
      [134, 158, 91],
      [210, 166, 76],
      [196, 94, 67],
      [90, 54, 76]
    ]);
  }
  if (mode === "confidence") {
    return ramp(model.dataConfidence?.observedSupport?.[i] ?? 0, 0, 1, [
      [109, 78, 72],
      [188, 138, 79],
      [196, 181, 98],
      [85, 153, 112],
      [53, 131, 172]
    ]);
  }
  if (mode === "slope") {
    return ramp(model.slope[i], 0, 42, [
      [77, 126, 83],
      [166, 161, 92],
      [178, 122, 77],
      [232, 231, 220]
    ]);
  }
  if (mode === "curvature") {
    return diverging(model.terrainDiagnostics?.curvature?.[i] ?? 0, -0.08, 0.08, [
      [90, 121, 172],
      [227, 229, 216],
      [176, 92, 72]
    ]);
  }
  if (mode === "tpi") {
    return diverging(model.terrainDiagnostics?.tpi?.[i] ?? 0, -80, 80, [
      [67, 126, 152],
      [216, 216, 188],
      [157, 99, 74]
    ]);
  }
  if (mode === "roughness") {
    return ramp(model.terrainDiagnostics?.roughness?.[i] ?? 0, 0, 180, [
      [58, 103, 91],
      [140, 154, 93],
      [187, 138, 81],
      [210, 211, 199]
    ]);
  }
  if (mode === "vegetation") {
    return ramp(model.surface?.vegetation?.[i] ?? 0, 0, 1, [
      [134, 108, 78],
      [180, 166, 86],
      [95, 151, 75],
      [35, 116, 74],
      [20, 78, 58]
    ]);
  }
  if (mode === "vegtype") {
    return vegetationTypeRecord(model.surface?.vegetationType?.[i] ?? 0).color;
  }
  if (mode === "biomass") {
    return ramp(model.surface?.biomassCarbonKgM2?.[i] ?? 0, 0, 32, [
      [132, 105, 78],
      [164, 154, 82],
      [88, 145, 83],
      [38, 112, 77],
      [18, 72, 57]
    ]);
  }
  if (mode === "canopy") {
    return ramp(model.surface?.canopyHeight?.[i] ?? 0, 0, 34, [
      [136, 112, 80],
      [116, 150, 83],
      [55, 124, 73],
      [23, 83, 59]
    ]);
  }
  if (mode === "lai") {
    return ramp(model.surface?.leafAreaIndex?.[i] ?? 0, 0, 8, [
      [130, 103, 75],
      [180, 171, 87],
      [88, 153, 80],
      [31, 111, 69],
      [16, 70, 54]
    ]);
  }
  if (mode === "landcover") {
    return (LAND_COVER[model.surface?.landCover?.[i] ?? 0] || LAND_COVER[0]).color;
  }
  if (mode === "soil") {
    return (SOIL_GROUPS[model.surface?.soilGroup?.[i] ?? 0] || SOIL_GROUPS[0]).color;
  }
  if (mode === "infiltration") {
    return ramp(model.surface?.infiltrationCapacity?.[i] ?? 0, 0, 1, [
      [126, 72, 66],
      [196, 143, 78],
      [181, 177, 94],
      [82, 151, 106],
      [61, 145, 175]
    ]);
  }
  if (mode === "soilwater") {
    return ramp(model.surface?.availableWaterCapacityMm?.[i] ?? 0, 20, 320, [
      [122, 83, 63],
      [181, 151, 84],
      [102, 153, 99],
      [63, 129, 166],
      [176, 216, 225]
    ]);
  }
  if (mode === "rootdepth") {
    return ramp(model.surface?.rootDepthM?.[i] ?? 0, 0.1, 3.4, [
      [143, 99, 69],
      [182, 151, 82],
      [108, 151, 84],
      [49, 111, 69]
    ]);
  }
  if (mode === "impervious") {
    return ramp(model.surface?.imperviousFraction?.[i] ?? 0, 0, 0.7, [
      [58, 120, 88],
      [154, 158, 92],
      [191, 126, 85],
      [151, 83, 88],
      [89, 79, 89]
    ]);
  }
  if (mode === "runoff") {
    return ramp(model.runoffCoefficient?.[i] ?? 0, 0.05, 0.9, [
      [74, 130, 88],
      [173, 170, 91],
      [202, 130, 74],
      [177, 79, 73],
      [114, 55, 72]
    ]);
  }
  if (mode === "wetness") {
    return ramp(model.wetnessIndex?.[i] ?? 0, 1, 15, [
      [126, 92, 64],
      [174, 153, 83],
      [89, 145, 100],
      [54, 127, 161],
      [185, 222, 229]
    ]);
  }
  if (mode === "wind") {
    return ramp(model.windSpeed?.[i] ?? 0, 0, 32, [
      [64, 91, 99],
      [72, 143, 147],
      [146, 178, 100],
      [223, 185, 84],
      [205, 103, 77]
    ]);
  }
  if (mode === "evapotranspiration") {
    return ramp(model.surface?.actualEvapotranspiration?.[i] ?? 0, 0, 1500, [
      [117, 86, 69],
      [180, 155, 86],
      [109, 159, 106],
      [58, 137, 151],
      [165, 215, 217]
    ]);
  }
  if (mode === "waterbalance") {
    return ramp(model.surface?.waterBalance?.[i] ?? 0, -500, 2600, [
      [134, 78, 67],
      [204, 165, 85],
      [100, 152, 91],
      [62, 130, 163],
      [189, 226, 232]
    ]);
  }

  const seaLevel = params.seaLevel;
  const h = model.height[i];
  const t = clamp((h - seaLevel) / Math.max(1, model.stats.maxElevation - seaLevel), 0, 1);
  return applyTerrainPresetColor(elevationColor(t, model.slope[i]), model, params, i, t);
}

function landscapeBlockAtCell(model, index) {
  const network = model?.landscapeNetwork;
  if (!network?.blocks?.length || !model?.n) return null;
  const x = index % model.n;
  const y = Math.floor(index / model.n);
  const bx = Math.min(network.gridSize - 1, Math.floor(x / Math.max(1, network.blockCellSize)));
  const by = Math.min(network.gridSize - 1, Math.floor(y / Math.max(1, network.blockCellSize)));
  return network.blocks[by * network.gridSize + bx] || null;
}

export function makeRiverGeoJSON(model, params) {
  const features = [];
  for (const segment of model.riverSegments) {
    const from = indexToPoint(segment.from, model.n, model.cellSizeKm);
    const to = indexToPoint(segment.to, model.n, model.cellSizeKm);
    features.push({
      type: "Feature",
      properties: {
        order: segment.order,
        catchment_km2: round(segment.catchment, 3),
        discharge_m3_yr: Math.round(segment.discharge),
        runoff_coefficient: round(model.runoffCoefficient?.[segment.from] ?? 0, 3),
        wind_speed_ms: round(model.windSpeed?.[segment.from] ?? 0, 2),
        lai: round(model.surface?.leafAreaIndex?.[segment.from] ?? 0, 2),
        water_balance_mm_yr: Math.round(model.surface?.waterBalance?.[segment.from] ?? 0),
        ksat_mm_hr: round(model.surface?.hydraulicConductivityMmHr?.[segment.from] ?? 0, 2),
        awc_mm: round(model.surface?.availableWaterCapacityMm?.[segment.from] ?? 0, 1),
        root_depth_m: round(model.surface?.rootDepthM?.[segment.from] ?? 0, 2),
        impervious_fraction: round(model.surface?.imperviousFraction?.[segment.from] ?? 0, 3),
        infiltration_capacity: round(model.surface?.infiltrationCapacity?.[segment.from] ?? 0, 3),
        flow_routing: model.flowRouting || "d8",
        flow_divergence: round(model.flowDivergence?.[segment.from] ?? 0, 2),
        flow_velocity_ms: round(model.hydraulics?.flowVelocity?.[segment.from] ?? 0, 3),
        channel_width_m: round(model.hydraulics?.channelWidthM?.[segment.from] ?? 0, 2),
        channel_depth_m: round(model.hydraulics?.channelDepthM?.[segment.from] ?? 0, 2),
        shear_stress_pa: round(model.hydraulics?.shearStressPa?.[segment.from] ?? 0, 2),
        stream_power_w_m2: round(model.hydraulics?.streamPowerWm2?.[segment.from] ?? 0, 2),
        sediment_transport_index: round(model.hydraulics?.sedimentTransportIndex?.[segment.from] ?? 0, 3),
        erosion_risk: round(model.hydraulics?.erosionRisk?.[segment.from] ?? 0, 3),
        deposition_risk: round(model.hydraulics?.depositionRisk?.[segment.from] ?? 0, 3),
        source: segment.source || "modeled",
        flowline_constrained: Boolean(segment.flowlineConstrained),
        flowline_name: segment.flowlineName || null,
        flowline_source_id: segment.flowlineSourceId || null,
        landcover: (LAND_COVER[model.surface?.landCover?.[segment.from] ?? 0] || LAND_COVER[0]).code,
        soil_hsg: (SOIL_GROUPS[model.surface?.soilGroup?.[segment.from] ?? 0] || SOIL_GROUPS[0]).code
      },
      geometry: {
        type: "LineString",
        coordinates: [
          [round(from.xKm, 4), round(from.yKm, 4)],
          [round(to.xKm, 4), round(to.yKm, 4)]
        ]
      }
    });
  }
  return {
    type: "FeatureCollection",
    name: "GeoLab 128 river network",
    crs: {
      type: "name",
      properties: { name: "local-128km-square" }
    },
    features
  };
}

