export function buildWatershedDelineation(model, params = {}, options = {}) {
  if (!model?.height?.length || !model.n || !model.receiver || !model.flowAccumulation) {
    throw new Error("A model with computed flow receivers and accumulation is required for watershed delineation");
  }

  const len = model.height.length;
  const outletSelection = resolveWatershedOutlet(model, params, options);
  const outletIndex = outletSelection.index;
  if (!Number.isInteger(outletIndex) || outletIndex < 0 || outletIndex >= len) {
    throw new Error("No valid watershed outlet could be selected");
  }

  const upstreamHead = new Int32Array(len);
  const upstreamNext = new Int32Array(len);
  upstreamHead.fill(-1);
  upstreamNext.fill(-1);
  for (let i = 0; i < len; i += 1) {
    const receiver = model.receiver[i];
    if (receiver >= 0 && receiver < len) {
      upstreamNext[i] = upstreamHead[receiver];
      upstreamHead[receiver] = i;
    }
  }

  const mask = new Uint8Array(len);
  const stack = [outletIndex];
  const cells = [];
  mask[outletIndex] = 1;
  while (stack.length > 0) {
    const index = stack.pop();
    cells.push(index);
    for (let child = upstreamHead[index]; child >= 0; child = upstreamNext[child]) {
      if (!mask[child]) {
        mask[child] = 1;
        stack.push(child);
      }
    }
  }

  const includeCells = options.includeCells !== false;
  const rows = includeCells ? [] : null;
  const seaLevel = Number(params.seaLevel ?? 0);
  const cellAreaKm2 = modelCellSupportAreaKm2(model);
  const cellAreaM2 = cellAreaKm2 * 1_000_000;
  const areaKm2 = cells.length * cellAreaKm2;
  const aoiAreaKm2 = Number(model.areaKm2) || MAP_AREA_KM2;
  const surface = model.surface || {};
  const hazards = model.hazards || {};
  const built = model.infrastructureInfluence || {};
  const boundaryLimit = clampInteger(options.boundaryLimit ?? 2500, 0, 20000, 2500);

  const landcoverCounts = {};
  const soilGroupCounts = {};
  const climateCounts = {};
  const infrastructureTypeCounts = {};
  let landCells = 0;
  let minElevation = Infinity;
  let maxElevation = -Infinity;
  let sumElevation = 0;
  let sumSlope = 0;
  let maxSlope = 0;
  let sumPrecip = 0;
  let sumTemperature = 0;
  let sumWind = 0;
  let sumVegetation = 0;
  let sumLeafArea = 0;
  let sumCanopyHeight = 0;
  let sumImpervious = 0;
  let sumRunoffCoefficient = 0;
  let sumWetness = 0;
  let sumWaterBalance = 0;
  let generatedRunoffAnnualM3 = 0;
  let retainedFlowAnnualM3 = 0;
  let precipitationVolumeM3 = 0;
  let actualEtVolumeM3 = 0;
  let infrastructureSupplyVolumeM3 = 0;
  let infrastructureDemandVolumeM3 = 0;
  let infrastructureAffectedCells = 0;
  let buildingCells = 0;
  let buildingDensitySum = 0;
  let buildingHeightSumM = 0;
  let maxBuildingHeightM = 0;
  let floodHighCells = 0;
  let droughtHighCells = 0;
  let wildfireHighCells = 0;
  let landslideHighCells = 0;
  let compositeHighCells = 0;
  let meanFlood = 0;
  let meanDrought = 0;
  let meanWildfire = 0;
  let meanLandslide = 0;
  let meanCompositeHazard = 0;
  let maxCompositeHazard = 0;
  let minXKm = Infinity;
  let minYKm = Infinity;
  let maxXKm = -Infinity;
  let maxYKm = -Infinity;

  for (const index of cells) {
    const x = index % model.n;
    const y = Math.floor(index / model.n);
    minXKm = Math.min(minXKm, x * model.cellSizeKm);
    minYKm = Math.min(minYKm, y * model.cellSizeKm);
    maxXKm = Math.max(maxXKm, (x + 1) * model.cellSizeKm);
    maxYKm = Math.max(maxYKm, (y + 1) * model.cellSizeKm);
    if (includeCells) rows.push(watershedCellRow(model, index));

    if (model.height[index] <= seaLevel) continue;
    landCells += 1;
    const elevation = model.height[index];
    const slope = model.slope?.[index] ?? 0;
    const precipitation = model.precipitation?.[index] ?? 0;
    const actualEt = surface.actualEvapotranspiration?.[index] ?? 0;
    const flood = hazards.currentFloodHazard?.[index] ?? hazards.floodHazard?.[index] ?? 0;
    const drought = hazards.currentDroughtStress?.[index] ?? hazards.droughtStress?.[index] ?? 0;
    const wildfire = hazards.currentWildfireRisk?.[index] ?? hazards.wildfireRisk?.[index] ?? 0;
    const landslide = hazards.currentLandslideRisk?.[index] ?? hazards.landslideRisk?.[index] ?? 0;
    const composite = hazards.currentHazardIndex?.[index] ?? hazards.hazardIndex?.[index] ?? 0;
    const buildingDensity = built.buildingDensity?.[index] ?? 0;
    const buildingHeightM = Math.max(built.buildingHeightM?.[index] ?? 0, built.landmarkHeightM?.[index] ?? 0);

    minElevation = Math.min(minElevation, elevation);
    maxElevation = Math.max(maxElevation, elevation);
    sumElevation += elevation;
    sumSlope += slope;
    maxSlope = Math.max(maxSlope, slope);
    sumPrecip += precipitation;
    sumTemperature += model.temperature?.[index] ?? 0;
    sumWind += model.windSpeed?.[index] ?? 0;
    sumVegetation += surface.vegetation?.[index] ?? 0;
    sumLeafArea += surface.leafAreaIndex?.[index] ?? 0;
    sumCanopyHeight += surface.canopyHeight?.[index] ?? 0;
    sumImpervious += surface.imperviousFraction?.[index] ?? 0;
    sumRunoffCoefficient += model.runoffCoefficient?.[index] ?? 0;
    sumWetness += model.wetnessIndex?.[index] ?? 0;
    sumWaterBalance += surface.waterBalance?.[index] ?? 0;
    generatedRunoffAnnualM3 += model.localRunoffAnnualM3?.[index] ?? 0;
    retainedFlowAnnualM3 += model.retainedFlowAnnualM3?.[index] ?? 0;
    precipitationVolumeM3 += (precipitation / 1000) * cellAreaM2;
    actualEtVolumeM3 += (actualEt / 1000) * cellAreaM2;
    infrastructureSupplyVolumeM3 += ((built.irrigationMm?.[index] ?? 0) / 1000) * cellAreaM2;
    infrastructureDemandVolumeM3 += ((built.waterDemandMm?.[index] ?? 0) / 1000) * cellAreaM2;
    meanFlood += flood;
    meanDrought += drought;
    meanWildfire += wildfire;
    meanLandslide += landslide;
    meanCompositeHazard += composite;
    maxCompositeHazard = Math.max(maxCompositeHazard, composite);
    if (flood >= 0.65) floodHighCells += 1;
    if (drought >= 0.65) droughtHighCells += 1;
    if (wildfire >= 0.65) wildfireHighCells += 1;
    if (landslide >= 0.65) landslideHighCells += 1;
    if (composite >= 0.65) compositeHighCells += 1;

    const landcover = LAND_COVER[surface.landCover?.[index] ?? 0] || LAND_COVER[0];
    const soil = SOIL_GROUPS[surface.soilGroup?.[index] ?? 0] || SOIL_GROUPS[0];
    const climate = CLIMATES[model.climate?.[index] ?? 0] || CLIMATES[0];
    landcoverCounts[landcover.code] = (landcoverCounts[landcover.code] || 0) + 1;
    soilGroupCounts[soil.code] = (soilGroupCounts[soil.code] || 0) + 1;
    climateCounts[climate.code] = (climateCounts[climate.code] || 0) + 1;

    if (built.mask?.[index]) {
      infrastructureAffectedCells += 1;
      const type = INFRASTRUCTURE_CODE_TYPES[built.typeCode?.[index] || 0] || "custom";
      infrastructureTypeCounts[type] = (infrastructureTypeCounts[type] || 0) + 1;
      if (buildingDensity > 0.02 || buildingHeightM > 1) {
        buildingCells += 1;
        buildingDensitySum += buildingDensity;
        buildingHeightSumM += buildingHeightM;
        maxBuildingHeightM = Math.max(maxBuildingHeightM, buildingHeightM);
      }
    }
  }

  const landAreaKm2 = landCells * cellAreaKm2;
  const outletPoint = indexToPoint(outletIndex, model.n, model.cellSizeKm);
  const referenceAreaKm2 = finiteNumber(model.stats?.calibration?.drainageArea?.referenceAreaKm2);
  const outletFlowAccumulationKm2 = finiteNumber(model.flowAccumulation?.[outletIndex]);
  const outletRunoffAnnualM3 = finiteNumber(model.discharge?.[outletIndex]);
  const boundary = buildWatershedBoundary(mask, model, cells, boundaryLimit);
  const mean = (value, decimals = 4) => (landCells > 0 ? round(value / landCells, decimals) : null);

  return {
    type: "geolab-watershed-delineation",
    displayName: "流域圈定",
    generatedAt: new Date().toISOString(),
    method: "reverse-d8-steepest-receiver-catchment-delineation",
    methodZh: "沿每个格网的D8最陡接收格反向追踪上游贡献区",
    flowRouting: model.flowRouting || params.flowRouting || "d8",
    assumptions: [
      "圈定边界采用D8最陡接收格以获得清晰上游分水岭。",
      model.flowRouting === "dinf"
        ? "当前模型的汇流量可使用D∞连续坡向双接收格分流；本导出的边界仍用D8主接收格表示可审查的主汇水区。"
        : model.flowRouting === "mfd"
          ? "当前模型的汇流量可使用MFD多流向分配；本导出的边界仍用D8主接收格表示可审查的主汇水区。"
          : "当前模型的汇流量与圈定边界均使用D8主接收格。"
    ],
    map: {
      sizeKm: model.sizeKm || MAP_SIZE_KM,
      areaKm2: aoiAreaKm2,
      sourceResolution: `${model.n}x${model.n}`,
      cellSizeKm: model.cellSizeKm,
      cellAreaKm2
    },
    outletSelection,
    outlet: {
      index: outletIndex,
      xKm: round(outletPoint.xKm, 4),
      yKm: round(outletPoint.yKm, 4),
      elevationM: round(model.height[outletIndex], 3),
      catchmentKm2: outletFlowAccumulationKm2 !== null ? round(outletFlowAccumulationKm2, 4) : null,
      reverseD8AreaKm2: round(areaKm2, 4),
      dischargeAnnualM3: outletRunoffAnnualM3 !== null ? round(outletRunoffAnnualM3, 2) : null,
      streamOrder: model.streamOrder?.[outletIndex] ?? 0,
      flowVelocityMs: roundedFinite(model.hydraulics?.flowVelocity?.[outletIndex], 4),
      channelWidthM: roundedFinite(model.hydraulics?.channelWidthM?.[outletIndex], 3),
      channelDepthM: roundedFinite(model.hydraulics?.channelDepthM?.[outletIndex], 4),
      shearStressPa: roundedFinite(model.hydraulics?.shearStressPa?.[outletIndex], 3),
      streamPowerWm2: roundedFinite(model.hydraulics?.streamPowerWm2?.[outletIndex], 3)
    },
    summary: {
      cellCount: cells.length,
      landCellCount: landCells,
      areaKm2: round(areaKm2, 4),
      landAreaKm2: round(landAreaKm2, 4),
      areaFractionOfAoi: ratio(areaKm2, aoiAreaKm2),
      minElevationM: landCells > 0 ? round(minElevation, 3) : null,
      meanElevationM: mean(sumElevation, 3),
      maxElevationM: landCells > 0 ? round(maxElevation, 3) : null,
      meanSlopeDeg: mean(sumSlope, 4),
      maxSlopeDeg: round(maxSlope, 4),
      meanPrecipitationMmYr: mean(sumPrecip, 2),
      meanTemperatureC: mean(sumTemperature, 3),
      meanWindSpeedMs: mean(sumWind, 4),
      meanVegetationFraction: mean(sumVegetation, 5),
      meanLeafAreaIndex: mean(sumLeafArea, 4),
      meanCanopyHeightM: mean(sumCanopyHeight, 3),
      meanImperviousFraction: mean(sumImpervious, 5),
      meanRunoffCoefficient: mean(sumRunoffCoefficient, 5),
      meanWetnessIndex: mean(sumWetness, 5),
      meanWaterBalanceMmYr: mean(sumWaterBalance, 2),
      dominantLandcover: topCountEntry(landcoverCounts, cellAreaKm2),
      dominantSoilGroup: topCountEntry(soilGroupCounts, cellAreaKm2),
      dominantClimate: topCountEntry(climateCounts, cellAreaKm2),
      landcoverCounts: countEntries(landcoverCounts, cellAreaKm2),
      soilGroupCounts: countEntries(soilGroupCounts, cellAreaKm2),
      climateCounts: countEntries(climateCounts, cellAreaKm2)
    },
    waterBudget: {
      precipitationVolumeM3: round(precipitationVolumeM3, 2),
      actualEvapotranspirationVolumeM3: round(actualEtVolumeM3, 2),
      infrastructureSupplyVolumeM3: round(infrastructureSupplyVolumeM3, 2),
      infrastructureDemandVolumeM3: round(infrastructureDemandVolumeM3, 2),
      generatedRunoffAnnualM3: round(generatedRunoffAnnualM3, 2),
      retainedFlowAnnualM3: round(retainedFlowAnnualM3, 2),
      outletRunoffAnnualM3: outletRunoffAnnualM3 !== null ? round(outletRunoffAnnualM3, 2) : null,
      runoffCaptureRatio: ratio(outletRunoffAnnualM3, generatedRunoffAnnualM3),
      etRatioOfPrecipitation: ratio(actualEtVolumeM3, precipitationVolumeM3)
    },
    hazards: {
      meanFloodHazard: mean(meanFlood, 5),
      meanDroughtStress: mean(meanDrought, 5),
      meanWildfireRisk: mean(meanWildfire, 5),
      meanLandslideRisk: mean(meanLandslide, 5),
      meanCompositeHazard: mean(meanCompositeHazard, 5),
      maxCompositeHazard: round(maxCompositeHazard, 5),
      highFloodAreaKm2: round(floodHighCells * cellAreaKm2, 4),
      highDroughtAreaKm2: round(droughtHighCells * cellAreaKm2, 4),
      highWildfireAreaKm2: round(wildfireHighCells * cellAreaKm2, 4),
      highLandslideAreaKm2: round(landslideHighCells * cellAreaKm2, 4),
      highCompositeHazardAreaKm2: round(compositeHighCells * cellAreaKm2, 4)
    },
    infrastructure: {
      affectedCellCount: infrastructureAffectedCells,
      affectedAreaKm2: round(infrastructureAffectedCells * cellAreaKm2, 4),
      buildingCellCount: buildingCells,
      meanBuildingDensity: buildingCells > 0 ? round(buildingDensitySum / buildingCells, 5) : 0,
      meanBuildingHeightM: buildingCells > 0 ? round(buildingHeightSumM / buildingCells, 3) : 0,
      maxBuildingHeightM: round(maxBuildingHeightM, 3),
      typeCounts: countEntries(infrastructureTypeCounts, cellAreaKm2)
    },
    calibrationComparison: {
      referenceAreaKm2,
      reverseD8AreaBiasPct: pctBias(areaKm2, referenceAreaKm2),
      outletAccumulationBiasPct: pctBias(outletFlowAccumulationKm2, referenceAreaKm2),
      gageLocationStatus: model.stats?.calibration?.gageLocation?.status || null,
      nearestRiverAreaBiasPct: model.stats?.calibration?.gageLocation?.nearestRiverAreaBiasPct ?? null
    },
    bboxKm: {
      west: Number.isFinite(minXKm) ? round(minXKm, 4) : null,
      south: Number.isFinite(minYKm) ? round(minYKm, 4) : null,
      east: Number.isFinite(maxXKm) ? round(maxXKm, 4) : null,
      north: Number.isFinite(maxYKm) ? round(maxYKm, 4) : null
    },
    boundary,
    csvColumns: WATERSHED_COLUMNS,
    cellRows: rows
  };
}

export function buildResearchDataAudit(model, params = {}, context = {}) {
  if (!model?.stats) throw new Error("A computed model with stats is required for research data audit");
  const readiness = model.stats.dataReadiness || null;
  const qualityByKey = new Map((model.stats.externalQuality || []).map((item) => [item.key, item]));
  const readinessById = new Map((readiness?.items || []).map((item) => [item.id, item]));
  const targetCellM = model.cellSizeKm * 1000;
  const uiResolutions = Array.isArray(context.uiResolutions) && context.uiResolutions.length
    ? context.uiResolutions
    : Array.from(SUPPORTED_MODEL_RESOLUTIONS);
  const requirements = [
    ["terrain", "dem", "真实 DEM 地形", true, 0.97],
    ["soil_hydrology", "soilGroup", "土壤 HSG", true, 0.92],
    ["soil_hydrology", "soilHydraulicConductivity", "饱和导水率 Ksat", true, 0.85],
    ["soil_hydrology", "availableWaterCapacity", "有效含水量 AWC", true, 0.85],
    ["soil_hydrology", "rootDepth", "根区深度", false, 0.8],
    ["landcover_vegetation", "landCover", "土地覆盖", true, 0.92],
    ["landcover_vegetation", "vegetation", "植被/NDVI 覆盖", false, 0.85],
    ["landcover_vegetation", "leafAreaIndex", "叶面积指数 LAI", false, 0.8],
    ["landcover_vegetation", "canopyHeight", "冠层高度", false, 0.8],
    ["landcover_vegetation", "imperviousFraction", "不透水面比例", true, 0.85],
    ["meteorology_boundary", "precipitation", "降水边界场", true, 0.9],
    ["meteorology_boundary", "temperature", "温度边界场", true, 0.9],
    ["meteorology_boundary", "windSpeed", "风速边界场", false, 0.75],
    ["meteorology_boundary", "windDirection", "风向边界场", false, 0.75],
    ["hydrology_flowlines", "flowlines", "真实河网 flowline", true, 1],
    ["calibration", "calibration", "观测流量校准", true, 1],
    ["calibration", "dailyHydrograph", "重叠日尺度水文过程", false, 1],
    ["subsurface_geology", "subsurface", "地下钻孔/水位/岩性观测", false, 0.01],
    ["built_environment", "infrastructure", "城镇/乡村/水利设施", true, 1],
    ["scenario_customization", "surfacePatches", "地表/气候自定义情景", false, 1]
  ];

  const layerRows = requirements.map(([group, key, label, required, minCoverage]) => {
    const quality = qualityByKey.get(key);
    const item = readinessById.get(key);
    const sourceCellM = meanCellSizeM(quality?.sourceCellSizeM || quality?.nativeCellSizeM);
    const targetCellFromQuality = meanCellSizeM(quality?.targetCellSizeM) || targetCellM;
    const sourceToTargetRatio = sourceCellM && targetCellFromQuality ? sourceCellM / targetCellFromQuality : null;
    const targetToSourceRatio = sourceCellM && targetCellFromQuality ? targetCellFromQuality / sourceCellM : null;
    const sourceSupportedResolution = sourceCellM ? Math.max(1, Math.floor(((model.sizeKm || MAP_SIZE_KM) * 1000) / sourceCellM)) : null;
    const gapFilledFraction = finiteNumber(quality?.gapFill?.filledFraction);
    const unfilledFraction = finiteNumber(quality?.gapFill?.unfilledFraction);
    const coverage = finiteNumber(quality?.coverage ?? item?.evidence?.coverage);
    const effectiveCoverage = finiteNumber(quality?.effectiveCoverage ?? item?.evidence?.effectiveCoverage ?? coverage);
    const limitingFactor = researchAuditLimitingFactor({
      key,
      item,
      quality,
      required,
      coverage,
      effectiveCoverage,
      minCoverage,
      sourceToTargetRatio,
      gapFilledFraction,
      unfilledFraction
    });
    const nextAction = researchAuditNextAction({
      key,
      label,
      item,
      quality,
      required,
      coverage,
      effectiveCoverage,
      minCoverage,
      sourceToTargetRatio,
      sourceSupportedResolution,
      limitingFactor
    });
    return {
      group,
      key,
      label,
      required,
      status: item?.status || (quality ? "observed-without-readiness-item" : "missing"),
      score: item?.score ?? (quality ? researchAuditFallbackScore(coverage, effectiveCoverage, minCoverage, sourceToTargetRatio) : 0),
      sourceName: quality?.sourceName || item?.evidence?.sourceName || null,
      sourceFormat: quality?.sourceFormat || item?.evidence?.sourceFormat || null,
      crs: quality?.crs || item?.evidence?.crs || null,
      coverage,
      effectiveCoverage,
      sourceCellM,
      targetCellM: targetCellFromQuality,
      sourceToTargetRatio,
      targetToSourceRatio,
      sourceSupportedResolution,
      resampling: quality?.resampling?.interpretation || quality?.resampling?.method || null,
      gapFilledFraction,
      unfilledFraction,
      limitingFactor,
      nextAction
    };
  });

  const requiredRows = layerRows.filter((row) => row.required);
  const missingRequired = requiredRows.filter((row) => row.status === "missing" || row.score < 0.35);
  const weakRequired = requiredRows.filter((row) => row.score >= 0.35 && row.score < 0.85);
  const observedRasterRows = layerRows.filter((row) => Number.isFinite(row.sourceCellM) && Number.isFinite(row.sourceSupportedResolution));
  const requiredObservedRasterRows = requiredRows.filter((row) => Number.isFinite(row.sourceCellM) && Number.isFinite(row.sourceSupportedResolution));
  const limitingLayer = requiredRows
    .slice()
    .sort((a, b) => a.score - b.score || (b.sourceToTargetRatio || 0) - (a.sourceToTargetRatio || 0))[0] || null;
  const coarsestRequired = requiredObservedRasterRows
    .slice()
    .sort((a, b) => (b.sourceCellM || 0) - (a.sourceCellM || 0))[0] || null;
  const sourceLimitedResolution = requiredObservedRasterRows.length
    ? Math.max(1, Math.min(...requiredObservedRasterRows.map((row) => row.sourceSupportedResolution)))
    : null;
  const recommendedUiResolution = sourceLimitedResolution
    ? chooseUiResolution(uiResolutions, sourceLimitedResolution, model.n)
    : model.n;
  const highPrecisionResolution = observedRasterRows.length
    ? Math.max(...observedRasterRows.map((row) => row.sourceSupportedResolution || 0))
    : null;
  const nextActions = dedupeStrings([
    ...missingRequired.map((row) => row.nextAction),
    ...weakRequired.map((row) => row.nextAction),
    ...((readiness?.blockers || []).map((item) => item.nextAction)),
    ...((context.pipelineWarnings || []).slice(0, 12))
  ].filter(Boolean));

  return {
    type: "geolab-research-data-audit",
    displayName: "科研数据适配审计",
    generatedAt: new Date().toISOString(),
    method: "layer-by-layer-source-fidelity-readiness-and-resolution-audit",
    methodZh: "逐层审计真实数据覆盖率、源像元、重采样、缺口填补、校准证据和推荐模型分辨率",
    map: {
      sizeKm: model.sizeKm || MAP_SIZE_KM,
      areaKm2: model.areaKm2 || MAP_AREA_KM2,
      currentResolution: model.n,
      currentCellSizeM: round(targetCellM, 3),
      supportedUiResolutions: uiResolutions
    },
    summary: {
      readinessClass: readiness?.class || "demonstration-only",
      readinessScore: readiness?.score ?? null,
      readinessScorePct: readiness?.scorePct ?? null,
      requiredReadyCount: readiness?.requiredReadyCount ?? requiredRows.filter((row) => row.score >= 0.85).length,
      requiredCount: readiness?.requiredCount ?? requiredRows.length,
      researchBlockerCount: readiness?.researchBlockerCount ?? missingRequired.length + weakRequired.length,
      missingRequiredCount: missingRequired.length,
      weakRequiredCount: weakRequired.length,
      limitingLayer: compactAuditLayer(limitingLayer),
      coarsestRequiredObservedRaster: compactAuditLayer(coarsestRequired),
      sourceLimitedResolution,
      recommendedUiResolution,
      highPrecisionSourceSupportedResolution: highPrecisionResolution,
      cellSourceConfidence: model.stats?.dataConfidence
        ? {
            meanObservedSupport: model.stats.dataConfidence.meanObservedSupport,
            meanObservedSourceCount: model.stats.dataConfidence.meanObservedSourceCount,
            highConfidenceAreaKm2: model.stats.dataConfidence.highConfidenceAreaKm2,
            mixedEvidenceAreaKm2: model.stats.dataConfidence.mixedEvidenceAreaKm2,
            domainFractions: model.stats.dataConfidence.domainFractions
          }
        : null,
      subsurfaceVoxelEvidence: model.stats?.subsurface
        ? {
            meanVoxelObservedSupport: model.stats.subsurface.meanVoxelObservedSupport,
            meanVoxelInferenceReliability: model.stats.subsurface.meanVoxelInferenceReliability,
            meanEngineeringRisk: model.stats.subsurface.meanEngineeringRisk,
            calibratedVoxelCount: model.stats.subsurface.calibratedVoxelCount,
            highConfidenceVoxelCount: model.stats.subsurface.highConfidenceVoxelCount,
            totalGrossVolumeM3: model.stats.subsurface.totalGrossVolumeM3,
            totalSolidVolumeM3: model.stats.subsurface.totalSolidVolumeM3,
            totalPoreVolumeM3: model.stats.subsurface.totalPoreVolumeM3,
            groundwaterVolumeM3: model.stats.subsurface.groundwaterVolumeM3,
            unsaturatedVoidVolumeM3: model.stats.subsurface.unsaturatedVoidVolumeM3,
            saturatedAquiferVolumeM3: model.stats.subsurface.saturatedAquiferVolumeM3,
            highEngineeringRiskVolumeM3: model.stats.subsurface.highEngineeringRiskVolumeM3
          }
        : null,
      subsurfaceCubeLedger: context.subsurfaceCubeLedger
        ? {
            voxelCount: context.subsurfaceCubeLedger.summary?.voxelCount,
            groupCount: context.subsurfaceCubeLedger.summary?.groupCount,
            totalGrossVolumeM3: context.subsurfaceCubeLedger.summary?.totalGrossVolumeM3,
            totalSolidVolumeM3: context.subsurfaceCubeLedger.summary?.totalSolidVolumeM3,
            totalPoreVolumeM3: context.subsurfaceCubeLedger.summary?.totalPoreVolumeM3,
            groundwaterVolumeM3: context.subsurfaceCubeLedger.summary?.groundwaterVolumeM3,
            unsaturatedVoidVolumeM3: context.subsurfaceCubeLedger.summary?.unsaturatedVoidVolumeM3,
            highRiskVolumeM3: context.subsurfaceCubeLedger.summary?.highRiskVolumeM3,
            meanEngineeringRisk: context.subsurfaceCubeLedger.summary?.meanEngineeringRisk,
            reliabilityClass: context.subsurfaceCubeLedger.summary?.reliabilityClass,
            dominantMaterialClass: context.subsurfaceCubeLedger.summary?.dominantMaterialClass?.code || null,
            dominantRiskClass: context.subsurfaceCubeLedger.summary?.dominantRiskClass?.code || null
          }
        : null,
      spatialAlignment: context.spatialAlignmentAudit
        ? {
            referenceKey: context.spatialAlignmentAudit.referenceKey,
            layerCount: context.spatialAlignmentAudit.summary?.layerCount,
            alignedLayerCount: context.spatialAlignmentAudit.summary?.alignedLayerCount,
            warningCount: context.spatialAlignmentAudit.summary?.warningCount,
            stackIntersectionAreaKm2: context.spatialAlignmentAudit.summary?.stackIntersectionAreaKm2,
            stackIntersectionFractionOfTarget: context.spatialAlignmentAudit.summary?.stackIntersectionFractionOfTarget,
            meanCenterOffsetKm: context.spatialAlignmentAudit.summary?.meanCenterOffsetKm,
            maxCenterOffsetKm: context.spatialAlignmentAudit.summary?.maxCenterOffsetKm,
            maxEdgeMismatchKm: context.spatialAlignmentAudit.summary?.maxEdgeMismatchKm,
            minAlignmentScore: context.spatialAlignmentAudit.summary?.minAlignmentScore
          }
        : null,
      subsurfaceTransect: context.subsurfaceTransect
        ? {
            profileId: context.subsurfaceTransect.profileId,
            mode: context.subsurfaceTransect.mode,
            sampleCount: context.subsurfaceTransect.sampleCount,
            layerCount: context.subsurfaceTransect.layerCount,
            rowCount: context.subsurfaceTransect.rowCount || context.subsurfaceTransect.rows?.length || 0,
            lengthKm: context.subsurfaceTransect.lengthKm,
            meanObservedSupport: context.subsurfaceTransect.summary?.meanObservedSupport,
            meanInferenceReliability: context.subsurfaceTransect.summary?.meanInferenceReliability,
            maxEngineeringRisk: context.subsurfaceTransect.summary?.maxEngineeringRisk,
            saturatedAquiferCrossSectionM2: context.subsurfaceTransect.summary?.saturatedAquiferCrossSectionM2,
            highRiskCrossSectionM2: context.subsurfaceTransect.summary?.highRiskCrossSectionM2,
            dominantMaterialClass: context.subsurfaceTransect.summary?.dominantMaterialClass?.code || null,
            dominantRiskClass: context.subsurfaceTransect.summary?.dominantRiskClass?.code || null
          }
        : null,
      interpretation: sourceLimitedResolution
        ? `当前必需真实栅格中最粗源数据约支持 ${sourceLimitedResolution}² 量级；若继续用更高网格，细节会包含上采样成分。`
        : "缺少足够必需真实栅格，当前模型无法证明科研级空间细节。"
    },
    groupScores: readiness?.groupScores || researchAuditGroupScores(layerRows),
    layerRows,
    blockers: readiness?.blockers || missingRequired.concat(weakRequired).map((row) => ({
      id: row.key,
      group: row.group,
      label: row.label,
      status: row.status,
      score: row.score,
      nextAction: row.nextAction
    })),
    nextActions,
    csvColumns: RESEARCH_DATA_AUDIT_COLUMNS,
    notes: [
      "该审计只证明输入数据与当前网格的适配程度，不把浏览器原型认证为工程级水文模型。",
      "若源像元比模型单元更粗，模型可继续运行，但空间细节会受到上采样限制。",
      "科研级结论仍需要真实 DEM、土壤、土地覆盖、气象、河网、人造设施和校准数据的共同证据。"
    ]
  };
}

export function makeResearchDataAuditCSV(audit) {
  const rows = Array.isArray(audit?.layerRows) ? audit.layerRows : [];
  return [
    RESEARCH_DATA_AUDIT_COLUMNS.join(","),
    ...rows.map((row) => RESEARCH_DATA_AUDIT_COLUMNS.map((key) => csvValue(auditCsvCell(row, key))).join(","))
  ].join("\n");
}

export function buildSpatialAlignmentAudit(model, params = {}, options = {}) {
  if (!model?.stats) throw new Error("A computed model with stats is required for spatial alignment audit");
  const qualityRows = Array.isArray(model.stats.externalQuality) ? model.stats.externalQuality : [];
  const targetBounds = Array.isArray(model.targetBounds) ? model.targetBounds : getTargetBounds(params);
  const targetAreaKm2 = boundsAreaKm2(targetBounds) || (Number(model.areaKm2) || MAP_AREA_KM2);
  const targetCenter = boundsCenter(targetBounds);
  const targetCellM = meanCellSizeM(qualityRows.find((row) => row.targetCellSizeM)?.targetCellSizeM) || (Number(model.cellSizeKm) || 1) * 1000;
  const targetCellKm = targetCellM / 1000;
  const referenceKey = options.referenceKey || (qualityRows.some((row) => row.key === "dem") ? "dem" : qualityRows[0]?.key || null);
  const referenceQuality = qualityRows.find((row) => row.key === referenceKey) || null;
  const referenceBounds = normalizeAuditBounds(referenceQuality?.sourceBoundsKm) || targetBounds;
  const rows = qualityRows
    .filter((quality) => normalizeAuditBounds(quality.sourceBoundsKm))
    .map((quality) => spatialAlignmentRow(quality, targetBounds, targetCenter, targetAreaKm2, targetCellKm));
  for (const row of rows) row.referenceKey = referenceKey;
  const pairRows = rows
    .filter((row) => row.key !== referenceKey)
    .map((row) => spatialAlignmentPairRow(row, referenceKey, referenceBounds));
  const stackIntersectionBounds = intersectionBounds(rows.map((row) => row.sourceBoundsKm));
  const stackIntersectionAreaKm2 = boundsAreaKm2(stackIntersectionBounds) || 0;
  const warningCount = rows.reduce((sum, row) => sum + row.warnings.length, 0);
  const meanCenterOffsetKm = rows.reduce((sum, row) => sum + row.centerOffsetKm, 0) / Math.max(1, rows.length);
  const meanAlignmentScore = rows.reduce((sum, row) => sum + row.alignmentScore, 0) / Math.max(1, rows.length);
  const maxCenterOffsetKm = rows.reduce((max, row) => Math.max(max, row.centerOffsetKm), 0);
  const maxEdgeMismatchKm = rows.reduce((max, row) => Math.max(max, row.edgeMismatchKm), 0);
  const minAlignmentScore = rows.reduce((min, row) => Math.min(min, row.alignmentScore), rows.length ? 1 : 0);
  const nextActions = [];
  for (const row of rows) {
    if (row.alignmentScore < 0.85) {
      nextActions.push(`Verify CRS/bounds for ${row.key}; center offset is ${round(row.centerOffsetKm, 3)} km and edge mismatch is ${round(row.edgeMismatchKm, 3)} km.`);
    }
  }
  if (stackIntersectionAreaKm2 < targetAreaKm2 * 0.9) {
    nextActions.push(`Clip or reproject sources to a common AOI; stacked overlap is ${round((stackIntersectionAreaKm2 / Math.max(1e-9, targetAreaKm2)) * 100, 1)}% of target area.`);
  }
  return {
    type: "geolab-spatial-alignment-audit",
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    referenceKey,
    targetBounds,
    targetResolution: `${model.n}x${model.n}`,
    targetCellSizeM: targetCellM,
    columns: SPATIAL_ALIGNMENT_AUDIT_COLUMNS,
    summary: {
      layerCount: rows.length,
      alignedLayerCount: rows.filter((row) => row.alignmentScore >= 0.9).length,
      warningCount,
      targetAreaKm2,
      stackIntersectionBounds,
      stackIntersectionAreaKm2,
      stackIntersectionFractionOfTarget: stackIntersectionAreaKm2 / Math.max(1e-9, targetAreaKm2),
      meanCenterOffsetKm,
      maxCenterOffsetKm,
      maxEdgeMismatchKm,
      meanAlignmentScore,
      minAlignmentScore,
      nextActions: dedupeStrings(nextActions)
    },
    rows,
    pairRows
  };
}

export function makeSpatialAlignmentAuditCSV(audit) {
  const rows = Array.isArray(audit?.rows) ? audit.rows : [];
  return [
    SPATIAL_ALIGNMENT_AUDIT_COLUMNS.join(","),
    ...rows.map((row) => SPATIAL_ALIGNMENT_AUDIT_COLUMNS.map((key) => csvValue(spatialAlignmentCsvCell(row, key))).join(","))
  ].join("\n");
}

export function buildTerrainProcessAudit(model, params = {}, options = {}) {
  if (!model?.stats) throw new Error("A computed model with stats is required for terrain process audit");
  const profile = terrainPresetProcessProfile(params);
  const preset = terrainPresetSummary(params);
  const evidence = terrainProcessEvidenceMetrics(model, params);
  const minExpectedWeight = clamp(Number(options.minExpectedWeight ?? 0.15), 0, 1);
  const processKeys = TERRAIN_PROCESS_NUMERIC_KEYS
    .filter((key) => profile[key] >= minExpectedWeight)
    .sort((a, b) => (profile[b] || 0) - (profile[a] || 0) || a.localeCompare(b));
  const rows = processKeys.map((key) => terrainProcessAuditRow(key, profile[key], evidence, profile));
  const expectedWeightSum = rows.reduce((sum, row) => sum + row.expected_weight, 0);
  const weightedAgreement = expectedWeightSum > 0
    ? rows.reduce((sum, row) => sum + row.agreement_score * row.expected_weight, 0) / expectedWeightSum
    : 0;
  const blockerRows = rows.filter((row) => row.status === "block");
  const warningRows = rows.filter((row) => row.status === "warning");
  const nextActions = dedupeStrings(rows.map((row) => row.next_action).filter(Boolean));
  return {
    type: "geolab-terrain-process-audit",
    schemaVersion: 1,
    displayName: "地貌过程一致性审计",
    generatedAt: new Date().toISOString(),
    method: "terrain-process-signature-dem-hydrology-climate-consistency-audit",
    methodZh: "按地貌预设过程签名，对 DEM 形态、水文、气候、风与材料参数的一致性进行参数化审计",
    map: {
      sizeKm: model.sizeKm || MAP_SIZE_KM,
      areaKm2: model.areaKm2 || MAP_AREA_KM2,
      resolution: model.n,
      cellSizeM: round(model.cellSizeKm * 1000, 3)
    },
    preset,
    processSignature: terrainPresetProcessSummary(params),
    evidence,
    summary: {
      processClass: profile.processClass,
      primaryProcess: profile.primaryProcess,
      dominantFeature: rows[0]?.process_key || "none",
      rowCount: rows.length,
      weightedAgreement: round(weightedAgreement, 5),
      scorePct: round(weightedAgreement * 100, 2),
      consistencyClass: terrainProcessConsistencyClass(weightedAgreement, blockerRows.length, warningRows.length),
      blockerCount: blockerRows.length,
      warningCount: warningRows.length,
      strongestRows: rows.slice(0, 5).map(terrainProcessAuditRowBrief),
      weakRows: rows
        .slice()
        .sort((a, b) => a.agreement_score - b.agreement_score || b.expected_weight - a.expected_weight)
        .slice(0, 5)
        .map(terrainProcessAuditRowBrief),
      nextActions
    },
    columns: TERRAIN_PROCESS_AUDIT_COLUMNS,
    rows,
    notes: [
      "This audit checks internal consistency between the chosen process preset and the generated parametric terrain.",
      "It is not a certified geomorphology, hydrodynamic, coastal, aeolian, glacial, or geotechnical validation.",
      "Research-grade claims still require observed DEM, mapped lithology, hydrology, meteorology, field control, and calibration evidence."
    ]
  };
}

export function makeTerrainProcessAuditCSV(input, options = {}) {
  const report = input?.type === "geolab-terrain-process-audit"
    ? input
    : buildTerrainProcessAudit(input, options.params || {}, options);
  const columns = report?.columns || TERRAIN_PROCESS_AUDIT_COLUMNS;
  return [
    columns.join(","),
    ...((report?.rows || []).map((row) => columns.map((key) => csvValue(row[key])).join(",")))
  ].join("\n");
}

function terrainProcessEvidenceMetrics(model, params = {}) {
  const stats = model.stats || {};
  const hydraulic = stats.hydraulicDiagnostics || {};
  const reliefM = Math.max(0, (stats.maxElevation ?? 0) - (stats.minElevation ?? 0));
  const landAreaKm2 = Math.max(1e-9, (model.areaKm2 || MAP_AREA_KM2) * clamp(stats.landFraction ?? 1, 0, 1));
  const channelFraction = clamp((hydraulic.channelAreaKm2 || 0) / landAreaKm2, 0, 1);
  const highErosionFraction = clamp(hydraulic.highErosionFractionOfLand ?? 0, 0, 1);
  const highDepositionFraction = clamp(hydraulic.highDepositionFractionOfLand ?? 0, 0, 1);
  const meanSlopeNorm = clamp((stats.meanSlope || 0) / 22, 0, 1);
  const roughnessNorm = clamp((stats.meanRoughness || 0) / Math.max(120, (stats.maxRoughness || 800) * 0.42), 0, 1);
  const reliefNorm = clamp(reliefM / Math.max(1200, MAX_TERRAIN_ELEVATION_M * 0.42), 0, 1);
  const wetnessNorm = clamp((stats.meanWetnessIndex || 0) / 16, 0, 1);
  const windNorm = clamp((stats.meanWindSpeed || 0) / 26, 0, 1);
  const precipitationNorm = clamp((stats.meanPrecipitation || 0) / 1800, 0, 1);
  const dryness = clamp((1 - precipitationNorm) * 0.45 + (1 - clamp(params.humidity ?? 0.9, 0, 1.6) / 1.6) * 0.35 + (stats.hazards?.meanDroughtStress || 0) * 0.2, 0, 1);
  const coldness = clamp((8 - (stats.meanTemperature ?? 12)) / 18, 0, 1);
  const lowSlope = 1 - clamp((stats.meanSlope || 0) / 8, 0, 1);
  const vegetationLow = 1 - clamp(stats.meanVegetation ?? 0.5, 0, 1);
  const streamPowerNorm = clamp((hydraulic.meanStreamPowerWm2 || 0) / Math.max(0.1, hydraulic.maxStreamPowerWm2 || 1), 0, 1);
  const erosionNorm = clamp((hydraulic.meanErosionRisk || 0) * 0.55 + highErosionFraction * 0.45, 0, 1);
  const depositionNorm = clamp((hydraulic.meanDepositionRisk || 0) * 0.55 + highDepositionFraction * 0.45, 0, 1);
  const coastalNorm = clamp((Number(params.seaLevel) || 0) / 260, 0, 1) * clamp(1 - Math.abs((stats.landFraction ?? 1) - 0.72) / 0.72, 0, 1);
  const hydrologyNorm = terrainWeightedScore([
    [channelFraction * 3.4, 0.22],
    [wetnessNorm, 0.24],
    [streamPowerNorm, 0.22],
    [erosionNorm, 0.18],
    [depositionNorm, 0.14]
  ]);
  return {
    reliefM: round(reliefM, 3),
    reliefNorm: round(reliefNorm, 6),
    meanSlopeDeg: round(stats.meanSlope || 0, 6),
    meanSlopeNorm: round(meanSlopeNorm, 6),
    meanRoughnessM: round(stats.meanRoughness || 0, 6),
    maxRoughnessM: round(stats.maxRoughness || 0, 6),
    roughnessNorm: round(roughnessNorm, 6),
    meanWetnessIndex: round(stats.meanWetnessIndex || 0, 6),
    wetnessNorm: round(wetnessNorm, 6),
    hydrologyNorm: round(hydrologyNorm, 6),
    channelFraction: round(channelFraction, 6),
    streamPowerNorm: round(streamPowerNorm, 6),
    erosionNorm: round(erosionNorm, 6),
    depositionNorm: round(depositionNorm, 6),
    highErosionFraction: round(highErosionFraction, 6),
    highDepositionFraction: round(highDepositionFraction, 6),
    windNorm: round(windNorm, 6),
    meanWindSpeedMs: round(stats.meanWindSpeed || 0, 6),
    precipitationNorm: round(precipitationNorm, 6),
    meanPrecipitationMm: round(stats.meanPrecipitation || 0, 6),
    meanTemperatureC: round(stats.meanTemperature || 0, 6),
    dryness: round(dryness, 6),
    humidity: round(clamp(params.humidity ?? 0.9, 0, 1.6) / 1.6, 6),
    coldness: round(coldness, 6),
    lowSlope: round(lowSlope, 6),
    vegetationLow: round(vegetationLow, 6),
    permeability: round(clamp(Number(params.permeability ?? 0.28), 0, 1), 6),
    tectonics: round(clamp(Number(params.tectonics ?? 0.58), 0, 1), 6),
    ridgeWeight: round(clamp(Number(params.ridgeWeight ?? 0.56), 0, 1), 6),
    coastalNorm: round(coastalNorm, 6),
    landFraction: round(stats.landFraction ?? 1, 6),
    seaLevelM: round(Number(params.seaLevel) || 0, 3)
  };
}

function terrainProcessAuditRow(key, expectedWeight, evidence, profile) {
  const observedScore = terrainProcessObservedScore(key, evidence, profile);
  const agreementScore = clamp(1 - Math.abs(expectedWeight - observedScore) / Math.max(0.28, expectedWeight), 0, 1);
  const status = terrainProcessAuditStatus(expectedWeight, observedScore, agreementScore);
  return {
    process_key: key,
    process_label: terrainProcessLabel(key),
    expected_weight: round(expectedWeight, 5),
    observed_score: round(observedScore, 5),
    agreement_score: round(agreementScore, 5),
    status,
    evidence: terrainProcessEvidenceText(key, evidence),
    limitation: terrainProcessLimitation(key),
    next_action: terrainProcessNextAction(key, status)
  };
}

function terrainProcessObservedScore(key, evidence, profile) {
  const structural = terrainWeightedScore([
    [evidence.tectonics, 0.34],
    [evidence.ridgeWeight, 0.26],
    [evidence.roughnessNorm, 0.22],
    [evidence.meanSlopeNorm, 0.18]
  ]);
  const hydrology = terrainWeightedScore([
    [evidence.channelFraction * 3.4, 0.22],
    [evidence.wetnessNorm, 0.24],
    [evidence.streamPowerNorm, 0.22],
    [evidence.erosionNorm, 0.18],
    [evidence.depositionNorm, 0.14]
  ]);
  const scores = {
    canyonIncision: terrainWeightedScore([[evidence.roughnessNorm, 0.3], [evidence.meanSlopeNorm, 0.22], [evidence.erosionNorm, 0.24], [evidence.streamPowerNorm, 0.16], [hydrology, 0.08]]),
    slotCanyon: terrainWeightedScore([[evidence.erosionNorm, 0.28], [evidence.roughnessNorm, 0.25], [structural, 0.2], [evidence.dryness, 0.18], [evidence.channelFraction * 3, 0.09]]),
    terraceFrequency: terrainWeightedScore([[structural, 0.34], [evidence.roughnessNorm, 0.24], [evidence.lowSlope, 0.18], [evidence.erosionNorm, 0.14], [evidence.reliefNorm, 0.1]]),
    karstTowerDensity: terrainWeightedScore([[evidence.roughnessNorm, 0.38], [evidence.meanSlopeNorm, 0.24], [structural, 0.18], [evidence.wetnessNorm, 0.12], [evidence.reliefNorm, 0.08]]),
    karstDissolution: terrainWeightedScore([[evidence.permeability, 0.36], [evidence.wetnessNorm, 0.28], [evidence.precipitationNorm, 0.2], [hydrology, 0.16]]),
    floodedKarst: terrainWeightedScore([[evidence.coastalNorm, 0.34], [evidence.wetnessNorm, 0.28], [evidence.permeability, 0.22], [evidence.channelFraction * 3, 0.16]]),
    glacialTrough: terrainWeightedScore([[evidence.reliefNorm, 0.28], [evidence.roughnessNorm, 0.24], [evidence.coldness, 0.24], [evidence.meanSlopeNorm, 0.16], [hydrology, 0.08]]),
    cirqueDensity: terrainWeightedScore([[evidence.coldness, 0.3], [evidence.roughnessNorm, 0.28], [evidence.meanSlopeNorm, 0.22], [evidence.reliefNorm, 0.2]]),
    volcanicCone: terrainWeightedScore([[evidence.reliefNorm, 0.34], [evidence.meanSlopeNorm, 0.22], [evidence.tectonics, 0.28], [structural, 0.16]]),
    calderaStrength: terrainWeightedScore([[evidence.tectonics, 0.32], [evidence.reliefNorm, 0.22], [evidence.roughnessNorm, 0.22], [structural, 0.24]]),
    deltaDistributary: terrainWeightedScore([[evidence.lowSlope, 0.3], [evidence.wetnessNorm, 0.24], [evidence.channelFraction * 3.4, 0.18], [evidence.depositionNorm, 0.2], [evidence.coastalNorm, 0.08]]),
    braidedChannel: terrainWeightedScore([[evidence.depositionNorm, 0.3], [evidence.channelFraction * 3.4, 0.24], [evidence.lowSlope, 0.2], [hydrology, 0.18], [evidence.reliefNorm, 0.08]]),
    duneField: terrainWeightedScore([[evidence.windNorm, 0.34], [evidence.dryness, 0.3], [1 - evidence.wetnessNorm, 0.14], [evidence.vegetationLow, 0.14], [profile.aeolianAlignmentDeg == null ? 0.35 : 0.75, 0.08]]),
    fjordTrough: terrainWeightedScore([[evidence.reliefNorm, 0.28], [evidence.coastalNorm, 0.26], [evidence.roughnessNorm, 0.18], [evidence.coldness, 0.18], [hydrology, 0.1]]),
    danxiaStrata: terrainWeightedScore([[structural, 0.34], [evidence.roughnessNorm, 0.22], [evidence.dryness, 0.18], [evidence.erosionNorm, 0.14], [evidence.reliefNorm, 0.12]]),
    loessGully: terrainWeightedScore([[evidence.erosionNorm, 0.34], [evidence.dryness, 0.24], [evidence.meanSlopeNorm, 0.16], [evidence.vegetationLow, 0.14], [hydrology, 0.12]]),
    badlandsRill: terrainWeightedScore([[evidence.erosionNorm, 0.34], [evidence.dryness, 0.24], [evidence.roughnessNorm, 0.18], [evidence.vegetationLow, 0.16], [structural, 0.08]]),
    coastalAbrasion: terrainWeightedScore([[evidence.coastalNorm, 0.4], [evidence.meanSlopeNorm, 0.18], [evidence.roughnessNorm, 0.16], [evidence.hydrologyNorm || hydrology, 0.1], [evidence.reliefNorm, 0.16]]),
    travertineTerrace: terrainWeightedScore([[evidence.lowSlope, 0.24], [evidence.permeability, 0.22], [evidence.wetnessNorm, 0.2], [evidence.depositionNorm, 0.18], [hydrology, 0.16]]),
    carbonatePool: terrainWeightedScore([[evidence.wetnessNorm, 0.28], [evidence.permeability, 0.26], [evidence.lowSlope, 0.2], [evidence.meanTemperatureC > 10 ? 0.72 : 0.42, 0.12], [evidence.depositionNorm, 0.14]]),
    hydrothermalSinter: terrainWeightedScore([[evidence.permeability, 0.24], [evidence.wetnessNorm, 0.22], [evidence.tectonics, 0.22], [evidence.meanTemperatureC > 4 ? 0.68 : 0.45, 0.12], [structural, 0.12], [hydrology, 0.08]]),
    engineeredTerrace: terrainWeightedScore([[structural, 0.28], [evidence.meanSlopeNorm, 0.2], [evidence.roughnessNorm, 0.18], [hydrology, 0.16], [evidence.permeability, 0.1], [evidence.reliefNorm, 0.08]]),
    columnarJointing: terrainWeightedScore([[evidence.tectonics, 0.28], [structural, 0.26], [evidence.coastalNorm, 0.18], [evidence.roughnessNorm, 0.14], [evidence.meanSlopeNorm, 0.08], [evidence.humidity ?? evidence.wetnessNorm, 0.06]]),
    evaporiteCrust: terrainWeightedScore([[evidence.dryness, 0.34], [evidence.lowSlope, 0.24], [1 - evidence.wetnessNorm, 0.16], [evidence.depositionNorm, 0.12], [evidence.vegetationLow, 0.08], [evidence.windNorm, 0.06]]),
    lowReliefBasin: terrainWeightedScore([[evidence.lowSlope, 0.32], [1 - evidence.reliefNorm, 0.24], [1 - evidence.roughnessNorm, 0.18], [evidence.depositionNorm, 0.12], [evidence.dryness, 0.08], [evidence.structuralBasin ?? (1 - structural), 0.06]]),
    hangingValleyWaterfall: terrainWeightedScore([[evidence.reliefNorm, 0.24], [evidence.roughnessNorm, 0.2], [evidence.wetnessNorm, 0.16], [evidence.coldness, 0.12], [hydrology, 0.14], [structural, 0.14]]),
    hoodooPillarDensity: terrainWeightedScore([[evidence.roughnessNorm, 0.28], [evidence.meanSlopeNorm, 0.22], [structural, 0.2], [evidence.erosionNorm, 0.16], [evidence.dryness, 0.08], [evidence.coldness, 0.06]]),
    frostWedging: terrainWeightedScore([[evidence.coldness, 0.32], [evidence.wetnessNorm, 0.18], [evidence.roughnessNorm, 0.18], [evidence.meanSlopeNorm, 0.14], [evidence.reliefNorm, 0.1], [evidence.erosionNorm, 0.08]]),
    amphitheaterErosion: terrainWeightedScore([[evidence.erosionNorm, 0.28], [evidence.roughnessNorm, 0.24], [evidence.meanSlopeNorm, 0.18], [structural, 0.14], [hydrology, 0.1], [evidence.dryness, 0.06]]),
    seaStackIsolation: terrainWeightedScore([[evidence.coastalNorm, 0.34], [evidence.roughnessNorm, 0.2], [evidence.meanSlopeNorm, 0.16], [structural, 0.16], [evidence.reliefNorm, 0.1], [hydrology, 0.04]]),
    waveUndercut: terrainWeightedScore([[evidence.coastalNorm, 0.36], [evidence.meanSlopeNorm, 0.18], [evidence.roughnessNorm, 0.16], [evidence.hydrologyNorm || hydrology, 0.14], [evidence.erosionNorm, 0.1], [evidence.reliefNorm, 0.06]]),
    coastalRetreat: terrainWeightedScore([[evidence.coastalNorm, 0.3], [evidence.erosionNorm, 0.22], [evidence.roughnessNorm, 0.18], [evidence.meanSlopeNorm, 0.12], [structural, 0.1], [evidence.vegetationLow, 0.08]]),
    sandstonePillarIsolation: terrainWeightedScore([[evidence.roughnessNorm, 0.3], [evidence.meanSlopeNorm, 0.22], [structural, 0.22], [evidence.reliefNorm, 0.14], [hydrology, 0.08], [evidence.permeability, 0.04]]),
    jointControlledPillar: terrainWeightedScore([[structural, 0.36], [evidence.ridgeWeight, 0.2], [evidence.roughnessNorm, 0.18], [evidence.meanSlopeNorm, 0.14], [evidence.tectonics, 0.12]]),
    caprockProtection: terrainWeightedScore([[structural, 0.28], [evidence.roughnessNorm, 0.22], [evidence.lowSlope, 0.18], [evidence.reliefNorm, 0.14], [evidence.erosionNorm, 0.1], [evidence.dryness, 0.08]]),
    structuralControl: structural,
    hydrologyCoupling: hydrology
  };
  return clamp(scores[key] ?? 0, 0, 1);
}

function terrainWeightedScore(pairs) {
  let total = 0;
  let weight = 0;
  for (const [value, w] of pairs) {
    const nextWeight = Math.max(0, Number(w) || 0);
    total += clamp(Number(value) || 0, 0, 1) * nextWeight;
    weight += nextWeight;
  }
  return weight > 0 ? clamp(total / weight, 0, 1) : 0;
}

function terrainProcessAuditStatus(expectedWeight, observedScore, agreementScore) {
  if (expectedWeight >= 0.55 && observedScore < 0.28) return "block";
  if (agreementScore >= 0.72 && observedScore >= 0.34) return "pass";
  if (agreementScore >= 0.46 || observedScore >= 0.42) return "warning";
  return "block";
}

function terrainProcessConsistencyClass(weightedAgreement, blockerCount, warningCount) {
  if (blockerCount > 0 && weightedAgreement < 0.52) return "process-inconsistent";
  if (weightedAgreement >= 0.76 && blockerCount === 0) return warningCount ? "strong-with-warnings" : "strong";
  if (weightedAgreement >= 0.56) return "moderate";
  return "weak";
}

function terrainProcessLabel(key) {
  const labels = {
    canyonIncision: "fluvial canyon incision",
    slotCanyon: "slot canyon narrowing",
    terraceFrequency: "terrace or bench frequency",
    karstTowerDensity: "karst tower density",
    karstDissolution: "karst dissolution",
    floodedKarst: "flooded karst / drowned towers",
    glacialTrough: "glacial trough",
    cirqueDensity: "cirque density",
    volcanicCone: "volcanic cone construction",
    calderaStrength: "caldera or crater expression",
    deltaDistributary: "delta distributary network",
    braidedChannel: "braided channel / outwash",
    duneField: "aeolian dune field",
    fjordTrough: "fjord trough",
    danxiaStrata: "danxia / stratified mesa",
    loessGully: "loess gully dissection",
    badlandsRill: "badlands rill erosion",
    coastalAbrasion: "coastal abrasion",
    travertineTerrace: "travertine terrace precipitation",
    carbonatePool: "carbonate thermal pool",
    hydrothermalSinter: "hydrothermal sinter / geyser basin",
    engineeredTerrace: "engineered terrace drainage",
    columnarJointing: "basalt columnar jointing",
    evaporiteCrust: "evaporite salt-crust formation",
    lowReliefBasin: "closed low-relief basin",
    hangingValleyWaterfall: "hanging-valley waterfall system",
    hoodooPillarDensity: "hoodoo pillar density",
    frostWedging: "freeze-thaw frost wedging",
    amphitheaterErosion: "amphitheater headward erosion",
    seaStackIsolation: "limestone sea-stack isolation",
    waveUndercut: "wave undercut notch",
    coastalRetreat: "coastal cliff retreat",
    sandstonePillarIsolation: "quartz-sandstone pillar isolation",
    jointControlledPillar: "joint-controlled sandstone pillar",
    caprockProtection: "caprock protection",
    structuralControl: "structural control",
    hydrologyCoupling: "hydrology coupling"
  };
  return labels[key] || key;
}

function terrainProcessEvidenceText(key, evidence) {
  const common = `slope=${round(evidence.meanSlopeDeg, 3)}deg; roughness=${round(evidence.meanRoughnessM, 2)}m; wetness=${round(evidence.meanWetnessIndex, 3)}; channelFraction=${round(evidence.channelFraction, 4)}; erosion=${round(evidence.erosionNorm, 3)}`;
  if (key === "duneField") return `${common}; wind=${round(evidence.meanWindSpeedMs, 2)}m/s; dryness=${round(evidence.dryness, 3)}`;
  if (key === "glacialTrough" || key === "cirqueDensity" || key === "fjordTrough") return `${common}; coldness=${round(evidence.coldness, 3)}; relief=${round(evidence.reliefM, 1)}m`;
  if (key === "coastalAbrasion" || key === "floodedKarst") return `${common}; coastal=${round(evidence.coastalNorm, 3)}; seaLevel=${round(evidence.seaLevelM, 1)}m; landFraction=${round(evidence.landFraction, 3)}`;
  if (key === "karstDissolution" || key === "karstTowerDensity") return `${common}; permeability=${round(evidence.permeability, 3)}; precipitation=${round(evidence.meanPrecipitationMm, 1)}mm`;
  if (key === "travertineTerrace" || key === "carbonatePool") return `${common}; permeability=${round(evidence.permeability, 3)}; deposition=${round(evidence.depositionNorm, 3)}; temperature=${round(evidence.meanTemperatureC, 1)}C`;
  if (key === "hydrothermalSinter") return `${common}; permeability=${round(evidence.permeability, 3)}; tectonics=${round(evidence.tectonics, 3)}; temperature=${round(evidence.meanTemperatureC, 1)}C`;
  if (key === "engineeredTerrace") return `${common}; structural=${round(evidence.tectonics * 0.55 + evidence.ridgeWeight * 0.45, 3)}; permeability=${round(evidence.permeability, 3)}; relief=${round(evidence.reliefM, 1)}m`;
  if (key === "columnarJointing") return `${common}; tectonics=${round(evidence.tectonics, 3)}; coastal=${round(evidence.coastalNorm, 3)}; relief=${round(evidence.reliefM, 1)}m`;
  if (key === "evaporiteCrust") return `${common}; dryness=${round(evidence.dryness, 3)}; lowSlope=${round(evidence.lowSlope, 3)}; vegetationLow=${round(evidence.vegetationLow, 3)}`;
  if (key === "lowReliefBasin") return `${common}; relief=${round(evidence.reliefM, 1)}m; lowSlope=${round(evidence.lowSlope, 3)}; deposition=${round(evidence.depositionNorm, 3)}`;
  if (key === "hangingValleyWaterfall") return `${common}; relief=${round(evidence.reliefM, 1)}m; coldness=${round(evidence.coldness, 3)}; hydrology=${round(evidence.hydrologyNorm || evidence.wetnessNorm, 3)}`;
  if (key === "hoodooPillarDensity" || key === "frostWedging" || key === "amphitheaterErosion") return `${common}; coldness=${round(evidence.coldness, 3)}; dryness=${round(evidence.dryness, 3)}; relief=${round(evidence.reliefM, 1)}m`;
  if (key === "seaStackIsolation" || key === "waveUndercut" || key === "coastalRetreat") return `${common}; coastal=${round(evidence.coastalNorm, 3)}; seaLevel=${round(evidence.seaLevelM, 1)}m; landFraction=${round(evidence.landFraction, 3)}`;
  if (key === "sandstonePillarIsolation" || key === "jointControlledPillar" || key === "caprockProtection") return `${common}; structural=${round(evidence.tectonics * 0.55 + evidence.ridgeWeight * 0.45, 3)}; permeability=${round(evidence.permeability, 3)}; relief=${round(evidence.reliefM, 1)}m`;
  return common;
}

function terrainProcessLimitation(key) {
  if (["coastalAbrasion", "fjordTrough", "floodedKarst"].includes(key)) return "coastline geometry is inferred from sea level and land fraction, not a true wave or tidal model";
  if (["duneField"].includes(key)) return "aeolian evidence is based on wind, dryness, vegetation, and preset alignment, not sediment transport";
  if (["glacialTrough", "cirqueDensity"].includes(key)) return "glacial evidence is a climate/topography proxy, not an ice-flow solver";
  if (["karstDissolution", "karstTowerDensity"].includes(key)) return "karst evidence uses permeability, wetness, and morphology proxies, not lithologic field mapping";
  if (["travertineTerrace", "carbonatePool"].includes(key)) return "travertine evidence uses permeability, wetness, temperature, and deposition proxies, not a groundwater geochemistry or spring-discharge solver";
  if (["hydrothermalSinter"].includes(key)) return "hydrothermal evidence uses permeability, wetness, tectonic heat proxy, and basin morphology, not a geothermal reservoir model";
  if (["engineeredTerrace"].includes(key)) return "engineered terrace evidence is a morphologic drainage proxy, not an archaeological site reconstruction";
  if (["columnarJointing"].includes(key)) return "columnar jointing evidence is a volcanic-rock cooling and coastal-morphology proxy, not mapped joint spacing or petrographic validation";
  if (["evaporiteCrust", "lowReliefBasin"].includes(key)) return "evaporite basin evidence uses aridity, low relief, deposition, and shallow-water proxies, not a calibrated lake-balance or brine chemistry model";
  if (["hangingValleyWaterfall"].includes(key)) return "hanging-valley waterfall evidence is inferred from glacial relief, wetness, and trough morphology, not observed waterfall discharge or cliff surveys";
  if (["hoodooPillarDensity", "frostWedging", "amphitheaterErosion"].includes(key)) return "hoodoo evidence uses freeze-thaw climate, slope, roughness, and erosion proxies, not measured joint spacing, lithology, or rockfall chronology";
  if (["seaStackIsolation", "waveUndercut", "coastalRetreat"].includes(key)) return "sea-stack evidence uses sea level, coastline proxy, slope, and roughness, not a coupled wave, tide, cliff-failure, or bathymetric model";
  if (["sandstonePillarIsolation", "jointControlledPillar", "caprockProtection"].includes(key)) return "sandstone pillar evidence uses structural and relief proxies, not mapped joint sets, caprock thickness, or field-calibrated weathering rates";  return "process score is a parametric consistency proxy and must be validated against observed terrain data";
}

function terrainProcessNextAction(key, status) {
  if (status === "pass") return "";
  const actions = {
    duneField: "increase wind/dryness evidence or reduce dune preset strength; add observed sand-field or sediment data for research use",
    karstDissolution: "add lithology/permeability evidence or tune wetness and dissolution parameters",
    karstTowerDensity: "increase tower-scale relief/roughness evidence or reduce tower preset strength",
    canyonIncision: "verify channel incision with DEM/flowline data and tune river threshold, relief, and erosion strength",
    slotCanyon: "verify narrow canyon geometry with higher-resolution DEM or reduce slot-canyon weight",
    coastalAbrasion: "add coastline/bathymetry or reduce coastal abrasion weight",
    glacialTrough: "add glacial landform evidence or reduce cold-relief trough weighting",
    fjordTrough: "add coastline and glacial trough evidence before treating fjord results as research-grade",
    travertineTerrace: "add spring discharge, carbonate chemistry, and high-resolution terrace DEM evidence before research-grade use",
    carbonatePool: "add mapped thermal pools or groundwater geochemistry evidence before treating carbonate pools as calibrated",
    hydrothermalSinter: "add mapped geyser basins, geothermal gradients, sinter deposits, and hydrothermal monitoring before research-grade use",
    engineeredTerrace: "add archaeological terrace geometry, retaining-wall surveys, drainage trenches, and slope-stability observations before treating terraces as calibrated",
    columnarJointing: "add basalt flow boundaries, column spacing surveys, coastal erosion mapping, and lithology before treating columnar jointing as calibrated",
    evaporiteCrust: "add lake-balance, salinity, evaporation, seasonal inundation, and brine chemistry evidence before research-grade salt-flat use",
    lowReliefBasin: "verify closed-basin topography with DEM sinks, playa margin mapping, and sediment-core or hydrologic observations",
    hangingValleyWaterfall: "add observed hanging-valley cliff lines, waterfall discharge, glacial trimlines, and fjord bathymetry before research-grade use",
    hoodooPillarDensity: "add mapped hoodoo spacing, lithology, caprock thickness, freeze-thaw climate records, and rockfall chronology before research-grade use",
    frostWedging: "add frost-day records, moisture availability, lithologic weakness planes, and monitored debris production before treating freeze-thaw erosion as calibrated",
    amphitheaterErosion: "compare amphitheater headwall retreat, rill networks, and talus aprons against high-resolution DEM or reduce hoodoo preset strength",
    seaStackIsolation: "add coastline change, wave-energy exposure, bathymetry, and cliff-retreat surveys before research-grade sea-stack simulation",
    waveUndercut: "verify tidal notch and wave-cut platform geometry with coastal LiDAR, bathymetry, and wave-climate data",
    coastalRetreat: "calibrate cliff retreat with historic shoreline positions, rock strength, storm-wave exposure, and mass-wasting records",
    sandstonePillarIsolation: "add mapped quartz-sandstone pillar spacing, joint orientations, valley incision, and lithology before research-grade use",
    jointControlledPillar: "add surveyed joint sets, fracture density, bedding attitude, and pillar spacing before treating joint control as calibrated",
    caprockProtection: "add caprock thickness, weathering resistance, blockfall evidence, and differential-erosion rates before research-grade use"
  };
  return actions[key] || "compare preset strength against observed DEM, hydrology, climate, and lithology evidence before research-grade use";
}

function terrainProcessAuditRowBrief(row) {
  return {
    processKey: row.process_key,
    expectedWeight: row.expected_weight,
    observedScore: row.observed_score,
    agreementScore: row.agreement_score,
    status: row.status
  };
}

export function buildResearchValidationGateReport(model, params = {}, context = {}) {
  if (!model?.stats) throw new Error("A computed model with stats is required for research validation gates");
  const pipelineWarnings = Array.isArray(context.pipelineWarnings) ? context.pipelineWarnings : [];
  const audit = context.researchDataAudit || buildResearchDataAudit(model, params, { pipelineWarnings });
  const infrastructureAtlas = context.infrastructureImpactAtlas || buildInfrastructureImpactAtlas(model, params);
  const readiness = model.stats.dataReadiness || null;
  const readinessById = new Map((readiness?.items || []).map((item) => [item.id, item]));
  const auditByKey = new Map((audit.layerRows || []).map((row) => [row.key, row]));
  const rows = [];

  rows.push(researchValidationGate({
    group: "overall",
    gateId: "data_readiness_overall",
    label: "整体真实数据就绪度",
    required: true,
    status: readiness?.class === "research-ready-data" ? "pass" : readiness?.class === "calibration-grade" ? "warning" : "block",
    score: readiness?.score ?? 0,
    threshold: "research-ready-data 且无必需输入阻塞项",
    currentValue: `${readiness?.class || "missing"} / ${round((readiness?.score || 0) * 100, 1)}%`,
    evidence: `requiredReady=${readiness?.requiredReadyCount ?? 0}/${readiness?.requiredCount ?? 0}; blockers=${readiness?.researchBlockerCount ?? 0}`,
    nextActionZh: readiness?.blockers?.[0]?.nextAction || "补齐真实 DEM、土壤、土地覆盖、气象、河网、人造设施和校准证据。"
  }));

  const requiredInputKeys = [
    "dem",
    "soilGroup",
    "soilHydraulicConductivity",
    "availableWaterCapacity",
    "landCover",
    "imperviousFraction",
    "precipitation",
    "temperature",
    "flowlines",
    "calibration",
    "infrastructure"
  ];
  for (const key of requiredInputKeys) {
    rows.push(researchValidationInputGate(key, readinessById.get(key), auditByKey.get(key)));
  }

  const calibration = model.stats.calibration || {};
  const advisor = calibration.advisor || {};
  rows.push(researchValidationGate({
    group: "calibration",
    gateId: "calibration_advisor_quality",
    label: "校准顾问质量等级",
    required: true,
    status: advisor.qualityClass === "research-ready" ? "pass" : advisor.qualityClass === "usable-with-caution" ? "warning" : "block",
    score: finiteNumber(advisor.overallScore) ?? 0,
    threshold: "qualityClass=research-ready，或至少谨慎可用且无空间匹配硬伤",
    currentValue: advisor.qualityClass || "not-calibrated",
    evidence: `biasPct=${roundedFinite(calibration.biasPct, 2)}; comparison=${calibration.comparison?.comparisonSource || "none"}; gage=${calibration.gageLocation?.status || "unknown"}`,
    nextActionZh: advisor.recommendedAction || advisor.nextChecks?.[0] || "导入观测流量、站点经纬度和流域面积，先证明站点与模型出口可比。"
  }));

  const hydrograph = calibration.hydrograph || null;
  const hydrographStatus = hydrograph?.status === "ready"
    ? (Number(hydrograph.metrics?.kge) >= 0.3 && Number(hydrograph.metrics?.nse) >= 0 ? "pass" : "warning")
    : "warning";
  rows.push(researchValidationGate({
    group: "calibration",
    gateId: "daily_hydrograph_skill",
    label: "日尺度水文过程拟合",
    required: false,
    status: hydrographStatus,
    score: hydrograph?.status === "ready" ? clamp((Number(hydrograph.metrics?.kge) + 0.2) / 1.2, 0, 1) : 0.35,
    threshold: "KGE >= 0.3 且 NSE >= 0 时可作为过程线初步证据",
    currentValue: hydrograph?.status || "missing",
    evidence: hydrograph?.metrics
      ? `paired=${hydrograph.metrics.pairedCount}; KGE=${hydrograph.metrics.kge}; NSE=${hydrograph.metrics.nse}`
      : "未形成重叠的日尺度气象-流量样本",
    nextActionZh: "导入与流量日期重叠的日尺度气象边界场，用 KGE/NSE 检查过程线形状。"
  }));

  const metBoundary = model.stats.meteorologyBoundary || null;
  rows.push(researchValidationGate({
    group: "meteorology_boundary",
    gateId: "time_varying_boundary_forcing",
    label: "时变气象边界强迫",
    required: false,
    status: metBoundary?.quality?.hasDailyExtremes ? "pass" : "warning",
    score: metBoundary?.quality?.hasDailyExtremes ? 0.92 : metBoundary ? 0.62 : 0.25,
    threshold: "建议导入至少 30 条日尺度气象记录，并包含降水、温度、风速或风向以驱动极端事件",
    currentValue: metBoundary ? `${metBoundary.dailyRecordCount || 0} records / selected=${metBoundary.selectedYear || "none"}` : "missing",
    evidence: metBoundary
      ? `storm=${roundedFinite(metBoundary.hazardMultipliers?.flood, 3)}; drySpell=${roundedFinite(metBoundary.extremes?.maxDrySpellDays, 1)}; windP95=${roundedFinite(metBoundary.extremes?.p95DailyWindSpeedMs, 2)}`
      : "未导入日尺度或网格气象时序",
    nextActionZh: "导入 Daymet/PRISM/ERA5 等与校准期重叠的日尺度边界场，让洪水、干旱、野火和滑坡风险由真实强迫驱动。"
  }));

  const waterBudget = model.stats.waterBudget || {};
  rows.push(researchValidationGate({
    group: "hydrology",
    gateId: "water_budget_closure",
    label: "水量平衡闭合",
    required: true,
    status: waterBudget.closureClass === "tight" ? "pass" : waterBudget.closureClass === "physically-suspect" ? "block" : "warning",
    score: waterBudgetScore(waterBudget),
    threshold: "closureClass=tight；残差绝对值宜低于年输入 20%",
    currentValue: `${waterBudget.closureClass || "missing"} / residual=${roundedFinite(waterBudget.residualPctOfInput, 2)}%`,
    evidence: `P=${roundedFinite(waterBudget.precipitationVolumeM3, 2)}; ET=${roundedFinite(waterBudget.actualEvapotranspirationVolumeM3, 2)}; runoff=${roundedFinite(waterBudget.generatedRunoffAnnualM3, 2)}`,
    nextActionZh: "检查降水、蒸散、取水、蓄滞、地下损失和出口选择，避免用不闭合水量做校准。"
  }));

  rows.push(researchValidationGate({
    group: "hydrology",
    gateId: "flow_routing_method",
    label: "汇流方法与真实河网约束",
    required: true,
    status:
      (model.stats.flowRouting === "mfd" || model.stats.flowRouting === "dinf") &&
      model.stats.externalFlowlines?.constrainedCellCount > 0
        ? "pass"
        : "warning",
    score:
      model.stats.flowRouting === "dinf"
        ? model.stats.externalFlowlines?.constrainedCellCount > 0
          ? 1
          : 0.78
        : model.stats.flowRouting === "mfd"
          ? model.stats.externalFlowlines?.constrainedCellCount > 0
            ? 0.96
            : 0.72
          : 0.52,
    threshold: "建议使用 D∞ 或 MFD 并导入真实 flowline 约束；后续仍可增加二维水动力",
    currentValue: `${model.stats.flowRouting || "d8"} / constrained=${model.stats.externalFlowlines?.constrainedCellCount || 0}`,
    evidence: `flowlineSegments=${model.stats.externalFlowlines?.flowlineRiverSegmentCount || 0}; channelAreaKm2=${roundedFinite(model.stats.hydraulicDiagnostics?.channelAreaKm2, 4)}`,
    nextActionZh: model.stats.externalFlowlines?.constrainedCellCount > 0
      ? "继续用测站和实测河网校核成河阈值、河阶和流速。"
      : "导入 NHDPlus/OSM 等真实河网，并检查 DEM 对齐与成河阈值。"
  }));

  const hazards = model.stats.hazards || {};
  rows.push(researchValidationGate({
    group: "hazard_time",
    gateId: "hazard_and_time_state",
    label: "灾害与时间演化状态",
    required: true,
    status: model.hazards?.hazardIndex && model.stats.timeProgression ? "pass" : "block",
    score: model.hazards?.hazardIndex && model.stats.timeProgression ? 0.86 : 0.2,
    threshold: "需要洪水、干旱、野火、滑坡和当前时间步累积状态",
    currentValue: `${params.currentYear ?? 0}/${params.simulationYears ?? 0} 年`,
    evidence: `meanComposite=${roundedFinite(hazards.meanCompositeHazard, 4)}; highAreaKm2=${roundedFinite(hazards.highCompositeHazardAreaKm2, 4)}`,
    nextActionZh: "用历史灾害记录、遥感扰动或事件水文资料继续校准灾害阈值与时间累积率。"
  }));

  rows.push(researchValidationGate({
    group: "built_environment",
    gateId: "infrastructure_feedback_atlas",
    label: "人造设施环境反馈",
    required: true,
    status: infrastructureAtlas.summary.status === "ready" ? "pass" : "block",
    score: infrastructureAtlas.summary.status === "ready" ? 0.9 : 0.1,
    threshold: "至少需要一个成功映射到网格的人造设施类型",
    currentValue: `${infrastructureAtlas.summary.typeCount || 0} types / ${infrastructureAtlas.summary.affectedAreaKm2 || 0} km2`,
    evidence: `impervious=${roundedFinite(infrastructureAtlas.summary.totalImperviousAreaKm2, 4)} km2; exposure=${roundedFinite(infrastructureAtlas.summary.totalBuiltExposureIndex, 4)}`,
    nextActionZh: infrastructureAtlas.summary.nextActions?.[0] || infrastructureAtlas.summary.noteZh
  }));

  rows.push(researchValidationGate({
    group: "uncertainty",
    gateId: "uncertainty_ensemble_required",
    label: "参数不确定性集合",
    required: false,
    status: "warning",
    score: 0.52,
    threshold: "发布科研结论前需导出集合并检查 P10/P90 包络",
    currentValue: "可导出，但当前门控未绑定最近集合结果",
    evidence: "runUncertaintyEnsemble 支持降水、温度、土壤、水文阈值、植被和设施扰动。",
    nextActionZh: "运行不确定性集合，若径流、校准偏差或水量残差包络过宽，应继续缩小输入与参数不确定性。"
  }));

  const summary = researchValidationSummary(rows, {
    readiness,
    audit,
    infrastructureAtlas,
    pipelineWarnings
  });

  return {
    type: "geolab-research-validation-gate-report",
    displayName: "科研验证门控包",
    generatedAt: new Date().toISOString(),
    method: "evidence-gated-research-readiness-validation",
    methodZh: "用真实数据就绪度、校准、河网、水量闭合、设施反馈、灾害时间状态和不确定性要求逐项门控科研可信度",
    sourceResolution: model ? `${model.n}x${model.n}` : null,
    map: {
      sizeKm: model?.sizeKm || MAP_SIZE_KM,
      areaKm2: model.areaKm2 || MAP_AREA_KM2,
      cellSizeM: model.cellSizeKm ? round(model.cellSizeKm * 1000, 3) : null
    },
    summary,
    columns: RESEARCH_VALIDATION_GATE_COLUMNS,
    gateRows: rows,
    evidence: {
      dataReadiness: readiness
        ? {
            class: readiness.class,
            scorePct: readiness.scorePct,
            requiredReadyCount: readiness.requiredReadyCount,
            requiredCount: readiness.requiredCount,
            researchBlockerCount: readiness.researchBlockerCount
          }
        : null,
      calibration: {
        qualityClass: advisor.qualityClass || null,
        overallScore: advisor.overallScore ?? null,
        biasPct: calibration.biasPct ?? null,
        hydrographStatus: hydrograph?.status || null,
        hydrographMetrics: hydrograph?.metrics || null
      },
      waterBudget: waterBudget || null,
      infrastructureAtlas: infrastructureAtlas.summary,
      pipelineWarnings
    },
    notes: [
      "该门控包用于证明哪些证据已经满足、哪些仍阻塞科研级结论；它不会把缺少真实数据或校准的运行判定为科研完成。",
      "所有 pass 仅代表当前浏览器模型的筛查门槛通过，最终科研或工程结论仍需外部 GIS、水文和气象专业复核。"
    ]
  };
}

export function makeResearchValidationGateCSV(report) {
  const rows = Array.isArray(report?.gateRows) ? report.gateRows : [];
  return [
    RESEARCH_VALIDATION_GATE_COLUMNS.join(","),
    ...rows.map((row) => RESEARCH_VALIDATION_GATE_COLUMNS.map((key) => csvValue(row[key])).join(","))
  ].join("\n");
}

export function makeWatershedCSV(watershed) {
  const rows = Array.isArray(watershed?.cellRows) ? watershed.cellRows : [];
  return [
    WATERSHED_COLUMNS.join(","),
    ...rows.map((row) => WATERSHED_COLUMNS.map((key) => csvValue(row[key])).join(","))
  ].join("\n");
}

function resolveWatershedOutlet(model, params, options) {
  const len = model.height.length;
  const requested = finiteNumber(options.gridIndex);
  if (requested !== null) {
    const index = clampInteger(requested, 0, len - 1, -1);
    return {
      source: "requested-grid-index",
      sourceZh: "用户指定格网出口",
      index,
      requestedGridIndex: requested
    };
  }

  const nearestChannelIndex = finiteNumber(model.stats?.calibration?.gageLocation?.nearestModeledChannel?.nearestCellIndex);
  if (nearestChannelIndex !== null && nearestChannelIndex >= 0 && nearestChannelIndex < len) {
    const index = Math.round(nearestChannelIndex);
    return {
      source: "calibration-nearest-modeled-channel",
      sourceZh: "校准水文站最近模型河道",
      index,
      gageLocationStatus: model.stats?.calibration?.gageLocation?.status || null
    };
  }

  const gageGridIndex = finiteNumber(model.stats?.calibration?.gageLocation?.grid?.index);
  if (gageGridIndex !== null && gageGridIndex >= 0 && gageGridIndex < len) {
    const index = Math.round(gageGridIndex);
    return {
      source: "calibration-gage-grid-cell",
      sourceZh: "校准水文站所在格网",
      index,
      gageLocationStatus: model.stats?.calibration?.gageLocation?.status || null
    };
  }

  const seaLevel = Number(params.seaLevel ?? 0);
  const threshold = Number(params.riverThreshold ?? 0);
  const outletBonusAreaKm2 = Number(model.areaKm2) || MAP_AREA_KM2;
  let bestIndex = -1;
  let bestScore = -Infinity;
  let bestAccumulation = null;
  for (let i = 0; i < len; i += 1) {
    if (model.height[i] <= seaLevel) continue;
    const accumulation = finiteNumber(model.flowAccumulation?.[i]);
    if (accumulation === null) continue;
    const receiver = model.receiver?.[i] ?? -1;
    const flowsToSeaOrEdge = receiver < 0 || model.height[receiver] <= seaLevel;
    const score =
      accumulation +
      (flowsToSeaOrEdge ? outletBonusAreaKm2 * 0.03 : 0) +
      (accumulation >= threshold ? outletBonusAreaKm2 * 0.006 : 0);
    if (score > bestScore) {
      bestScore = score;
      bestIndex = i;
      bestAccumulation = accumulation;
    }
  }

  return {
    source: "maximum-flow-accumulation-cell",
    sourceZh: "最大汇流累积格网",
    index: bestIndex,
    catchmentKm2: bestAccumulation
  };
}

function watershedCellRow(model, index) {
  const landcover = LAND_COVER[model.surface?.landCover?.[index] ?? 0] || LAND_COVER[0];
  const soil = SOIL_GROUPS[model.surface?.soilGroup?.[index] ?? 0] || SOIL_GROUPS[0];
  const climate = CLIMATES[model.climate?.[index] ?? 0] || CLIMATES[0];
  const hazards = model.hazards || {};
  const built = model.infrastructureInfluence || {};
  const point = indexToPoint(index, model.n, model.cellSizeKm);
  return {
    x_km: round(point.xKm, 4),
    y_km: round(point.yKm, 4),
    index,
    elevation_m: round(model.height?.[index] ?? 0, 3),
    slope_deg: round(model.slope?.[index] ?? 0, 4),
    flow_acc_km2: round(model.flowAccumulation?.[index] ?? 0, 5),
    discharge_m3_yr: round(model.discharge?.[index] ?? 0, 2),
    stream_order: model.streamOrder?.[index] ?? 0,
    climate: climate.code,
    landcover: landcover.code,
    soil_hsg: soil.code,
    runoff_coefficient: round(model.runoffCoefficient?.[index] ?? 0, 5),
    impervious_fraction: round(model.surface?.imperviousFraction?.[index] ?? 0, 5),
    vegetation_fraction: round(model.surface?.vegetation?.[index] ?? 0, 5),
    lai: round(model.surface?.leafAreaIndex?.[index] ?? 0, 4),
    canopy_height_m: round(model.surface?.canopyHeight?.[index] ?? 0, 3),
    wetness_index: round(model.wetnessIndex?.[index] ?? 0, 5),
    flood_hazard: round(hazards.currentFloodHazard?.[index] ?? hazards.floodHazard?.[index] ?? 0, 5),
    drought_stress: round(hazards.currentDroughtStress?.[index] ?? hazards.droughtStress?.[index] ?? 0, 5),
    wildfire_risk: round(hazards.currentWildfireRisk?.[index] ?? hazards.wildfireRisk?.[index] ?? 0, 5),
    landslide_risk: round(hazards.currentLandslideRisk?.[index] ?? hazards.landslideRisk?.[index] ?? 0, 5),
    hazard_index: round(hazards.currentHazardIndex?.[index] ?? hazards.hazardIndex?.[index] ?? 0, 5),
    built_type: built.mask?.[index] ? INFRASTRUCTURE_CODE_TYPES[built.typeCode?.[index] || 0] || "custom" : "",
    building_density: round(built.buildingDensity?.[index] ?? 0, 5),
    building_height_m: round(Math.max(built.buildingHeightM?.[index] ?? 0, built.landmarkHeightM?.[index] ?? 0), 3)
  };
}

function buildWatershedBoundary(mask, model, cells, pointLimit) {
  const boundaryIndices = [];
  for (const index of cells) {
    const x = index % model.n;
    const y = Math.floor(index / model.n);
    let boundary = false;
    for (const nb of D8) {
      const nx = x + nb.dx;
      const ny = y + nb.dy;
      if (nx < 0 || ny < 0 || nx >= model.n || ny >= model.n) {
        boundary = true;
        break;
      }
      if (!mask[ny * model.n + nx]) {
        boundary = true;
        break;
      }
    }
    if (boundary) boundaryIndices.push(index);
  }

  const sampled = [];
  if (pointLimit > 0 && boundaryIndices.length > 0) {
    const count = Math.min(pointLimit, boundaryIndices.length);
    for (let i = 0; i < count; i += 1) {
      const sourceIndex = boundaryIndices.length === count
        ? i
        : Math.floor((i / Math.max(1, count - 1)) * (boundaryIndices.length - 1));
      const index = boundaryIndices[sourceIndex];
      const point = indexToPoint(index, model.n, model.cellSizeKm);
      sampled.push({
        index,
        xKm: round(point.xKm, 4),
        yKm: round(point.yKm, 4)
      });
    }
  }

  return {
    type: "sampled-boundary-cells",
    pointCount: boundaryIndices.length,
    sampledPointCount: sampled.length,
    points: sampled,
    note: "Boundary points are sampled watershed-edge cell centers; construct a polygon externally if a topological boundary is required.",
    noteZh: "边界点为抽样后的流域边缘格网中心；如需拓扑面边界，可在GIS中据此重建多边形。"
  };
}

function topCountEntry(counts, cellAreaKm2) {
  return countEntries(counts, cellAreaKm2)[0] || null;
}

function countEntries(counts, cellAreaKm2) {
  return Object.entries(counts)
    .map(([key, cells]) => ({
      key,
      cells,
      areaKm2: round(cells * cellAreaKm2, 4)
    }))
    .sort((a, b) => b.cells - a.cells || String(a.key).localeCompare(String(b.key)));
}

function roundedFinite(value, decimals) {
  const number = finiteNumber(value);
  return number === null ? null : round(number, decimals);
}

function meanCellSizeM(cellSize) {
  if (!cellSize) return null;
  if (Number.isFinite(Number(cellSize))) return Number(cellSize);
  const mean = finiteNumber(cellSize.mean);
  if (mean !== null) return mean;
  const x = finiteNumber(cellSize.x ?? cellSize.width ?? cellSize[0]);
  const y = finiteNumber(cellSize.y ?? cellSize.height ?? cellSize[1]);
  if (x !== null && y !== null) return (Math.abs(x) + Math.abs(y)) / 2;
  return x ?? y;
}

function researchValidationInputGate(key, readinessItem, auditRow) {
  const required = readinessItem?.required ?? auditRow?.required ?? true;
  const score = finiteNumber(readinessItem?.score ?? auditRow?.score) ?? 0;
  const status = score >= 0.85 ? "pass" : required && score < 0.55 ? "block" : "warning";
  const currentBits = [
    readinessItem?.status || auditRow?.status || "missing",
    auditRow?.effectiveCoverage !== null && auditRow?.effectiveCoverage !== undefined ? `coverage=${round(auditRow.effectiveCoverage * 100, 1)}%` : null,
    auditRow?.sourceCellM ? `sourceCell=${round(auditRow.sourceCellM, 2)}m` : null
  ].filter(Boolean);
  return researchValidationGate({
    group: readinessItem?.group || auditRow?.group || "input_data",
    gateId: `input_${key}`,
    label: auditRow?.label || readinessItem?.label || key,
    required,
    status,
    score,
    threshold: required ? "score >= 0.85 且覆盖率/分辨率/校准证据达到科研阈值" : "可选层，score >= 0.7 为较稳妥",
    currentValue: currentBits.join(" / "),
    evidence: researchValidationEvidence(readinessItem, auditRow),
    nextActionZh: auditRow?.nextAction || readinessItem?.nextActions?.[0] || "补充该输入层的真实来源、CRS、范围、单位和质量证据。"
  });
}

function researchValidationEvidence(readinessItem, auditRow) {
  const parts = [];
  if (readinessItem?.evidence?.sourceName || auditRow?.sourceName) parts.push(`source=${readinessItem?.evidence?.sourceName || auditRow?.sourceName}`);
  if (auditRow?.sourceToTargetRatio !== null && auditRow?.sourceToTargetRatio !== undefined) parts.push(`sourceToTarget=${round(auditRow.sourceToTargetRatio, 3)}`);
  if (auditRow?.limitingFactor) parts.push(`limiting=${auditRow.limitingFactor}`);
  if (readinessItem?.score !== undefined) parts.push(`readinessScore=${round(readinessItem.score, 3)}`);
  return parts.join("; ") || "暂无可审查证据";
}

function researchValidationGate(input) {
  const status = input.status || "warning";
  const score = clamp(Number(input.score), 0, 1);
  return {
    group: input.group || "general",
    gate_id: input.gateId || input.id || "gate",
    label: input.label || input.gateId || "Gate",
    required: input.required !== false,
    status,
    severity: researchValidationSeverity(status, input.required !== false),
    score: Number.isFinite(score) ? round(score, 4) : 0,
    threshold: input.threshold || "",
    current_value: input.currentValue ?? "",
    evidence: input.evidence ?? "",
    next_action_zh: input.nextActionZh || ""
  };
}

function researchValidationSeverity(status, required) {
  if (status === "pass") return "ok";
  if (status === "block") return required ? "blocking" : "advisory";
  if (status === "warning") return required ? "major" : "minor";
  return "info";
}

function researchValidationSummary(rows, context) {
  const passRows = rows.filter((row) => row.status === "pass");
  const warningRows = rows.filter((row) => row.status === "warning");
  const blockerRows = rows.filter((row) => row.status === "block" && row.required);
  const optionalBlockers = rows.filter((row) => row.status === "block" && !row.required);
  let weightedScore = 0;
  let weightSum = 0;
  for (const row of rows) {
    const weight = row.required ? 1.45 : 0.55;
    weightedScore += row.score * weight;
    weightSum += weight;
  }
  const score = weightSum > 0 ? weightedScore / weightSum : 0;
  const requiredWarnings = warningRows.filter((row) => row.required);
  const overallClass = researchValidationOverallClass(score, blockerRows.length, requiredWarnings.length);
  return {
    overallClass,
    isResearchDefensible: overallClass === "research-defensible",
    score: round(score, 4),
    scorePct: round(score * 100, 1),
    passCount: passRows.length,
    warningCount: warningRows.length,
    blockerCount: blockerRows.length,
    optionalBlockerCount: optionalBlockers.length,
    requiredGateCount: rows.filter((row) => row.required).length,
    totalGateCount: rows.length,
    dataReadinessClass: context.readiness?.class || null,
    dataReadinessScorePct: context.readiness?.scorePct ?? null,
    infrastructureAtlasStatus: context.infrastructureAtlas?.summary?.status || null,
    pipelineWarningCount: context.pipelineWarnings?.length || 0,
    blockers: blockerRows.slice(0, 12).map(researchValidationGateBrief),
    warnings: warningRows.slice(0, 12).map(researchValidationGateBrief),
    nextActions: dedupeStrings([
      ...blockerRows.map((row) => row.next_action_zh),
      ...requiredWarnings.map((row) => row.next_action_zh),
      ...(context.pipelineWarnings || [])
    ]).slice(0, 16),
    noteZh: overallClass === "research-defensible"
      ? "当前门控未发现必需阻塞项，但仍需外部专业复核后才能发布科研或工程结论。"
      : "当前运行仍存在科研门控阻塞或主要警告，应继续补真实数据、校准与不确定性证据。"
  };
}

function researchValidationOverallClass(score, blockerCount, requiredWarningCount) {
  if (blockerCount === 0 && requiredWarningCount === 0 && score >= 0.86) return "research-defensible";
  if (blockerCount === 0 && score >= 0.72) return "calibration-defensible";
  if (blockerCount <= 3 && score >= 0.48) return "screening-only";
  return "demonstration-only";
}

function researchValidationGateBrief(row) {
  return {
    gateId: row.gate_id,
    group: row.group,
    label: row.label,
    status: row.status,
    score: row.score,
    nextActionZh: row.next_action_zh
  };
}

function researchAuditFallbackScore(coverage, effectiveCoverage, minCoverage, sourceToTargetRatio) {
  const cover = finiteNumber(effectiveCoverage ?? coverage);
  if (cover === null) return 0;
  const coverageScore = clamp(cover / Math.max(0.01, minCoverage), 0, 1);
  const resolutionPenalty =
    sourceToTargetRatio > 6 ? 0.35 :
    sourceToTargetRatio > 3 ? 0.22 :
    sourceToTargetRatio > 1.75 ? 0.12 :
    0;
  return round(clamp(coverageScore - resolutionPenalty, 0, 1), 3);
}

function researchAuditLimitingFactor(input) {
  if (!input.quality && !input.item) return input.required ? "missing-required-source" : "missing-optional-source";
  if (input.effectiveCoverage !== null && input.effectiveCoverage < input.minCoverage) return "insufficient-effective-coverage";
  if (input.coverage !== null && input.coverage < input.minCoverage) return "insufficient-observed-coverage";
  if (input.unfilledFraction !== null && input.unfilledFraction > 0.01) return "unfilled-nodata";
  if (input.gapFilledFraction !== null && input.gapFilledFraction > 0.05) return "gap-filled-data";
  if (input.sourceToTargetRatio !== null && input.sourceToTargetRatio > 6) return "very-coarse-source-upsampled";
  if (input.sourceToTargetRatio !== null && input.sourceToTargetRatio > 1.75) return "coarse-source-upsampled";
  if ((input.quality?.warnings || []).length) return "metadata-or-normalization-warning";
  if (input.item?.score !== undefined && input.item.score < 0.85) return "readiness-score-below-research-threshold";
  return "ready";
}

function researchAuditNextAction(input) {
  if (input.limitingFactor === "missing-required-source") {
    return `导入覆盖 AOI 的${input.label}，并包含 CRS、范围和单位元数据。`;
  }
  if (input.limitingFactor === "missing-optional-source") {
    return `可选增强：导入${input.label}以减少模型推断。`;
  }
  if (input.limitingFactor === "insufficient-effective-coverage" || input.limitingFactor === "insufficient-observed-coverage") {
    const observed = input.effectiveCoverage ?? input.coverage ?? 0;
    return `补齐${input.label}覆盖率：当前 ${round(observed * 100, 1)}%，目标至少 ${round(input.minCoverage * 100, 0)}%。`;
  }
  if (input.limitingFactor === "unfilled-nodata") {
    return `替换${input.label}中未填补 NoData 区域，避免局部模型退回推断值。`;
  }
  if (input.limitingFactor === "gap-filled-data") {
    return `用观测数据替代${input.label}的缺口填补区域，或在质量报告中标明低置信区。`;
  }
  if (input.limitingFactor === "very-coarse-source-upsampled" || input.limitingFactor === "coarse-source-upsampled") {
    const supported = input.sourceSupportedResolution ? `${input.sourceSupportedResolution}²` : "更低";
    return `使用更细的${input.label}源数据，或把模型网格降到约 ${supported} 以内；当前源像元约为模型单元 ${round(input.sourceToTargetRatio, 1)} 倍。`;
  }
  if (input.limitingFactor === "metadata-or-normalization-warning") {
    return input.quality?.warnings?.[0] || `复核${input.label}的 CRS、单位、scale/offset 或范围元数据。`;
  }
  if (input.limitingFactor === "readiness-score-below-research-threshold") {
    return input.item?.nextActions?.[0] || `提高${input.label}证据质量至科研阈值。`;
  }
  return input.item?.nextActions?.[0] || "";
}

function chooseUiResolution(uiResolutions, sourceLimitedResolution, fallback) {
  const sorted = uiResolutions
    .map((value) => Math.round(Number(value)))
    .filter((value) => Number.isFinite(value) && value > 0)
    .sort((a, b) => a - b);
  const supported = sorted.filter((value) => value <= sourceLimitedResolution);
  if (supported.length) return supported[supported.length - 1];
  return sorted[0] || fallback;
}

function compactAuditLayer(row) {
  if (!row) return null;
  return {
    key: row.key,
    label: row.label,
    group: row.group,
    status: row.status,
    score: row.score,
    sourceName: row.sourceName,
    sourceCellM: row.sourceCellM,
    sourceToTargetRatio: row.sourceToTargetRatio,
    limitingFactor: row.limitingFactor,
    nextAction: row.nextAction
  };
}

function researchAuditGroupScores(layerRows) {
  const groups = new Map();
  for (const row of layerRows) {
    const current = groups.get(row.group) || { scoreSum: 0, count: 0, ready: 0 };
    current.scoreSum += Number(row.score) || 0;
    current.count += 1;
    current.ready += row.score >= 0.85 ? 1 : 0;
    groups.set(row.group, current);
  }
  return Object.fromEntries(Array.from(groups.entries()).map(([group, value]) => [group, {
    score: round(value.count ? value.scoreSum / value.count : 0, 3),
    ready: value.ready,
    total: value.count
  }]));
}

function auditCsvCell(row, key) {
  if (key === "coverage") return row.coverage;
  if (key === "effective_coverage") return row.effectiveCoverage;
  if (key === "source_cell_m") return row.sourceCellM;
  if (key === "target_cell_m") return row.targetCellM;
  if (key === "source_to_target_ratio") return row.sourceToTargetRatio;
  if (key === "target_to_source_ratio") return row.targetToSourceRatio;
  if (key === "source_supported_resolution") return row.sourceSupportedResolution;
  if (key === "gap_filled_fraction") return row.gapFilledFraction;
  if (key === "unfilled_fraction") return row.unfilledFraction;
  if (key === "next_action") return row.nextAction;
  return row[key];
}

function spatialAlignmentRow(quality, targetBounds, targetCenter, targetAreaKm2, targetCellKm) {
  const sourceBoundsKm = normalizeAuditBounds(quality.sourceBoundsKm);
  const sourceCenter = boundsCenter(sourceBoundsKm);
  const centerOffsetKm = Math.hypot(sourceCenter.x - targetCenter.x, sourceCenter.y - targetCenter.y);
  const edgeMismatchKm = Math.max(
    Math.abs(sourceBoundsKm[0] - targetBounds[0]),
    Math.abs(sourceBoundsKm[1] - targetBounds[1]),
    Math.abs(sourceBoundsKm[2] - targetBounds[2]),
    Math.abs(sourceBoundsKm[3] - targetBounds[3])
  );
  const overlapAreaKm2 = boundsOverlapAreaKm2(sourceBoundsKm, targetBounds) || 0;
  const overlapFractionOfTarget = overlapAreaKm2 / Math.max(1e-9, targetAreaKm2);
  const sourceCellM = meanCellSizeM(quality.sourceCellSizeM || quality.nativeCellSizeM);
  const targetCellM = meanCellSizeM(quality.targetCellSizeM);
  const cellSizeRatioToTarget = sourceCellM && targetCellM ? sourceCellM / targetCellM : null;
  const centerPenalty = Math.min(0.25, centerOffsetKm / Math.max(0.001, targetCellKm * 16));
  const edgePenalty = Math.min(0.15, edgeMismatchKm / Math.max(0.001, targetCellKm * 16));
  const coarsePenalty = cellSizeRatioToTarget && cellSizeRatioToTarget > 4 ? Math.min(0.14, (cellSizeRatioToTarget - 4) * 0.025) : 0;
  const warningPenalty = Math.min(0.08, (quality.warnings?.length || 0) * 0.015);
  const alignmentScore = clamp(overlapFractionOfTarget - centerPenalty - edgePenalty - coarsePenalty - warningPenalty, 0, 1);
  const warnings = [...(quality.warnings || [])];
  if (centerOffsetKm > targetCellKm * 1.5) warnings.push(`center offset ${round(centerOffsetKm, 3)} km exceeds 1.5 target cells`);
  if (edgeMismatchKm > targetCellKm * 1.5) warnings.push(`source bounds edge mismatch ${round(edgeMismatchKm, 3)} km exceeds 1.5 target cells`);
  if (overlapFractionOfTarget < 0.98) warnings.push(`source overlaps ${round(overlapFractionOfTarget * 100, 1)}% of target AOI`);
  if (cellSizeRatioToTarget && cellSizeRatioToTarget > 3) warnings.push(`source cell is ${round(cellSizeRatioToTarget, 2)}x target cell`);
  return {
    key: quality.key,
    sourceName: quality.sourceName,
    crs: quality.crs,
    crsInterpretation: quality.crsInterpretation,
    sourceBoundsKm: sourceBoundsKm.map((value) => round(value, 6)),
    targetBoundsKm: targetBounds.map((value) => round(value, 6)),
    sourceCenterKm: { x: round(sourceCenter.x, 6), y: round(sourceCenter.y, 6) },
    targetCenterKm: { x: round(targetCenter.x, 6), y: round(targetCenter.y, 6) },
    centerOffsetKm: round(centerOffsetKm, 6),
    edgeMismatchKm: round(edgeMismatchKm, 6),
    overlapAreaKm2: round(overlapAreaKm2, 6),
    overlapFractionOfTarget: round(overlapFractionOfTarget, 6),
    cellSizeRatioToTarget: Number.isFinite(cellSizeRatioToTarget) ? round(cellSizeRatioToTarget, 6) : null,
    alignmentScore: round(alignmentScore, 6),
    warnings: dedupeStrings(warnings)
  };
}

function spatialAlignmentPairRow(row, referenceKey, referenceBounds) {
  const referenceCenter = boundsCenter(referenceBounds);
  const sourceCenter = boundsCenter(row.sourceBoundsKm);
  const referenceArea = boundsAreaKm2(referenceBounds) || 0;
  const overlapAreaKm2 = boundsOverlapAreaKm2(row.sourceBoundsKm, referenceBounds) || 0;
  return {
    key: row.key,
    referenceKey,
    centerOffsetKm: round(Math.hypot(sourceCenter.x - referenceCenter.x, sourceCenter.y - referenceCenter.y), 6),
    edgeMismatchKm: round(Math.max(
      Math.abs(row.sourceBoundsKm[0] - referenceBounds[0]),
      Math.abs(row.sourceBoundsKm[1] - referenceBounds[1]),
      Math.abs(row.sourceBoundsKm[2] - referenceBounds[2]),
      Math.abs(row.sourceBoundsKm[3] - referenceBounds[3])
    ), 6),
    overlapAreaKm2: round(overlapAreaKm2, 6),
    overlapFractionOfReference: round(overlapAreaKm2 / Math.max(1e-9, referenceArea), 6)
  };
}

function spatialAlignmentCsvCell(row, key) {
  if (key === "reference_key") return row.referenceKey;
  if (key === "source_name") return row.sourceName;
  if (key === "crs_interpretation") return row.crsInterpretation;
  if (key === "source_bounds_km") return row.sourceBoundsKm?.join("|");
  if (key === "target_bounds_km") return row.targetBoundsKm?.join("|");
  if (key === "center_offset_km") return row.centerOffsetKm;
  if (key === "edge_mismatch_km") return row.edgeMismatchKm;
  if (key === "overlap_area_km2") return row.overlapAreaKm2;
  if (key === "overlap_fraction_of_target") return row.overlapFractionOfTarget;
  if (key === "cell_size_ratio_to_target") return row.cellSizeRatioToTarget;
  if (key === "alignment_score") return row.alignmentScore;
  if (key === "warnings") return row.warnings?.join("|") || "";
  return row[key];
}

function normalizeAuditBounds(bounds) {
  if (!Array.isArray(bounds) || bounds.length < 4) return null;
  const values = bounds.slice(0, 4).map(Number);
  return values.every(Number.isFinite) ? values : null;
}

function boundsCenter(bounds) {
  return {
    x: (Number(bounds?.[0]) + Number(bounds?.[2])) / 2,
    y: (Number(bounds?.[1]) + Number(bounds?.[3])) / 2
  };
}

function intersectionBounds(boundsList) {
  const valid = boundsList.map(normalizeAuditBounds).filter(Boolean);
  if (!valid.length) return null;
  const bounds = [
    Math.max(...valid.map((item) => item[0])),
    Math.max(...valid.map((item) => item[1])),
    Math.min(...valid.map((item) => item[2])),
    Math.min(...valid.map((item) => item[3]))
  ];
  if (bounds[2] <= bounds[0] || bounds[3] <= bounds[1]) return null;
  return bounds.map((value) => round(value, 6));
}

export function makeGridCSV(model) {
  const lines = [
    "x_km,y_km,elevation_m,slope_deg,aspect_deg,curvature_1km,tpi_m,roughness_m,wetness_index,precip_mm_yr,temp_c,wind_speed_ms,wind_from_deg,wind_exposure,data_confidence,observed_source_count,data_source_mask,customized_support,climate,landcover,soil_hsg,vegetation_fraction,canopy_height_m,lai,vegetation_type,vegetation_resilience,biomass_carbon_kg_m2,canopy_roughness_m,ksat_mm_hr,awc_mm,root_depth_m,impervious_fraction,infiltration_capacity,root_cohesion,actual_et_mm_yr,water_balance_mm_yr,curve_number,runoff_coefficient,flow_acc_km2,discharge_index,flow_routing,flow_divergence,flow_velocity_ms,channel_width_m,channel_depth_m,shear_stress_pa,stream_power_w_m2,sediment_transport_index,erosion_risk,deposition_risk,flood_hazard,flood_depth_m,drought_stress,wildfire_risk,landslide_risk,hazard_index,cumulative_erosion_m,projected_vegetation_fraction,water_table_depth_m,bedrock_depth_m,aquifer_potential,fracture_risk,liquefaction_risk,subsurface_storage_mm"
  ];
  for (let y = 0; y < model.n; y += 1) {
    for (let x = 0; x < model.n; x += 1) {
      const i = y * model.n + x;
      lines.push(
        [
          round(x * model.cellSizeKm, 4),
          round(y * model.cellSizeKm, 4),
          Math.round(model.height[i]),
          round(model.slope[i], 2),
          round(model.aspect?.[i] ?? 0, 1),
          round(model.terrainDiagnostics?.curvature?.[i] ?? 0, 5),
          round(model.terrainDiagnostics?.tpi?.[i] ?? 0, 2),
          round(model.terrainDiagnostics?.roughness?.[i] ?? 0, 2),
          round(model.wetnessIndex?.[i] ?? 0, 3),
          Math.round(model.precipitation[i]),
          round(model.temperature[i], 2),
          round(model.windSpeed?.[i] ?? 0, 2),
          round(model.windDirection?.[i] ?? 0, 1),
          round(model.windExposure?.[i] ?? 0, 3),
          round(model.dataConfidence?.observedSupport?.[i] ?? 0, 4),
          model.dataConfidence?.sourceCount?.[i] ?? 0,
          dataSourceCodes(model.dataConfidence?.sourceMask?.[i] ?? 0).join("|"),
          round(model.dataConfidence?.customizedSupport?.[i] ?? 0, 4),
          CLIMATES[model.climate[i]].code,
          (LAND_COVER[model.surface?.landCover?.[i] ?? 0] || LAND_COVER[0]).code,
          (SOIL_GROUPS[model.surface?.soilGroup?.[i] ?? 0] || SOIL_GROUPS[0]).code,
          round(model.surface?.vegetation?.[i] ?? 0, 3),
          round(model.surface?.canopyHeight?.[i] ?? 0, 2),
          round(model.surface?.leafAreaIndex?.[i] ?? 0, 2),
          vegetationTypeRecord(model.surface?.vegetationType?.[i] ?? 0).code,
          round(model.surface?.vegetationResilience?.[i] ?? 0, 4),
          round(model.surface?.biomassCarbonKgM2?.[i] ?? 0, 3),
          round(model.surface?.canopyRoughnessLengthM?.[i] ?? 0, 3),
          round(model.surface?.hydraulicConductivityMmHr?.[i] ?? 0, 2),
          round(model.surface?.availableWaterCapacityMm?.[i] ?? 0, 1),
          round(model.surface?.rootDepthM?.[i] ?? 0, 2),
          round(model.surface?.imperviousFraction?.[i] ?? 0, 3),
          round(model.surface?.infiltrationCapacity?.[i] ?? 0, 3),
          round(model.surface?.rootCohesion?.[i] ?? 0, 3),
          Math.round(model.surface?.actualEvapotranspiration?.[i] ?? 0),
          Math.round(model.surface?.waterBalance?.[i] ?? 0),
          round(model.surface?.curveNumber?.[i] ?? 0, 1),
          round(model.runoffCoefficient?.[i] ?? 0, 3),
          round(model.flowAccumulation[i], 4),
          Math.round(model.discharge[i]),
          model.flowRouting || "d8",
          round(model.flowDivergence?.[i] ?? 0, 2),
          round(model.hydraulics?.flowVelocity?.[i] ?? 0, 4),
          round(model.hydraulics?.channelWidthM?.[i] ?? 0, 2),
          round(model.hydraulics?.channelDepthM?.[i] ?? 0, 3),
          round(model.hydraulics?.shearStressPa?.[i] ?? 0, 3),
          round(model.hydraulics?.streamPowerWm2?.[i] ?? 0, 3),
          round(model.hydraulics?.sedimentTransportIndex?.[i] ?? 0, 4),
          round(model.hydraulics?.erosionRisk?.[i] ?? 0, 4),
          round(model.hydraulics?.depositionRisk?.[i] ?? 0, 4),
          round(model.hazards?.currentFloodHazard?.[i] ?? model.hazards?.floodHazard?.[i] ?? 0, 4),
          round(model.hazards?.floodDepthM?.[i] ?? 0, 3),
          round(model.hazards?.currentDroughtStress?.[i] ?? model.hazards?.droughtStress?.[i] ?? 0, 4),
          round(model.hazards?.currentWildfireRisk?.[i] ?? model.hazards?.wildfireRisk?.[i] ?? 0, 4),
          round(model.hazards?.currentLandslideRisk?.[i] ?? model.hazards?.landslideRisk?.[i] ?? 0, 4),
          round(model.hazards?.currentHazardIndex?.[i] ?? model.hazards?.hazardIndex?.[i] ?? 0, 4),
          round(model.hazards?.currentCumulativeErosionM?.[i] ?? model.hazards?.cumulativeErosionM?.[i] ?? 0, 4),
          round(model.hazards?.currentProjectedVegetation?.[i] ?? model.hazards?.projectedVegetation?.[i] ?? 0, 4),
          round(subsurfaceColumnValue(model, "columnWaterTableDepthM", i, 0), 3),
          round(subsurfaceColumnValue(model, "columnBedrockDepthM", i, 0), 3),
          round(subsurfaceColumnValue(model, "columnAquiferPotential", i, 0), 4),
          round(subsurfaceColumnValue(model, "columnFractureRisk", i, 0), 4),
          round(subsurfaceColumnValue(model, "columnLiquefactionRisk", i, 0), 4),
          round(subsurfaceColumnValue(model, "columnStorageMm", i, 0), 1)
        ].join(",")
      );
    }
  }
  return lines.join("\n");
}

export function makeSubsurfaceVoxelCSV(model, options = {}) {
  if (!model?.subsurface?.voxelCount) {
    return "x_km,y_km,source_x,source_y,layer,top_depth_m,bottom_depth_m,center_depth_m,lithology,material_class,risk_class,porosity,permeability_mm_hr,saturation,pore_pressure_kpa,temperature_c,vertical_stress_kpa,fracture_risk,aquifer_potential,observed_support,inference_reliability,engineering_risk,evidence_mask,voxel_storage_m3,voxel_gross_volume_m3,voxel_solid_volume_m3,voxel_pore_volume_m3,voxel_water_volume_m3,voxel_air_void_volume_m3\n";
  }
  const volume = model.subsurface;
  const lines = [
    "x_km,y_km,source_x,source_y,layer,top_depth_m,bottom_depth_m,center_depth_m,lithology,material_class,risk_class,porosity,permeability_mm_hr,saturation,pore_pressure_kpa,temperature_c,vertical_stress_kpa,fracture_risk,aquifer_potential,observed_support,inference_reliability,engineering_risk,evidence_mask,voxel_storage_m3,voxel_gross_volume_m3,voxel_solid_volume_m3,voxel_pore_volume_m3,voxel_water_volume_m3,voxel_air_void_volume_m3"
  ];
  const maxRows = Number.isFinite(Number(options.maxRows)) ? Math.max(1, Math.floor(Number(options.maxRows))) : Infinity;
  let rowCount = 0;
  for (let gy = 0; gy < volume.gridN; gy += 1) {
    const sy = gridToSurfaceIndex(gy, volume.gridN, model.n);
    for (let gx = 0; gx < volume.gridN; gx += 1) {
      const sx = gridToSurfaceIndex(gx, volume.gridN, model.n);
      const columnIndex = gy * volume.gridN + gx;
      for (let layer = 0; layer < volume.layerCount; layer += 1) {
        if (rowCount >= maxRows) return lines.join("\n");
        const voxelIndex = layer * volume.columnCellCount + columnIndex;
        const top = volume.depthEdgesM[layer];
        const bottom = volume.depthEdgesM[layer + 1];
        const lithology = SUBSURFACE_LITHOLOGY[volume.lithologyCode[voxelIndex]] || SUBSURFACE_LITHOLOGY[0];
        const materialClass = SUBSURFACE_MATERIAL_CLASSES[volume.materialClassCode?.[voxelIndex] ?? 0] || SUBSURFACE_MATERIAL_CLASSES[0];
        const riskClass = SUBSURFACE_RISK_CLASSES[volume.riskClassCode?.[voxelIndex] ?? 0] || SUBSURFACE_RISK_CLASSES[0];
        const aquifer = clamp(
          (volume.groundwaterSaturation[voxelIndex] || 0) * (volume.porosity[voxelIndex] || 0) *
            clamp(Math.log1p(volume.permeabilityMmHr[voxelIndex] || 0) / Math.log1p(28), 0, 1.2),
          0,
          1
        );
        lines.push(
          [
            round(sx * model.cellSizeKm, 4),
            round(sy * model.cellSizeKm, 4),
            sx,
            sy,
            layer,
            round(top, 3),
            round(bottom, 3),
            round((top + bottom) / 2, 3),
            lithology.code,
            materialClass.code,
            riskClass.code,
            round(volume.porosity[voxelIndex], 4),
            round(volume.permeabilityMmHr[voxelIndex], 4),
            round(volume.groundwaterSaturation[voxelIndex], 4),
            round(volume.porePressureKpa[voxelIndex], 4),
            round(volume.temperatureC[voxelIndex], 3),
            round(volume.verticalStressKpa[voxelIndex], 3),
            round(volume.fractureRisk[voxelIndex], 4),
            round(aquifer, 4),
            round(volume.voxelObservedSupport?.[voxelIndex] ?? 0, 4),
            round(volume.voxelInferenceReliability?.[voxelIndex] ?? 0, 4),
            round(volume.engineeringRisk?.[voxelIndex] ?? 0, 4),
            evidenceMaskCodes(volume.voxelEvidenceMask?.[voxelIndex] ?? 0).join("|"),
            round(volume.voxelStorageM3?.[voxelIndex] ?? 0, 4),
            round(volume.voxelGrossVolumeM3?.[voxelIndex] ?? 0, 4),
            round(volume.voxelSolidVolumeM3?.[voxelIndex] ?? 0, 4),
            round(volume.voxelPoreVolumeM3?.[voxelIndex] ?? 0, 4),
            round(volume.voxelWaterVolumeM3?.[voxelIndex] ?? 0, 4),
            round(volume.voxelAirVoidVolumeM3?.[voxelIndex] ?? 0, 4)
          ].join(",")
        );
        rowCount += 1;
      }
    }
  }
  return lines.join("\n");
}

export function buildSubsurfaceCubeLedger(model, params = {}, options = {}) {
  if (!model?.subsurface?.voxelCount) throw new Error("A computed model with subsurface voxels is required");
  const volume = model.subsurface;
  const groups = new Map();
  const materialWeights = new Float64Array(SUBSURFACE_MATERIAL_CLASSES.length);
  const riskWeights = new Float64Array(SUBSURFACE_RISK_CLASSES.length);
  const layerWeights = new Float64Array(volume.layerCount);
  const cellAreaM2 = volume.cubeGeometry?.areaM2 || ((Number(model.sizeKm || params.mapSizeKm || MAP_SIZE_KM) * 1000) / Math.max(1, volume.gridN - 1)) ** 2;

  let totalGrossVolumeM3 = 0;
  let totalSolidVolumeM3 = 0;
  let totalPoreVolumeM3 = 0;
  let groundwaterVolumeM3 = 0;
  let unsaturatedVoidVolumeM3 = 0;
  let highRiskVolumeM3 = 0;
  let aquiferBodyVolumeM3 = 0;
  let observedWeighted = 0;
  let reliabilityWeighted = 0;
  let engineeringRiskWeighted = 0;
  let calibratedVoxelCount = 0;
  let highConfidenceVoxelCount = 0;

  for (let layer = 0; layer < volume.layerCount; layer += 1) {
    const topDepthM = volume.depthEdgesM[layer];
    const bottomDepthM = volume.depthEdgesM[layer + 1];
    const thicknessM = Math.max(0, bottomDepthM - topDepthM);
    for (let columnIndex = 0; columnIndex < volume.columnCellCount; columnIndex += 1) {
      const voxelIndex = layer * volume.columnCellCount + columnIndex;
      const lithologyId = volume.lithologyCode?.[voxelIndex] ?? 0;
      const lithology = SUBSURFACE_LITHOLOGY[lithologyId] || SUBSURFACE_LITHOLOGY[0];
      const materialId = volume.materialClassCode?.[voxelIndex] ?? 0;
      const riskId = volume.riskClassCode?.[voxelIndex] ?? 0;
      const materialClass = SUBSURFACE_MATERIAL_CLASSES[materialId] || SUBSURFACE_MATERIAL_CLASSES[0];
      const riskClass = SUBSURFACE_RISK_CLASSES[riskId] || SUBSURFACE_RISK_CLASSES[0];
      const grossVolumeM3 = volume.voxelGrossVolumeM3?.[voxelIndex] ?? thicknessM * cellAreaM2;
      const porosity = clamp(volume.porosity?.[voxelIndex] ?? lithology.porosity ?? 0, 0, 0.9);
      const saturation = clamp(volume.groundwaterSaturation?.[voxelIndex] ?? 0, 0, 1);
      const poreVolumeM3 = volume.voxelPoreVolumeM3?.[voxelIndex] ?? grossVolumeM3 * porosity;
      const solidVolumeM3 = volume.voxelSolidVolumeM3?.[voxelIndex] ?? Math.max(0, grossVolumeM3 - poreVolumeM3);
      const waterVolumeM3 = volume.voxelWaterVolumeM3?.[voxelIndex] ?? poreVolumeM3 * saturation;
      const airVoidVolumeM3 = volume.voxelAirVoidVolumeM3?.[voxelIndex] ?? Math.max(0, poreVolumeM3 - waterVolumeM3);
      const engineeringRiskValue = clamp(volume.engineeringRisk?.[voxelIndex] ?? 0, 0, 1);
      const observedSupport = clamp(volume.voxelObservedSupport?.[voxelIndex] ?? 0, 0, 1);
      const inferenceReliability = clamp(volume.voxelInferenceReliability?.[voxelIndex] ?? 0, 0, 1);
      const evidenceMask = volume.voxelEvidenceMask?.[voxelIndex] ?? 0;
      const key = `${layer}:${lithologyId}:${materialId}:${riskId}`;
      let group = groups.get(key);
      if (!group) {
        group = createSubsurfaceCubeLedgerGroup({
          groupKey: key,
          layer,
          topDepthM,
          bottomDepthM,
          thicknessM,
          lithology,
          materialClass,
          riskClass
        });
        groups.set(key, group);
      }
      group.voxelCount += 1;
      group.grossVolumeM3 += grossVolumeM3;
      group.solidVolumeM3 += solidVolumeM3;
      group.poreVolumeM3 += poreVolumeM3;
      group.waterVolumeM3 += waterVolumeM3;
      group.airVoidVolumeM3 += airVoidVolumeM3;
      group.solidMassTonnes += (solidVolumeM3 * (lithology.densityKgM3 || 2000)) / 1000;
      group.groundwaterMassTonnes += waterVolumeM3;
      group.highRiskVolumeM3 += engineeringRiskValue > 0.62 ? grossVolumeM3 : 0;
      group.aquiferBodyVolumeM3 += materialClass.code === "AQUIFER_BODY" || materialClass.code === "SATURATED_UNCONSOLIDATED" ? waterVolumeM3 : 0;
      group.sumPorosity += porosity * grossVolumeM3;
      group.sumSaturation += saturation * grossVolumeM3;
      group.sumPermeability += (volume.permeabilityMmHr?.[voxelIndex] ?? 0) * grossVolumeM3;
      group.sumPorePressure += (volume.porePressureKpa?.[voxelIndex] ?? 0) * grossVolumeM3;
      group.sumVerticalStress += (volume.verticalStressKpa?.[voxelIndex] ?? 0) * grossVolumeM3;
      group.sumTemperature += (volume.temperatureC?.[voxelIndex] ?? 0) * grossVolumeM3;
      group.sumFractureRisk += (volume.fractureRisk?.[voxelIndex] ?? 0) * grossVolumeM3;
      group.sumObservedSupport += observedSupport * grossVolumeM3;
      group.sumInferenceReliability += inferenceReliability * grossVolumeM3;
      group.sumEngineeringRisk += engineeringRiskValue * grossVolumeM3;
      group.evidenceMask |= evidenceMask;
      if (observedSupport > 0.58) group.calibratedVoxelCount += 1;
      if (observedSupport > 0.72) group.highConfidenceVoxelCount += 1;

      totalGrossVolumeM3 += grossVolumeM3;
      totalSolidVolumeM3 += solidVolumeM3;
      totalPoreVolumeM3 += poreVolumeM3;
      groundwaterVolumeM3 += waterVolumeM3;
      unsaturatedVoidVolumeM3 += airVoidVolumeM3;
      if (engineeringRiskValue > 0.62) highRiskVolumeM3 += grossVolumeM3;
      if (materialClass.code === "AQUIFER_BODY" || materialClass.code === "SATURATED_UNCONSOLIDATED") aquiferBodyVolumeM3 += waterVolumeM3;
      observedWeighted += observedSupport * grossVolumeM3;
      reliabilityWeighted += inferenceReliability * grossVolumeM3;
      engineeringRiskWeighted += engineeringRiskValue * grossVolumeM3;
      if (observedSupport > 0.58) calibratedVoxelCount += 1;
      if (observedSupport > 0.72) highConfidenceVoxelCount += 1;
      materialWeights[materialClass.id] += grossVolumeM3;
      riskWeights[riskClass.id] += grossVolumeM3;
      layerWeights[layer] += grossVolumeM3;
    }
  }

  const rows = Array.from(groups.values())
    .map(finalizeSubsurfaceCubeLedgerGroup)
    .sort((a, b) => b.meanEngineeringRisk - a.meanEngineeringRisk || b.grossVolumeM3 - a.grossVolumeM3);
  rows.forEach((row, index) => {
    row.rank = index + 1;
  });

  const grossDivisor = Math.max(1, totalGrossVolumeM3);
  const poreDivisor = Math.max(1, totalPoreVolumeM3);
  return {
    type: "geolab-subsurface-cube-ledger",
    schemaVersion: 1,
    method: "layer-lithology-material-risk volumetric aggregation from the subsurface voxel cube",
    methodZh: "由地下体素立方按层位、岩性、材料类别和工程风险聚合为地底实心推理账本",
    cubeGeometry: {
      gridN: volume.gridN,
      layerCount: volume.layerCount,
      depthM: volume.depthM,
      widthM: volume.cubeGeometry?.widthM || Math.sqrt(cellAreaM2),
      areaM2: cellAreaM2,
      heightByLayerM: volume.cubeGeometry?.heightByLayerM || Array.from({ length: volume.layerCount }, (_, layer) => volume.depthEdgesM[layer + 1] - volume.depthEdgesM[layer])
    },
    summary: {
      voxelCount: volume.voxelCount,
      columnCellCount: volume.columnCellCount,
      gridN: volume.gridN,
      layerCount: volume.layerCount,
      depthM: volume.depthM,
      groupCount: rows.length,
      totalGrossVolumeM3,
      totalSolidVolumeM3,
      totalPoreVolumeM3,
      groundwaterVolumeM3,
      unsaturatedVoidVolumeM3,
      highRiskVolumeM3,
      aquiferBodyVolumeM3,
      solidFraction: totalSolidVolumeM3 / grossDivisor,
      poreFraction: totalPoreVolumeM3 / grossDivisor,
      groundwaterSaturationFraction: groundwaterVolumeM3 / poreDivisor,
      unsaturatedVoidFraction: unsaturatedVoidVolumeM3 / poreDivisor,
      highRiskVolumeFraction: highRiskVolumeM3 / grossDivisor,
      meanObservedSupport: observedWeighted / grossDivisor,
      meanInferenceReliability: reliabilityWeighted / grossDivisor,
      meanEngineeringRisk: engineeringRiskWeighted / grossDivisor,
      reliabilityClass: subsurfaceReliabilityClass(reliabilityWeighted / grossDivisor, observedWeighted / grossDivisor),
      calibratedVoxelCount,
      highConfidenceVoxelCount,
      dominantMaterialClass: dominantLegendEntry(SUBSURFACE_MATERIAL_CLASSES, materialWeights),
      dominantRiskClass: dominantLegendEntry(SUBSURFACE_RISK_CLASSES, riskWeights),
      dominantLayer: dominantSubsurfaceLayer(layerWeights, volume.depthEdgesM)
    },
    reasoning: {
      rules: [
        "voxel-gross-volume-equals-column-area-times-layer-thickness",
        "gross-volume-is-partitioned-into-solid-pore-water-and-air-void-volume",
        "solid-volume-and-mass-use-lithology-density-and-porosity",
        "water-volume-is-pore-volume-times-groundwater-saturation",
        "risk-ledger-ranks-groups-by-volume-weighted-engineering-risk"
      ],
      couplings: [
        "voxel-solid-ledger-to-engineering-risk",
        "aquifer-volume-to-water-budget",
        "pore-pressure-to-geostress-and-liquefaction",
        "borehole-evidence-to-observed-support",
        "surface-recharge-to-groundwater-saturation"
      ],
      limitations: [
        "solid partitions are inferred unless constrained by borehole lithology and hydraulic observations",
        "voxel groups are an engineering ledger, not a substitute for site-specific geotechnical investigation"
      ]
    },
    rows
  };
}

export function makeSubsurfaceCubeLedgerCSV(input, options = {}) {
  const ledger = input?.type === "geolab-subsurface-cube-ledger"
    ? input
    : buildSubsurfaceCubeLedger(input, options.params || {}, options);
  const header = [
    "rank",
    "group_key",
    "layer",
    "top_depth_m",
    "bottom_depth_m",
    "thickness_m",
    "lithology",
    "material_class",
    "risk_class",
    "voxel_count",
    "gross_volume_m3",
    "solid_volume_m3",
    "pore_volume_m3",
    "water_volume_m3",
    "air_void_volume_m3",
    "solid_mass_tonnes",
    "groundwater_mass_tonnes",
    "high_risk_volume_m3",
    "aquifer_body_volume_m3",
    "mean_porosity",
    "mean_saturation",
    "mean_permeability_mm_hr",
    "mean_pore_pressure_kpa",
    "mean_vertical_stress_kpa",
    "mean_temperature_c",
    "mean_fracture_risk",
    "mean_observed_support",
    "mean_inference_reliability",
    "mean_engineering_risk",
    "dominant_process",
    "evidence_mask",
    "inference_basis"
  ];
  return [
    header.join(","),
    ...ledger.rows.map((row) => [
      row.rank,
      row.groupKey,
      row.layer,
      round(row.topDepthM, 3),
      round(row.bottomDepthM, 3),
      round(row.thicknessM, 3),
      row.lithology?.code || "",
      row.materialClass?.code || "",
      row.riskClass?.code || "",
      row.voxelCount,
      round(row.grossVolumeM3, 3),
      round(row.solidVolumeM3, 3),
      round(row.poreVolumeM3, 3),
      round(row.waterVolumeM3, 3),
      round(row.airVoidVolumeM3, 3),
      round(row.solidMassTonnes, 3),
      round(row.groundwaterMassTonnes, 3),
      round(row.highRiskVolumeM3, 3),
      round(row.aquiferBodyVolumeM3, 3),
      round(row.meanPorosity, 5),
      round(row.meanSaturation, 5),
      round(row.meanPermeabilityMmHr, 5),
      round(row.meanPorePressureKpa, 4),
      round(row.meanVerticalStressKpa, 4),
      round(row.meanTemperatureC, 4),
      round(row.meanFractureRisk, 5),
      round(row.meanObservedSupport, 5),
      round(row.meanInferenceReliability, 5),
      round(row.meanEngineeringRisk, 5),
      row.dominantProcess,
      row.evidenceCodes?.join("|") || "",
      row.inferenceBasis?.join("|") || ""
    ].map(csvValue).join(","))
  ].join("\n");
}

export function buildSubsurfaceColumnReasoningAtlas(model, params = {}, options = {}) {
  if (!model?.subsurface?.voxelCount) throw new Error("A computed model with subsurface voxels is required");
  const volume = model.subsurface;
  const gridN = volume.gridN;
  const layerCount = volume.layerCount;
  const columnCellCount = volume.columnCellCount;
  const sizeKm = Number(model.sizeKm || params.mapSizeKm || MAP_SIZE_KM);
  const columnWidthKm = sizeKm / Math.max(1, gridN - 1);
  const rows = [];
  const summaryMaterialWeights = new Float64Array(SUBSURFACE_MATERIAL_CLASSES.length);
  const summaryRiskWeights = new Float64Array(SUBSURFACE_RISK_CLASSES.length);
  const summary = {
    totalGrossVolumeM3: 0,
    totalSolidVolumeM3: 0,
    totalPoreVolumeM3: 0,
    groundwaterVolumeM3: 0,
    airVoidVolumeM3: 0,
    aquiferVolumeM3: 0,
    highRiskVolumeM3: 0,
    meanFoundationSuitabilityIndex: 0,
    meanExcavationDifficultyIndex: 0,
    meanGroundwaterInterferenceIndex: 0,
    meanCollapseSubsidenceRisk: 0,
    meanTunnelSupportDemandIndex: 0,
    highRiskColumnCount: 0,
    highGroundwaterInterferenceColumnCount: 0,
    lowFoundationSuitabilityColumnCount: 0
  };

  for (let columnIndex = 0; columnIndex < columnCellCount; columnIndex += 1) {
    const gx = columnIndex % gridN;
    const gy = Math.floor(columnIndex / gridN);
    const sourceX = gridToSurfaceIndex(gx, gridN, model.n);
    const sourceY = gridToSurfaceIndex(gy, gridN, model.n);
    const materialWeights = new Float64Array(SUBSURFACE_MATERIAL_CLASSES.length);
    const riskWeights = new Float64Array(SUBSURFACE_RISK_CLASSES.length);
    let grossVolumeM3 = 0;
    let solidVolumeM3 = 0;
    let poreVolumeM3 = 0;
    let groundwaterVolumeM3 = 0;
    let airVoidVolumeM3 = 0;
    let aquiferVolumeM3 = 0;
    let highRiskVolumeM3 = 0;
    let weightedPorosity = 0;
    let weightedSaturation = 0;
    let weightedPermeability = 0;
    let weightedPorePressure = 0;
    let weightedVerticalStress = 0;
    let weightedTemperature = 0;
    let weightedFractureRisk = 0;
    let weightedObservedSupport = 0;
    let weightedReliability = 0;
    let weightedEngineeringRisk = 0;
    let maxEngineeringRisk = 0;
    let evidenceMask = 0;
    let competentBedrockVolumeM3 = 0;
    let saturatedLooseVolumeM3 = 0;

    for (let layer = 0; layer < layerCount; layer += 1) {
      const voxelIndex = layer * columnCellCount + columnIndex;
      const lithologyId = volume.lithologyCode?.[voxelIndex] ?? 0;
      const lithology = SUBSURFACE_LITHOLOGY[lithologyId] || SUBSURFACE_LITHOLOGY[0];
      const materialId = volume.materialClassCode?.[voxelIndex] ?? 0;
      const riskId = volume.riskClassCode?.[voxelIndex] ?? 0;
      const gross = volume.voxelGrossVolumeM3?.[voxelIndex] ?? 0;
      const solid = volume.voxelSolidVolumeM3?.[voxelIndex] ?? Math.max(0, gross * (1 - (volume.porosity?.[voxelIndex] ?? lithology.porosity ?? 0)));
      const pore = volume.voxelPoreVolumeM3?.[voxelIndex] ?? Math.max(0, gross - solid);
      const water = volume.voxelWaterVolumeM3?.[voxelIndex] ?? pore * clamp(volume.groundwaterSaturation?.[voxelIndex] ?? 0, 0, 1);
      const airVoid = volume.voxelAirVoidVolumeM3?.[voxelIndex] ?? Math.max(0, pore - water);
      const engineeringRiskValue = clamp(volume.engineeringRisk?.[voxelIndex] ?? 0, 0, 1);
      const aquiferSignal = clamp(
        (volume.groundwaterSaturation?.[voxelIndex] ?? 0) *
          (volume.porosity?.[voxelIndex] ?? lithology.porosity ?? 0) *
          clamp(Math.log1p(volume.permeabilityMmHr?.[voxelIndex] ?? 0) / Math.log1p(28), 0, 1.2),
        0,
        1
      );

      grossVolumeM3 += gross;
      solidVolumeM3 += solid;
      poreVolumeM3 += pore;
      groundwaterVolumeM3 += water;
      airVoidVolumeM3 += airVoid;
      if (aquiferSignal > 0.28) aquiferVolumeM3 += water;
      if (engineeringRiskValue > 0.62) highRiskVolumeM3 += gross;
      weightedPorosity += (volume.porosity?.[voxelIndex] ?? lithology.porosity ?? 0) * gross;
      weightedSaturation += (volume.groundwaterSaturation?.[voxelIndex] ?? 0) * gross;
      weightedPermeability += (volume.permeabilityMmHr?.[voxelIndex] ?? 0) * gross;
      weightedPorePressure += (volume.porePressureKpa?.[voxelIndex] ?? 0) * gross;
      weightedVerticalStress += (volume.verticalStressKpa?.[voxelIndex] ?? 0) * gross;
      weightedTemperature += (volume.temperatureC?.[voxelIndex] ?? 0) * gross;
      weightedFractureRisk += (volume.fractureRisk?.[voxelIndex] ?? 0) * gross;
      weightedObservedSupport += (volume.voxelObservedSupport?.[voxelIndex] ?? 0) * gross;
      weightedReliability += (volume.voxelInferenceReliability?.[voxelIndex] ?? 0) * gross;
      weightedEngineeringRisk += engineeringRiskValue * gross;
      maxEngineeringRisk = Math.max(maxEngineeringRisk, engineeringRiskValue);
      evidenceMask |= volume.voxelEvidenceMask?.[voxelIndex] ?? 0;
      materialWeights[materialId] += gross;
      riskWeights[riskId] += gross;
      summaryMaterialWeights[materialId] += gross;
      summaryRiskWeights[riskId] += gross;
      if (materialId === 6) competentBedrockVolumeM3 += gross;
      if (materialId === 7 || riskId === 3) saturatedLooseVolumeM3 += gross;
    }

    const grossDivisor = Math.max(1, grossVolumeM3);
    const poreDivisor = Math.max(1, poreVolumeM3);
    const meanPorosity = weightedPorosity / grossDivisor;
    const meanSaturation = weightedSaturation / grossDivisor;
    const meanPermeabilityMmHr = weightedPermeability / grossDivisor;
    const meanPorePressureKpa = weightedPorePressure / grossDivisor;
    const meanVerticalStressKpa = weightedVerticalStress / grossDivisor;
    const meanTemperatureC = weightedTemperature / grossDivisor;
    const meanFractureRisk = weightedFractureRisk / grossDivisor;
    const meanObservedSupport = weightedObservedSupport / grossDivisor;
    const meanInferenceReliability = weightedReliability / grossDivisor;
    const meanEngineeringRisk = weightedEngineeringRisk / grossDivisor;
    const solidFraction = solidVolumeM3 / grossDivisor;
    const poreFraction = poreVolumeM3 / grossDivisor;
    const saturatedPoreFraction = groundwaterVolumeM3 / poreDivisor;
    const highRiskFraction = highRiskVolumeM3 / grossDivisor;
    const aquiferVolumeFraction = aquiferVolumeM3 / grossDivisor;
    const competentBedrockFraction = competentBedrockVolumeM3 / grossDivisor;
    const saturatedLooseFraction = saturatedLooseVolumeM3 / grossDivisor;
    const waterTableDepthM = volume.columnWaterTableDepthM?.[columnIndex] ?? 0;
    const bedrockDepthM = volume.columnBedrockDepthM?.[columnIndex] ?? 0;
    const aquiferPotential = clamp(volume.columnAquiferPotential?.[columnIndex] ?? 0, 0, 1);
    const liquefactionRisk = clamp(volume.columnLiquefactionRisk?.[columnIndex] ?? 0, 0, 1);
    const shallowWater = clamp(1 - waterTableDepthM / Math.max(2, volume.depthM * 0.34), 0, 1);
    const shallowBedrock = clamp(1 - bedrockDepthM / Math.max(2, volume.depthM * 0.26), 0, 1);
    const permeabilityNorm = clamp(Math.log1p(meanPermeabilityMmHr) / Math.log1p(80), 0, 1);
    const porePressureNorm = clamp(meanPorePressureKpa / Math.max(35, meanVerticalStressKpa * 0.42), 0, 1);
    const stressNorm = clamp(meanVerticalStressKpa / 2600, 0, 1);
    const groundwaterInterferenceIndex = clamp(
      shallowWater * 0.28 +
        saturatedPoreFraction * 0.22 +
        aquiferPotential * 0.2 +
        porePressureNorm * 0.12 +
        aquiferVolumeFraction * 1.35 +
        permeabilityNorm * 0.08,
      0,
      1
    );
    const excavationDifficultyIndex = clamp(
      shallowBedrock * 0.18 +
        solidFraction * 0.12 +
        meanFractureRisk * 0.22 +
        groundwaterInterferenceIndex * 0.2 +
        highRiskFraction * 0.18 +
        porePressureNorm * 0.08 +
        stressNorm * 0.06,
      0,
      1
    );
    const collapseSubsidenceRisk = clamp(
      liquefactionRisk * 0.32 +
        saturatedLooseFraction * 0.24 +
        highRiskFraction * 0.16 +
        meanEngineeringRisk * 0.14 +
        poreFraction * 0.12 +
        (1 - meanInferenceReliability) * 0.07 +
        meanFractureRisk * 0.1,
      0,
      1
    );
    const tunnelSupportDemandIndex = clamp(
      meanEngineeringRisk * 0.24 +
        meanFractureRisk * 0.22 +
        groundwaterInterferenceIndex * 0.2 +
        porePressureNorm * 0.14 +
        stressNorm * 0.1 +
        (1 - competentBedrockFraction) * 0.1,
      0,
      1
    );
    const foundationSuitabilityIndex = clamp(
      0.18 +
        competentBedrockFraction * 0.3 +
        (1 - meanEngineeringRisk) * 0.2 +
        (1 - liquefactionRisk) * 0.16 +
        (1 - groundwaterInterferenceIndex) * 0.12 +
        meanInferenceReliability * 0.12 +
        shallowBedrock * 0.08 -
        collapseSubsidenceRisk * 0.12,
      0,
      1
    );
    const dominantMaterialClass = dominantLegendEntry(SUBSURFACE_MATERIAL_CLASSES, materialWeights);
    const dominantRiskClass = dominantLegendEntry(SUBSURFACE_RISK_CLASSES, riskWeights);
    const evidenceCodes = evidenceMaskCodes(evidenceMask);
    const dominantProcess = subsurfaceDominantProcess({
      materialClass: dominantMaterialClass,
      riskClass: dominantRiskClass,
      meanPorosity,
      meanSaturation,
      meanPermeabilityMmHr,
      meanFractureRisk,
      meanEngineeringRisk,
      waterVolumeM3: groundwaterVolumeM3,
      grossVolumeM3
    });
    const reliabilityClass = subsurfaceReliabilityClass(meanInferenceReliability, meanObservedSupport);
    const inferenceBasis = subsurfaceInferenceBasis({
      materialClass: dominantMaterialClass,
      riskClass: dominantRiskClass,
      evidenceCodes,
      meanPorosity,
      meanSaturation,
      meanPermeabilityMmHr,
      meanFractureRisk,
      meanObservedSupport,
      meanInferenceReliability,
      meanEngineeringRisk,
      waterVolumeFraction: groundwaterVolumeM3 / grossDivisor,
      highRiskVolumeFraction: highRiskFraction
    });
    const priorityScore = Math.max(
      meanEngineeringRisk,
      maxEngineeringRisk * 0.86,
      groundwaterInterferenceIndex * 0.92,
      collapseSubsidenceRisk * 0.96,
      tunnelSupportDemandIndex * 0.9,
      (1 - foundationSuitabilityIndex) * 0.78
    );
    const row = {
      rank: 0,
      xKm: gx * columnWidthKm,
      yKm: gy * columnWidthKm,
      sourceX,
      sourceY,
      columnIndex,
      waterTableDepthM,
      bedrockDepthM,
      grossVolumeM3,
      solidVolumeM3,
      poreVolumeM3,
      groundwaterVolumeM3,
      airVoidVolumeM3,
      aquiferVolumeM3,
      highRiskVolumeM3,
      solidFraction,
      poreFraction,
      saturatedPoreFraction,
      meanPorosity,
      meanSaturation,
      meanPermeabilityMmHr,
      meanPorePressureKpa,
      meanVerticalStressKpa,
      meanTemperatureC,
      meanFractureRisk,
      aquiferPotential,
      liquefactionRisk,
      meanEngineeringRisk,
      maxEngineeringRisk,
      meanObservedSupport,
      meanInferenceReliability,
      foundationSuitabilityIndex,
      excavationDifficultyIndex,
      groundwaterInterferenceIndex,
      collapseSubsidenceRisk,
      tunnelSupportDemandIndex,
      dominantMaterialClass,
      dominantRiskClass,
      dominantProcess,
      reliabilityClass,
      recommendedActionZh: subsurfaceColumnRecommendedActionZh({
        foundationSuitabilityIndex,
        excavationDifficultyIndex,
        groundwaterInterferenceIndex,
        collapseSubsidenceRisk,
        tunnelSupportDemandIndex,
        dominantRiskClass
      }),
      inferenceBasis,
      evidenceMask,
      evidenceCodes,
      priorityScore
    };
    rows.push(row);

    summary.totalGrossVolumeM3 += grossVolumeM3;
    summary.totalSolidVolumeM3 += solidVolumeM3;
    summary.totalPoreVolumeM3 += poreVolumeM3;
    summary.groundwaterVolumeM3 += groundwaterVolumeM3;
    summary.airVoidVolumeM3 += airVoidVolumeM3;
    summary.aquiferVolumeM3 += aquiferVolumeM3;
    summary.highRiskVolumeM3 += highRiskVolumeM3;
    summary.meanFoundationSuitabilityIndex += foundationSuitabilityIndex;
    summary.meanExcavationDifficultyIndex += excavationDifficultyIndex;
    summary.meanGroundwaterInterferenceIndex += groundwaterInterferenceIndex;
    summary.meanCollapseSubsidenceRisk += collapseSubsidenceRisk;
    summary.meanTunnelSupportDemandIndex += tunnelSupportDemandIndex;
    if (priorityScore > 0.62 || meanEngineeringRisk > 0.48 || maxEngineeringRisk > 0.72) summary.highRiskColumnCount += 1;
    if (groundwaterInterferenceIndex > 0.58) summary.highGroundwaterInterferenceColumnCount += 1;
    if (foundationSuitabilityIndex < 0.42) summary.lowFoundationSuitabilityColumnCount += 1;
  }

  rows.sort((a, b) => b.priorityScore - a.priorityScore || b.highRiskVolumeM3 - a.highRiskVolumeM3 || a.columnIndex - b.columnIndex);
  rows.forEach((row, index) => {
    row.rank = index + 1;
  });

  const countDivisor = Math.max(1, rows.length);
  summary.meanFoundationSuitabilityIndex /= countDivisor;
  summary.meanExcavationDifficultyIndex /= countDivisor;
  summary.meanGroundwaterInterferenceIndex /= countDivisor;
  summary.meanCollapseSubsidenceRisk /= countDivisor;
  summary.meanTunnelSupportDemandIndex /= countDivisor;
  summary.highRiskVolumeFraction = summary.highRiskVolumeM3 / Math.max(1, summary.totalGrossVolumeM3);
  summary.groundwaterFractionOfPoreVolume = summary.groundwaterVolumeM3 / Math.max(1, summary.totalPoreVolumeM3);
  summary.dominantMaterialClass = dominantLegendEntry(SUBSURFACE_MATERIAL_CLASSES, summaryMaterialWeights);
  summary.dominantRiskClass = dominantLegendEntry(SUBSURFACE_RISK_CLASSES, summaryRiskWeights);

  return {
    type: "geolab-subsurface-column-reasoning-atlas",
    schemaVersion: 1,
    displayName: "地下柱体立方推理图谱",
    method: "surface-column aggregation of solid, pore, groundwater and geotechnical voxel state",
    methodZh: "按地表柱体聚合地下立方体元，推理实体体积、孔隙水、开挖、承载、液化和地下水干扰。",
    cubeGeometry: {
      gridN,
      layerCount,
      depthM: volume.depthM,
      widthM: volume.cubeGeometry?.widthM || columnWidthKm * 1000,
      areaM2: volume.cubeGeometry?.areaM2 || (columnWidthKm * 1000) ** 2,
      heightByLayerM: volume.cubeGeometry?.heightByLayerM || Array.from({ length: layerCount }, (_, layer) => volume.depthEdgesM[layer + 1] - volume.depthEdgesM[layer])
    },
    summary,
    reasoning: {
      rules: [
        "column-volume-is-summed-from-all-depth-voxels",
        "gross-volume-is-conserved-into-solid-pore-water-and-air-void-parts",
        "foundation-suitability-combines-competent-bedrock-risk-groundwater-liquefaction-and-confidence",
        "excavation-difficulty-combines-shallow-bedrock-fracture-groundwater-pressure-and-high-risk-volume",
        "collapse-subsidence-risk-combines-liquefaction-saturated-loose-deposit-pore-volume-and-low-confidence"
      ],
      couplings: [
        "groundwater-table-to-excavation-and-foundation-risk",
        "pore-pressure-to-tunnel-support-demand",
        "material-class-to-bearing-suitability",
        "risk-class-to-underground-priority-action",
        "voxel-evidence-mask-to-column-reliability"
      ],
      limitations: [
        "column reasoning is a planning-grade volumetric inference unless calibrated by boreholes or geophysics",
        "foundation and excavation indices are comparative screening metrics, not final structural design parameters"
      ]
    },
    columns: SUBSURFACE_COLUMN_REASONING_COLUMNS,
    rowCount: rows.length,
    rows
  };
}

export function makeSubsurfaceColumnReasoningCSV(input, options = {}) {
  const atlas = input?.type === "geolab-subsurface-column-reasoning-atlas"
    ? input
    : buildSubsurfaceColumnReasoningAtlas(input, options.params || {}, options);
  const maxRows = Number.isFinite(Number(options.maxRows)) ? Math.max(1, Math.floor(Number(options.maxRows))) : Infinity;
  return [
    SUBSURFACE_COLUMN_REASONING_COLUMNS.join(","),
    ...atlas.rows.slice(0, maxRows).map((row) => [
      row.rank,
      round(row.xKm, 4),
      round(row.yKm, 4),
      row.sourceX,
      row.sourceY,
      row.columnIndex,
      round(row.waterTableDepthM, 3),
      round(row.bedrockDepthM, 3),
      round(row.grossVolumeM3, 3),
      round(row.solidVolumeM3, 3),
      round(row.poreVolumeM3, 3),
      round(row.groundwaterVolumeM3, 3),
      round(row.airVoidVolumeM3, 3),
      round(row.aquiferVolumeM3, 3),
      round(row.highRiskVolumeM3, 3),
      round(row.solidFraction, 5),
      round(row.poreFraction, 5),
      round(row.saturatedPoreFraction, 5),
      round(row.meanPorosity, 5),
      round(row.meanSaturation, 5),
      round(row.meanPermeabilityMmHr, 5),
      round(row.meanPorePressureKpa, 4),
      round(row.meanVerticalStressKpa, 4),
      round(row.meanTemperatureC, 4),
      round(row.meanFractureRisk, 5),
      round(row.aquiferPotential, 5),
      round(row.liquefactionRisk, 5),
      round(row.meanEngineeringRisk, 5),
      round(row.maxEngineeringRisk, 5),
      round(row.meanObservedSupport, 5),
      round(row.meanInferenceReliability, 5),
      round(row.foundationSuitabilityIndex, 5),
      round(row.excavationDifficultyIndex, 5),
      round(row.groundwaterInterferenceIndex, 5),
      round(row.collapseSubsidenceRisk, 5),
      round(row.tunnelSupportDemandIndex, 5),
      row.dominantMaterialClass?.code || "",
      row.dominantRiskClass?.code || "",
      row.dominantProcess,
      row.reliabilityClass,
      row.recommendedActionZh,
      row.inferenceBasis?.join("|") || "",
      row.evidenceCodes?.join("|") || evidenceMaskCodes(row.evidenceMask).join("|")
    ].map(csvValue).join(","))
  ].join("\n");
}

export function buildSubsurfaceTransect(model, params = {}, options = {}) {
  if (!model?.subsurface?.voxelCount) throw new Error("A computed model with subsurface voxels is required");
  const volume = model.subsurface;
  const sizeKm = Number(model.sizeKm) || Number(params.mapSizeKm) || MAP_SIZE_KM;
  const mode = options.mode || "west-east";
  const endpoints = subsurfaceTransectEndpoints(mode, sizeKm, options);
  const samples = clampInteger(options.samples ?? 33, 2, 1025, 33);
  const profileId = options.profileId || `${mode}-${samples}`;
  const lengthKm = Math.hypot(endpoints.end.xKm - endpoints.start.xKm, endpoints.end.yKm - endpoints.start.yKm);
  const segmentWidthM = samples > 1 ? (lengthKm * 1000) / (samples - 1) : model.cellSizeKm * 1000;
  const rows = [];
  const materialArea = new Float64Array(SUBSURFACE_MATERIAL_CLASSES.length);
  const riskArea = new Float64Array(SUBSURFACE_RISK_CLASSES.length);
  let meanObservedSupport = 0;
  let meanInferenceReliability = 0;
  let meanEngineeringRisk = 0;
  let maxEngineeringRisk = 0;
  let saturatedAquiferCrossSectionM2 = 0;
  let highRiskCrossSectionM2 = 0;
  let calibratedRowCount = 0;

  for (let sample = 0; sample < samples; sample += 1) {
    const t = samples === 1 ? 0 : sample / (samples - 1);
    const xKm = lerp(endpoints.start.xKm, endpoints.end.xKm, t);
    const yKm = lerp(endpoints.start.yKm, endpoints.end.yKm, t);
    const sx = clamp(Math.round((xKm / Math.max(sizeKm, 0.0001)) * (model.n - 1)), 0, model.n - 1);
    const sy = clamp(Math.round((yKm / Math.max(sizeKm, 0.0001)) * (model.n - 1)), 0, model.n - 1);
    const surfaceIndex = sy * model.n + sx;
    const columnIndex = subsurfaceColumnIndex(model, surfaceIndex);
    if (columnIndex < 0) continue;
    for (let layer = 0; layer < volume.layerCount; layer += 1) {
      const topDepthM = volume.depthEdgesM[layer];
      const bottomDepthM = volume.depthEdgesM[layer + 1];
      const thicknessM = Math.max(0, bottomDepthM - topDepthM);
      const voxelIndex = layer * volume.columnCellCount + columnIndex;
      const lithology = SUBSURFACE_LITHOLOGY[volume.lithologyCode?.[voxelIndex] ?? 0] || SUBSURFACE_LITHOLOGY[0];
      const materialClass = SUBSURFACE_MATERIAL_CLASSES[volume.materialClassCode?.[voxelIndex] ?? 0] || SUBSURFACE_MATERIAL_CLASSES[0];
      const riskClass = SUBSURFACE_RISK_CLASSES[volume.riskClassCode?.[voxelIndex] ?? 0] || SUBSURFACE_RISK_CLASSES[0];
      const saturation = volume.groundwaterSaturation?.[voxelIndex] ?? 0;
      const porosity = volume.porosity?.[voxelIndex] ?? 0;
      const permeability = volume.permeabilityMmHr?.[voxelIndex] ?? 0;
      const aquiferPotential = clamp(saturation * porosity * clamp(Math.log1p(permeability) / Math.log1p(28), 0, 1.2), 0, 1);
      const observedSupport = volume.voxelObservedSupport?.[voxelIndex] ?? 0;
      const inferenceReliability = volume.voxelInferenceReliability?.[voxelIndex] ?? 0;
      const engineeringRiskValue = volume.engineeringRisk?.[voxelIndex] ?? 0;
      const evidenceMask = volume.voxelEvidenceMask?.[voxelIndex] ?? 0;
      const areaM2 = thicknessM * segmentWidthM;
      if (aquiferPotential > 0.28) saturatedAquiferCrossSectionM2 += areaM2;
      if (engineeringRiskValue > 0.62) highRiskCrossSectionM2 += areaM2;
      if (observedSupport > 0.58) calibratedRowCount += 1;
      materialArea[materialClass.id] += areaM2;
      riskArea[riskClass.id] += areaM2;
      meanObservedSupport += observedSupport;
      meanInferenceReliability += inferenceReliability;
      meanEngineeringRisk += engineeringRiskValue;
      maxEngineeringRisk = Math.max(maxEngineeringRisk, engineeringRiskValue);
      rows.push({
        profileId,
        mode,
        sample,
        distanceKm: lengthKm * t,
        xKm,
        yKm,
        sourceX: sx,
        sourceY: sy,
        surfaceIndex,
        columnIndex,
        layer,
        topDepthM,
        bottomDepthM,
        centerDepthM: (topDepthM + bottomDepthM) / 2,
        thicknessM,
        lithology,
        materialClass,
        riskClass,
        porosity,
        permeabilityMmHr: permeability,
        saturation,
        porePressureKpa: volume.porePressureKpa?.[voxelIndex] ?? 0,
        temperatureC: volume.temperatureC?.[voxelIndex] ?? 0,
        verticalStressKpa: volume.verticalStressKpa?.[voxelIndex] ?? 0,
        fractureRisk: volume.fractureRisk?.[voxelIndex] ?? 0,
        aquiferPotential,
        observedSupport,
        inferenceReliability,
        engineeringRisk: engineeringRiskValue,
        evidenceMask,
        evidenceCodes: evidenceMaskCodes(evidenceMask),
        voxelStorageM3: volume.voxelStorageM3?.[voxelIndex] ?? 0
      });
    }
  }

  const rowDivisor = Math.max(1, rows.length);
  return {
    type: "geolab-subsurface-transect",
    schemaVersion: 1,
    profileId,
    mode,
    start: endpoints.start,
    end: endpoints.end,
    lengthKm,
    sampleCount: samples,
    layerCount: volume.layerCount,
    rowCount: rows.length,
    summary: {
      meanObservedSupport: meanObservedSupport / rowDivisor,
      meanInferenceReliability: meanInferenceReliability / rowDivisor,
      meanEngineeringRisk: meanEngineeringRisk / rowDivisor,
      maxEngineeringRisk,
      saturatedAquiferCrossSectionM2,
      highRiskCrossSectionM2,
      calibratedRowCount,
      dominantMaterialClass: dominantLegendEntry(SUBSURFACE_MATERIAL_CLASSES, materialArea),
      dominantRiskClass: dominantLegendEntry(SUBSURFACE_RISK_CLASSES, riskArea)
    },
    rows
  };
}

export function makeSubsurfaceTransectCSV(input, options = {}) {
  const transect = input?.type === "geolab-subsurface-transect"
    ? input
    : buildSubsurfaceTransect(input, options.params || {}, options);
  const header = [
    "profile_id",
    "mode",
    "sample",
    "distance_km",
    "x_km",
    "y_km",
    "source_x",
    "source_y",
    "layer",
    "top_depth_m",
    "bottom_depth_m",
    "center_depth_m",
    "lithology",
    "material_class",
    "risk_class",
    "porosity",
    "permeability_mm_hr",
    "saturation",
    "pore_pressure_kpa",
    "temperature_c",
    "vertical_stress_kpa",
    "fracture_risk",
    "aquifer_potential",
    "observed_support",
    "inference_reliability",
    "engineering_risk",
    "evidence_mask",
    "voxel_storage_m3"
  ];
  return [
    header.join(","),
    ...transect.rows.map((row) => [
      row.profileId,
      row.mode,
      row.sample,
      round(row.distanceKm, 4),
      round(row.xKm, 4),
      round(row.yKm, 4),
      row.sourceX,
      row.sourceY,
      row.layer,
      round(row.topDepthM, 3),
      round(row.bottomDepthM, 3),
      round(row.centerDepthM, 3),
      row.lithology?.code || "",
      row.materialClass?.code || "",
      row.riskClass?.code || "",
      round(row.porosity, 4),
      round(row.permeabilityMmHr, 4),
      round(row.saturation, 4),
      round(row.porePressureKpa, 4),
      round(row.temperatureC, 3),
      round(row.verticalStressKpa, 3),
      round(row.fractureRisk, 4),
      round(row.aquiferPotential, 4),
      round(row.observedSupport, 4),
      round(row.inferenceReliability, 4),
      round(row.engineeringRisk, 4),
      row.evidenceCodes?.join("|") || "",
      round(row.voxelStorageM3, 4)
    ].map(csvValue).join(","))
  ].join("\n");
}

export function buildLocalRefinementTile(model, params = {}, centerGx = null, centerGy = null, options = {}) {
  if (!model?.height?.length || !model.n) throw new Error("A model is required for local refinement");
  const spanCells = clampInteger(options.windowCells ?? 17, 3, 129, 17);
  const refinementFactor = clampInteger(options.refinementFactor ?? 16, 2, 64, 16);
  const resolution = clampInteger(options.resolution ?? spanCells * refinementFactor, 16, 4096, spanCells * refinementFactor);
  const includeRows = options.includeRows !== false;
  const cx = clamp(Number(centerGx ?? (model.n - 1) / 2), 0, model.n - 1);
  const cy = clamp(Number(centerGy ?? (model.n - 1) / 2), 0, model.n - 1);
  const startGx = clamp(cx - spanCells / 2, 0, model.n - 1);
  const startGy = clamp(cy - spanCells / 2, 0, model.n - 1);
  const endGx = clamp(startGx + spanCells, 0, model.n - 1);
  const endGy = clamp(startGy + spanCells, 0, model.n - 1);
  const actualSpanX = Math.max(1 / refinementFactor, endGx - startGx);
  const actualSpanY = Math.max(1 / refinementFactor, endGy - startGy);
  const sourceCellSizeM = model.cellSizeKm * 1000;
  const refinedCellSizeM = ((actualSpanX + actualSpanY) * sourceCellSizeM) / (2 * resolution);
  const len = resolution * resolution;
  const height = new Float32Array(len);
  const fields = includeRows ? new Array(len) : null;
  const statsAccumulator = {
    minElevation: Infinity,
    maxElevation: -Infinity,
    meanElevation: 0,
    meanSourceSlope: 0,
    meanMicroReliefAbs: 0,
    maxMicroReliefAbs: 0,
    meanVegetation: 0,
    meanImpervious: 0,
    meanHazard: 0,
    meanFlood: 0,
    meanWetness: 0,
    highHazard: 0,
    highFlood: 0,
    channelLike: 0
  };
  const seed = Number(params.seed) || 0;
  const demQuality = model.stats?.externalQuality?.find((item) => item.key === "dem") || null;

  for (let y = 0; y < resolution; y += 1) {
    for (let x = 0; x < resolution; x += 1) {
      const i = y * resolution + x;
      const gx = startGx + ((x + 0.5) / resolution) * actualSpanX;
      const gy = startGy + ((y + 0.5) / resolution) * actualSpanY;
      const sourceIndex = nearestModelIndex(model, gx, gy);
      const roughness = sampleModelArray(model, model.terrainDiagnostics?.roughness, gx, gy);
      const slope = sampleModelArray(model, model.slope, gx, gy);
      const microReliefM = localRefinementMicroRelief(model, params, gx, gy, roughness, slope, seed);
      const elevation = clamp(sampleModelArray(model, model.height, gx, gy) + microReliefM, 0, MAX_TERRAIN_ELEVATION_M);
      const xKm = gx * model.cellSizeKm;
      const yKm = gy * model.cellSizeKm;
      const wetness = sampleModelArray(model, model.wetnessIndex, gx, gy);
      const vegetation = sampleModelArray(model, model.surface?.vegetation, gx, gy);
      const projectedVegetation = sampleModelArray(model, model.hazards?.currentProjectedVegetation ?? model.hazards?.projectedVegetation, gx, gy);
      const impervious = sampleModelArray(model, model.surface?.imperviousFraction, gx, gy);
      const flowAccumulation = sampleModelArray(model, model.flowAccumulation, gx, gy);
      const flowVelocity = sampleModelArray(model, model.hydraulics?.flowVelocity, gx, gy);
      const floodHazard = sampleModelArray(model, model.hazards?.currentFloodHazard ?? model.hazards?.floodHazard, gx, gy);
      const hazardIndex = sampleModelArray(model, model.hazards?.currentHazardIndex ?? model.hazards?.hazardIndex, gx, gy);
      height[i] = elevation;
      statsAccumulator.minElevation = Math.min(statsAccumulator.minElevation, elevation);
      statsAccumulator.maxElevation = Math.max(statsAccumulator.maxElevation, elevation);
      statsAccumulator.meanElevation += elevation;
      statsAccumulator.meanSourceSlope += slope;
      const microAbs = Math.abs(microReliefM);
      statsAccumulator.meanMicroReliefAbs += microAbs;
      statsAccumulator.maxMicroReliefAbs = Math.max(statsAccumulator.maxMicroReliefAbs, microAbs);
      statsAccumulator.meanVegetation += projectedVegetation || vegetation || 0;
      statsAccumulator.meanImpervious += impervious || 0;
      statsAccumulator.meanHazard += hazardIndex || 0;
      statsAccumulator.meanFlood += floodHazard || 0;
      statsAccumulator.meanWetness += wetness || 0;
      if ((hazardIndex || 0) >= 0.65) statsAccumulator.highHazard += 1;
      if ((floodHazard || 0) >= 0.65) statsAccumulator.highFlood += 1;
      if ((flowAccumulation || 0) >= Number(model.stats?.riverThresholdKm2 || 72) || (flowVelocity || 0) > 0.25) {
        statsAccumulator.channelLike += 1;
      }
      if (includeRows) {
        fields[i] = {
          x_km: xKm,
          y_km: yKm,
          source_grid_x: gx,
          source_grid_y: gy,
          source_index: sourceIndex,
          elevation_m: elevation,
          micro_relief_m: microReliefM,
          source_slope_deg: slope,
          source_aspect_deg: sampleModelAngle(model, model.aspect, gx, gy),
          curvature_1km: sampleModelArray(model, model.terrainDiagnostics?.curvature, gx, gy),
          tpi_m: sampleModelArray(model, model.terrainDiagnostics?.tpi, gx, gy),
          roughness_m: roughness,
          wetness_index: wetness,
          precipitation_mm_yr: sampleModelArray(model, model.precipitation, gx, gy),
          temp_c: sampleModelArray(model, model.temperature, gx, gy),
          wind_speed_ms: sampleModelArray(model, model.windSpeed, gx, gy),
          wind_from_deg: sampleModelAngle(model, model.windDirection, gx, gy),
          vegetation_fraction: vegetation,
          projected_vegetation_fraction: projectedVegetation,
          canopy_height_m: sampleModelArray(model, model.surface?.canopyHeight, gx, gy),
          lai: sampleModelArray(model, model.surface?.leafAreaIndex, gx, gy),
          impervious_fraction: impervious,
          infiltration_capacity: sampleModelArray(model, model.surface?.infiltrationCapacity, gx, gy),
          runoff_coefficient: sampleModelArray(model, model.runoffCoefficient, gx, gy),
          flow_acc_km2: flowAccumulation,
          discharge_index: sampleModelArray(model, model.discharge, gx, gy),
          flow_velocity_ms: flowVelocity,
          shear_stress_pa: sampleModelArray(model, model.hydraulics?.shearStressPa, gx, gy),
          stream_power_w_m2: sampleModelArray(model, model.hydraulics?.streamPowerWm2, gx, gy),
          erosion_risk: sampleModelArray(model, model.hydraulics?.erosionRisk, gx, gy),
          deposition_risk: sampleModelArray(model, model.hydraulics?.depositionRisk, gx, gy),
          flood_hazard: floodHazard,
          drought_stress: sampleModelArray(model, model.hazards?.currentDroughtStress ?? model.hazards?.droughtStress, gx, gy),
          wildfire_risk: sampleModelArray(model, model.hazards?.currentWildfireRisk ?? model.hazards?.wildfireRisk, gx, gy),
          landslide_risk: sampleModelArray(model, model.hazards?.currentLandslideRisk ?? model.hazards?.landslideRisk, gx, gy),
          hazard_index: hazardIndex,
          cumulative_erosion_m: sampleModelArray(model, model.hazards?.currentCumulativeErosionM ?? model.hazards?.cumulativeErosionM, gx, gy),
          climate_code: climateCodeAt(model, gx, gy),
          landcover_code: landCoverCodeAt(model, gx, gy),
          soil_hsg: soilGroupCodeAt(model, gx, gy)
        };
      }
    }
  }

  const stats = localRefinementStats(model, height, statsAccumulator, resolution, refinedCellSizeM);
  const precision = localRefinementPrecisionReport({
    sourceCellSizeM,
    refinedCellSizeM,
    refinementFactor,
    resolution,
    spanCells,
    demQuality,
    model
  });
  const tile = {
    type: "geolab-local-refinement-tile",
    method: "bilinear-model-field-downscaling-with-deterministic-subcell-microrelief",
    resolution,
    windowCells: spanCells,
    refinementFactor,
    sourceCellSizeM: round(sourceCellSizeM, 3),
    refinedCellSizeM: round(refinedCellSizeM, 3),
    centerGrid: { x: round(cx, 4), y: round(cy, 4) },
    centerKm: { x: round(cx * model.cellSizeKm, 4), y: round(cy * model.cellSizeKm, 4) },
    boundsGrid: [round(startGx, 4), round(startGy, 4), round(endGx, 4), round(endGy, 4)],
    boundsKm: [round(startGx * model.cellSizeKm, 4), round(startGy * model.cellSizeKm, 4), round(endGx * model.cellSizeKm, 4), round(endGy * model.cellSizeKm, 4)],
    sourceResolution: `${model.n}x${model.n}`,
    targetResolution: `${resolution}x${resolution}`,
    demQuality: demQuality
      ? {
          sourceName: demQuality.sourceName,
          coverage: demQuality.coverage,
          effectiveCoverage: demQuality.effectiveCoverage,
          sourceCellSizeM: demQuality.sourceCellSizeM,
          targetCellSizeM: demQuality.targetCellSizeM,
          warnings: demQuality.warnings || []
        }
      : null,
    precision,
    fields: LOCAL_REFINEMENT_COLUMNS,
    summary: stats
  };
  if (includeRows) tile.rows = fields.map((field, i) => localRefinementRow(field, height, resolution, i, refinedCellSizeM));
  return tile;
}

function localRefinementPrecisionReport({ sourceCellSizeM, refinedCellSizeM, refinementFactor, resolution, spanCells, demQuality, model }) {
  const observedCellM = meanCellSizeM(demQuality?.sourceCellSizeM || demQuality?.nativeCellSizeM);
  const targetCellM = meanCellSizeM(demQuality?.targetCellSizeM) || sourceCellSizeM;
  const hasObservedSupport = Number.isFinite(observedCellM) && observedCellM <= refinedCellSizeM * 1.25;
  const modelToRefinedRatio = sourceCellSizeM / Math.max(refinedCellSizeM, 1e-9);
  return {
    class: hasObservedSupport ? "observed-dem-supported" : "model-downscaled",
    interpretationZh: hasObservedSupport
      ? "局部精细单元达到或接近导入 DEM 原生像元，精细化主要由观测 DEM 支撑。"
      : "局部精细单元细于当前观测源像元，亚格细节来自模型场双线性下推与确定性微地形，不应当作独立观测 DEM。",
    sourceCellSizeM: round(sourceCellSizeM, 3),
    refinedCellSizeM: round(refinedCellSizeM, 3),
    modelToRefinedRatio: round(modelToRefinedRatio, 3),
    refinementFactor,
    windowCells: spanCells,
    outputResolution: resolution,
    observedDemCellSizeM: Number.isFinite(observedCellM) ? round(observedCellM, 3) : null,
    observedTargetCellSizeM: Number.isFinite(targetCellM) ? round(targetCellM, 3) : null,
    demCoverage: Number.isFinite(demQuality?.coverage) ? round(demQuality.coverage, 4) : null,
    demEffectiveCoverage: Number.isFinite(demQuality?.effectiveCoverage) ? round(demQuality.effectiveCoverage, 4) : null,
    sourceResolution: model ? `${model.n}x${model.n}` : null,
    targetResolution: `${resolution}x${resolution}`
  };
}

export function makeLocalRefinementCSV(tile) {
  if (!tile?.rows?.length) throw new Error("Local refinement tile has no rows to export");
  return [
    LOCAL_REFINEMENT_COLUMNS.join(","),
    ...tile.rows.map((row) => LOCAL_REFINEMENT_COLUMNS.map((key) => csvValue(row[key])).join(","))
  ].join("\n");
}

export function buildTimeProgressionSeries(model, params = {}, options = {}) {
  if (!model?.hazards) throw new Error("A model with computed hazards is required for time progression series");
  const targetYears = clampInteger(options.targetYears ?? params.simulationYears ?? model.hazards.years ?? 0, 0, 250, 0);
  const requestedStep = clampInteger(options.stepYears ?? 1, 1, Math.max(1, targetYears || 1), 1);
  const stepYears = targetYears > 120 && options.stepYears === undefined ? Math.ceil(targetYears / 120) : requestedStep;
  const years = [];
  for (let year = 0; year <= targetYears; year += stepYears) years.push(year);
  if (!years.includes(targetYears)) years.push(targetYears);
  const rows = years.map((year) => timeProgressionRow(model, params, year, targetYears));
  return {
    type: "geolab-time-progression-series",
    method: "annualized-cumulative-exposure-vegetation-erosion-water-budget",
    targetYears,
    stepYears,
    rowCount: rows.length,
    sourceCellSizeM: round(model.cellSizeKm * 1000, 3),
    sourceResolution: `${model.n}x${model.n}`,
    columns: TIME_PROGRESSION_COLUMNS,
    assumptions: [
      "hazard susceptibility fields are held spatially fixed and converted to cumulative exposure by return-period style annual exceedance probability",
      "vegetation and erosion are linearly interpolated between current terrain state and target-horizon state",
      "annual water-budget volumes are accumulated from the current modeled annual budget"
    ],
    firstYear: rows[0] || null,
    currentYear: timeProgressionRow(model, params, clamp(Number(params.currentYear ?? targetYears), 0, targetYears), targetYears),
    finalYear: rows[rows.length - 1] || null,
    rows
  };
}

export function makeTimeProgressionCSV(series) {
  if (!series?.rows?.length) throw new Error("Time progression series has no rows to export");
  const columns = series.columns || TIME_PROGRESSION_COLUMNS;
  return [
    columns.join(","),
    ...series.rows.map((row) => columns.map((key) => csvValue(row[key])).join(","))
  ].join("\n");
}

export function buildPhysicalTimeProgressionSeries(model, params = {}, options = {}) {
  if (!model?.surface || !model?.hazards) throw new Error("A model with surface and hazard fields is required for physical time progression");
  const targetYears = clampInteger(options.targetYears ?? params.simulationYears ?? model.hazards.years ?? 0, 0, 250, 0);
  const requestedStep = clampInteger(options.stepYears ?? 1, 1, Math.max(1, targetYears || 1), 1);
  const outputStepYears = targetYears > 120 && options.stepYears === undefined ? Math.ceil(targetYears / 120) : requestedStep;
  const seasonalState = model.hazards?.summary?.seasonalState || computeSeasonalTimeState(model, params);
  const seaLevel = Number(params.seaLevel ?? 0);
  const len = model.height.length;
  const cellAreaM2 = modelCellSupportAreaKm2(model) * 1_000_000;
  const landIndices = [];
  for (let i = 0; i < len; i += 1) {
    if (model.height[i] > seaLevel) landIndices.push(i);
  }
  const landCells = Math.max(1, landIndices.length);
  const state = initializePhysicalTimeState(model, landIndices);
  const rows = [physicalTimeRowFromState(model, params, state, 0, targetYears, landIndices, cellAreaM2)];
  let currentYearRow = rows[0];
  for (let year = 1; year <= targetYears; year += 1) {
    const row = advancePhysicalTimeYear(model, params, state, year, targetYears, landIndices, cellAreaM2, landCells);
    if (year % outputStepYears === 0 || year === targetYears) rows.push(row);
    if (year === clampInteger(params.currentYear ?? targetYears, 0, Math.max(0, targetYears), targetYears)) currentYearRow = row;
  }
  return {
    type: "geolab-physical-time-progression-series",
    method: "annual-soil-water-vegetation-erosion-built-feedback-state-model",
    methodZh: "逐年土壤水库-蒸散-产流-设施滞留-植被-侵蚀反馈状态模型",
    targetYears,
    stepYears: outputStepYears,
    rowCount: rows.length,
    sourceCellSizeM: round(model.cellSizeKm * 1000, 3),
    sourceResolution: `${model.n}x${model.n}`,
    landCellCount: landIndices.length,
    seasonalState,
    columns: PHYSICAL_TIME_PROGRESSION_COLUMNS,
    assumptions: [
      "每个陆地格网使用单层土壤水桶，容量由 AWC、根深和水利设施蓄水修正。",
      "年降水与温度使用确定性多年振荡和灾害模式扰动；若导入气象边界场，则以导入场为基准。",
      "径流、蒸散、补给、滞留、取水、植被恢复/损失和侵蚀累积逐年更新状态。",
      "该过程模型用于长期筛查和一致性审计，不替代二维非恒定水动力、火行为或边坡稳定求解器。"
    ],
    firstYear: rows[0] || null,
    currentYear: currentYearRow,
    finalYear: rows[rows.length - 1] || null,
    rows
  };
}

export function makePhysicalTimeProgressionCSV(series) {
  if (!series?.rows?.length) throw new Error("Physical time progression series has no rows to export");
  const columns = series.columns || PHYSICAL_TIME_PROGRESSION_COLUMNS;
  return [
    columns.join(","),
    ...series.rows.map((row) => columns.map((key) => csvValue(row[key])).join(","))
  ].join("\n");
}

export function buildInfrastructureImpactAtlas(model, params = {}, options = {}) {
  if (!model?.height) throw new Error("A computed model is required for infrastructure impact atlas");
  const influence = model.infrastructureInfluence || null;
  const len = model.height.length;
  const cellAreaKm2 = modelCellSupportAreaKm2(model);
  const cellAreaM2 = cellAreaKm2 * 1_000_000;
  const totalAreaKm2 = model.areaKm2 || MAP_AREA_KM2;
  const highCompositeThreshold = clamp(Number(options.highCompositeThreshold ?? 0.65), 0, 1);
  const groups = new Map();

  if (influence?.mask) {
    for (let i = 0; i < len; i += 1) {
      if (!influence.mask[i]) continue;
      const type = INFRASTRUCTURE_CODE_TYPES[influence.typeCode?.[i] || 0] || "custom";
      let group = groups.get(type);
      if (!group) {
        group = createInfrastructureAtlasGroup(type);
        groups.set(type, group);
      }
      addInfrastructureAtlasCell(group, model, influence, i, cellAreaKm2, cellAreaM2, highCompositeThreshold);
    }
  }

  const affectedCellCount = Array.from(groups.values()).reduce((sum, group) => sum + group.cells, 0);
  const affectedAreaKm2 = affectedCellCount * cellAreaKm2;
  const rows = Array.from(groups.values())
    .map((group) => finalizeInfrastructureAtlasRow(group, {
      cellAreaKm2,
      totalAreaKm2,
      affectedAreaKm2
    }))
    .sort((a, b) => b.cells - a.cells || String(a.type).localeCompare(String(b.type)));

  return {
    type: "geolab-infrastructure-impact-atlas",
    displayName: "人造设施影响图谱",
    generatedAt: new Date().toISOString(),
    method: "type-grouped-built-environment-feedback-atlas",
    methodZh: "按人造设施类型汇总不透水面、热环境、径流、蓄滞、用水、建筑体量和灾害暴露反馈",
    sourceResolution: `${model.n}x${model.n}`,
    sourceCellSizeM: round(model.cellSizeKm * 1000, 3),
    map: {
      sizeKm: model.sizeKm || MAP_SIZE_KM,
      areaKm2: totalAreaKm2,
      resolution: model.n,
      cellAreaKm2: round(cellAreaKm2, 6)
    },
    assumptions: [
      "设施影响来自已导入或手工绘制的人造设施掩膜；重叠区域保留局地影响较强的类型编码。",
      "供水量沿用模型中的灌溉量与少量库容可调度项，需求量沿用设施用水深度；两者是筛查量级，不等同于详细管网调度。",
      "灾害暴露使用当前时间步 hazard index 与建筑密度、高度、不透水面共同构成的面积加权指数。",
      "该图谱用于定位设施类型的环境反馈与后续校准重点，不替代专业二维水动力、城市微气候或结构安全求解器。"
    ],
    summary: infrastructureAtlasSummary(rows, influence, {
      affectedCellCount,
      affectedAreaKm2,
      totalAreaKm2
    }),
    columns: INFRASTRUCTURE_IMPACT_ATLAS_COLUMNS,
    rows
  };
}

export function makeInfrastructureImpactAtlasCSV(atlas) {
  const columns = atlas?.columns || INFRASTRUCTURE_IMPACT_ATLAS_COLUMNS;
  return [
    columns.join(","),
    ...((atlas?.rows || []).map((row) => columns.map((key) => csvValue(row[key])).join(",")))
  ].join("\n");
}

export function buildInfrastructureBlockStateReport(model, params = {}, options = {}) {
  if (!model?.height) throw new Error("A computed model is required for infrastructure block state export");
  const influence = model.infrastructureInfluence || null;
  const blockState = influence?.blockState || null;
  const rows = Array.isArray(blockState?.rows) ? blockState.rows : [];
  return {
    type: "geolab-infrastructure-block-state",
    schemaVersion: 1,
    displayName: "人造设施区块联动状态",
    generatedAt: new Date().toISOString(),
    method: "per-block-environment-adaptive-infrastructure-state-ledger",
    sourceResolution: `${model.n}x${model.n}`,
    sourceCellSizeM: round(model.cellSizeKm * 1000, 3),
    map: {
      sizeKm: model.sizeKm || MAP_SIZE_KM,
      areaKm2: model.areaKm2 || MAP_AREA_KM2,
      resolution: model.n,
      cellAreaKm2: round(modelCellSupportAreaKm2(model), 6)
    },
    infrastructure: influence
      ? {
          sourceName: influence.sourceName,
          featureCount: influence.featureCount,
          appliedFeatureCount: influence.appliedFeatureCount,
          affectedCellCount: influence.cellCount,
          candidateCellCount: influence.candidateCellCount || 0,
          selectedCandidateCellCount: influence.selectedCandidateCellCount || 0,
          rejectedCandidateCellCount: influence.rejectedCandidateCellCount || 0,
          lowSuitabilityRejectCount: influence.lowSuitabilityRejectCount || 0,
          classCellCounts: influence.classCellCounts || {},
          placementClassCounts: influence.placementClassCounts || {},
          adaptivePlacement: influence.adaptivePlacement || null
        }
      : null,
    summary: blockState ? infrastructureBlockStateSummary(blockState, options) : {
      status: "no-infrastructure-block-state",
      blockCount: 0,
      occupiedBlockCount: 0,
      rowsOmittedFromSummary: false
    },
    columns: INFRASTRUCTURE_BLOCK_STATE_COLUMNS,
    rows
  };
}

export function makeInfrastructureBlockStateCSV(input, options = {}) {
  const report = input?.type === "geolab-infrastructure-block-state"
    ? input
    : buildInfrastructureBlockStateReport(input, options.params || {}, options);
  const columns = report?.columns || INFRASTRUCTURE_BLOCK_STATE_COLUMNS;
  return [
    columns.join(","),
    ...((report?.rows || []).map((row) => columns.map((key) => csvValue(row[key])).join(",")))
  ].join("\n");
}

export function buildInfrastructureCellPlacementLedger(model, params = {}, options = {}) {
  if (!model?.height) throw new Error("A computed model is required for infrastructure cell placement ledger");
  const influence = model.infrastructureInfluence || null;
  const includeEmpty = options.includeEmpty === true;
  const maxRows = clampInteger(options.maxRows ?? 120000, 1, 2_000_000, 120000);
  const blockCellSize = influence?.blockCellSize || infrastructureBlockCellSize(model);
  const blockGridSize = influence?.blockGridSize || Math.max(1, Math.ceil(model.n / blockCellSize));
  const blockRows = new Map((influence?.blockState?.rows || []).map((row) => [row.block_id, row]));
  const rows = [];
  const summary = {
    status: influence ? "ready" : "no-infrastructure",
    sourceCellCount: model.height.length,
    candidateCellCount: 0,
    selectedCellCount: 0,
    rejectedCellCount: 0,
    emptyCellCount: 0,
    exportedRowCount: 0,
    omittedRowCount: 0,
    includeEmpty,
    maxRows,
    statusCounts: {},
    rejectReasonCounts: {},
    facilityTypeCounts: {},
    serviceClassCounts: {},
    meanSelectedSuitability: 0,
    meanRejectedSuitability: 0,
    meanBlockStructureScore: 0,
    meanBlockLinkageScore: 0
  };
  let selectedSuitabilitySum = 0;
  let rejectedSuitabilitySum = 0;
  let structureSum = 0;
  let linkageSum = 0;

  for (let i = 0; i < model.height.length; i += 1) {
    const rawStatus = influence?.candidateStatusCode?.[i] || (influence?.mask?.[i] ? INFRASTRUCTURE_CANDIDATE_STATUS.selected : 0);
    if (!rawStatus && !includeEmpty) continue;
    const statusCode = rawStatus || INFRASTRUCTURE_CANDIDATE_STATUS.none;
    const blockId = influence?.blockId?.[i] ?? infrastructureBlockId(i, model, blockCellSize);
    const blockRow = blockRows.get(blockId) || null;
    const row = infrastructureCellPlacementLedgerRow(model, params, influence, i, statusCode, blockCellSize, blockGridSize, blockRow);
    if (statusCode === INFRASTRUCTURE_CANDIDATE_STATUS.selected) {
      summary.selectedCellCount += 1;
      selectedSuitabilitySum += row.suitability_score || 0;
    } else if (statusCode === INFRASTRUCTURE_CANDIDATE_STATUS.rejected) {
      summary.rejectedCellCount += 1;
      rejectedSuitabilitySum += row.suitability_score || 0;
    } else {
      summary.emptyCellCount += 1;
    }
    if (statusCode) summary.candidateCellCount += 1;
    structureSum += row.block_structure_score || 0;
    linkageSum += row.block_linkage_score || 0;
    incrementCountMap(summary.statusCounts, row.placement_state, 1);
    if (row.reject_reason) incrementCountMap(summary.rejectReasonCounts, row.reject_reason, 1);
    if (row.facility_type) incrementCountMap(summary.facilityTypeCounts, row.facility_type, 1);
    if (row.service_class) incrementCountMap(summary.serviceClassCounts, row.service_class, 1);
    if (rows.length < maxRows) {
      rows.push(row);
    } else {
      summary.omittedRowCount += 1;
    }
  }

  summary.exportedRowCount = rows.length;
  summary.meanSelectedSuitability = round(selectedSuitabilitySum / Math.max(1, summary.selectedCellCount), 5);
  summary.meanRejectedSuitability = round(rejectedSuitabilitySum / Math.max(1, summary.rejectedCellCount), 5);
  summary.meanBlockStructureScore = round(structureSum / Math.max(1, summary.candidateCellCount || summary.exportedRowCount), 5);
  summary.meanBlockLinkageScore = round(linkageSum / Math.max(1, summary.candidateCellCount || summary.exportedRowCount), 5);
  summary.selectedFractionOfCandidates = summary.candidateCellCount > 0 ? round(summary.selectedCellCount / summary.candidateCellCount, 5) : 0;

  return {
    type: "geolab-infrastructure-cell-placement-ledger",
    schemaVersion: 1,
    displayName: "\u8bbe\u65bd\u5019\u9009\u5355\u5143\u5e03\u7f6e\u8d26\u672c",
    generatedAt: new Date().toISOString(),
    method: "cell-level-facility-candidate-selection-rejection-ledger",
    methodZh: "\u9010\u683c\u8bb0\u5f55\u8bbe\u65bd\u5019\u9009\u5355\u5143\u7684\u9009\u4e2d\u3001\u62d2\u7edd\u3001\u533a\u5757\u7ed3\u6784\u3001\u73af\u5883\u95e8\u69db\u548c\u90bb\u57df\u8054\u52a8\u72b6\u6001\u3002",
    map: {
      sizeKm: model.sizeKm || MAP_SIZE_KM,
      areaKm2: model.areaKm2 || MAP_AREA_KM2,
      resolution: model.n,
      cellAreaKm2: round(modelCellSupportAreaKm2(model), 6),
      blockCellSize,
      blockGridSize
    },
    assumptions: [
      "Rows are emitted for candidate and selected infrastructure cells by default; pass includeEmpty=true to include the full grid.",
      "Rejected rows preserve why a candidate cell was not selected: hard suitability gate, block capacity, intra-block spacing, or stochastic dispersal.",
      "Facility demand is intentionally stricter than free drawing: each type is screened against terrain, wetness, flow, wind, vegetation, imperviousness, hazards, block capacity, and neighborhood linkage."
    ],
    summary,
    columns: INFRASTRUCTURE_CELL_PLACEMENT_COLUMNS,
    rows
  };
}

