function infrastructureBlockCellSize(model) {
  const n = Math.max(1, Number(model?.n) || 1);
  if (n <= 64) return Math.max(2, Math.ceil(n / 16));
  return Math.max(4, Math.ceil(n / 64));
}

function infrastructureBlockId(index, model, blockCellSize = infrastructureBlockCellSize(model)) {
  const n = Math.max(1, Number(model?.n) || 1);
  const grid = Math.max(1, Math.ceil(n / Math.max(1, blockCellSize)));
  const x = index % n;
  const y = Math.floor(index / n);
  const bx = clamp(Math.floor(x / blockCellSize), 0, grid - 1);
  const by = clamp(Math.floor(y / blockCellSize), 0, grid - 1);
  return by * grid + bx;
}

