function buildSubsurfaceObservationQualityReport(subsurface, targetBounds, n, spatialContext = null) {
  const transform = layerTransformInfo(subsurface, spatialContext);
  const targetCellSizeM = boundsCellSizeM(targetBounds, n - 1, n - 1);
  const sourceAreaKm2 = boundsAreaKm2(transform.sourceBoundsKm);
  const targetAreaKm2 = boundsAreaKm2(targetBounds);
  const overlapAreaKm2 = boundsOverlapAreaKm2(transform.sourceBoundsKm, targetBounds);
  const observationCount = subsurface.observationCount || subsurface.observations?.length || 0;
  const boreholeCount = subsurface.boreholeCount || 0;
  const warnings = [...transform.warnings];
  if (!observationCount) warnings.push("subsurface observation layer has no usable borehole, water-table, or lithology records");
  if (!subsurface.waterTableObservationCount && !subsurface.intervalCount) {
    warnings.push("subsurface observations do not include water-table depth or lithology intervals");
  }
  if (overlapAreaKm2 === 0) warnings.push("subsurface observation bounds do not overlap the current model target bounds");
  const evidenceScore = clamp(
    (boreholeCount > 0 ? 0.35 : 0) +
      (subsurface.waterTableObservationCount > 0 ? 0.24 : 0) +
      (subsurface.bedrockObservationCount > 0 ? 0.16 : 0) +
      (subsurface.intervalCount > 0 ? 0.25 : 0),
    0,
    1
  );
  return {
    key: "subsurface",
    sourceName: subsurface.sourceName || "subsurface-observations",
    sourceFormat: subsurface.sourceFormat || "GeoJSON/CSV/JSON",
    crs: subsurface.crs || "unknown",
    crsInterpretation: transform.crsInterpretation,
    sourceBounds: subsurface.bounds || subsurface.boundsKm || null,
    sourceBoundsWgs84: transform.sourceBoundsWgs84,
    sourceBoundsKm: transform.sourceBoundsKm,
    targetBounds,
    sourceResolution: `${observationCount} observations / ${boreholeCount} boreholes`,
    targetResolution: `${n}x${n}`,
    targetCellSizeM,
    sourceAreaKm2,
    targetAreaKm2,
    overlapAreaKm2,
    coverage: Math.min(1, observationCount / Math.max(1, Math.sqrt(n))),
    effectiveCoverage: evidenceScore,
    vectorFeatureCount: subsurface.featureCount || observationCount,
    observationCount,
    boreholeCount,
    waterTableObservationCount: subsurface.waterTableObservationCount || 0,
    bedrockObservationCount: subsurface.bedrockObservationCount || 0,
    lithologyIntervalCount: subsurface.intervalCount || 0,
    aquiferObservationCount: subsurface.aquiferObservationCount || 0,
    hazardObservationCount: subsurface.hazardObservationCount || 0,
    warnings
  };
}

function rasterGapWarnings(key, data, coverage, effectiveCoverage, targetCellSizeM) {
  const warnings = [];
  if (!data) return warnings;
  const filled = data.gapFilledCellCount || 0;
  const unfilled = data.unfilledGapCellCount || 0;
  const total = Math.max(1, data.length || 0);
  if (filled > 0) {
    const maxKm = (data.maxGapFillDistanceCells || 0) * ((targetCellSizeM?.mean || 0) / 1000);
    warnings.push(
      `${key} had ${filled} target cell(s) gap-filled from the nearest valid source value within ${round(maxKm, 2)} km; treat these cells as lower-confidence modeled support`
    );
  }
  if (unfilled > 0) {
    warnings.push(`${key} still has ${unfilled} target cell(s) without valid source support after limited gap filling`);
  }
  if (coverage < 0.85) {
    warnings.push(`${key} source coverage is ${round(coverage * 100, 1)}% before gap filling; avoid interpreting uncovered areas as fully observed`);
  }
  if (effectiveCoverage > coverage && (filled / total) > 0.05) {
    warnings.push(`${key} effective coverage relies on gap filling for ${round((filled / total) * 100, 1)}% of the model grid`);
  }
  return warnings;
}

function layerResolutionDiagnostics(key, source, sourceBoundsKm, targetBounds, n) {
  const sourceCellSizeM = boundsCellSizeM(sourceBoundsKm, source.width, source.height);
  const targetCellSizeM = boundsCellSizeM(targetBounds, n - 1, n - 1);
  const sourceAreaKm2 = boundsAreaKm2(sourceBoundsKm);
  const targetAreaKm2 = boundsAreaKm2(targetBounds);
  const overlapAreaKm2 = boundsOverlapAreaKm2(sourceBoundsKm, targetBounds);
  const warnings = [];
  let resampling = null;
  if (sourceCellSizeM?.mean && targetCellSizeM?.mean) {
    const ratio = sourceCellSizeM.mean / targetCellSizeM.mean;
    const uniformField = Number(source.width) <= 1 && Number(source.height) <= 1;
    let interpretation = "near-native";
    if (uniformField) interpretation = "uniform-field";
    else if (ratio > 6) interpretation = "upsampled-very-coarse";
    else if (ratio > 2) interpretation = "upsampled-coarse";
    else if (ratio < 0.35) interpretation = "downsampled-fine";
    resampling = {
      sourceToTargetRatio: ratio,
      targetToSourceRatio: 1 / ratio,
      interpretation,
      uniformField
    };
    if (uniformField) {
      warnings.push(`${key} is a uniform 1x1 boundary field; no spatial gradients from real source data are represented`);
    } else if (ratio > 2) {
      warnings.push(
        `source cells are ${round(ratio, 1)}x coarser than the model grid; ${key} detail is being upsampled rather than resolved`
      );
    } else if (ratio < 0.35) {
      warnings.push(
        `source cells are ${round(1 / ratio, 1)}x finer than the model grid; increase model resolution to preserve native ${key} detail`
      );
    }
  } else {
    warnings.push("source cell size could not be derived from bounds and raster dimensions");
  }
  const native = normalizeCellSizeObject(source.nativeCellSizeM || source.nativePixelSizeM || source.nativePixelSize);
  if (native?.mean && sourceCellSizeM?.mean) {
    const mismatch = Math.abs(native.mean - sourceCellSizeM.mean) / Math.max(sourceCellSizeM.mean, 1);
    if (mismatch > 0.5 && native.unit && !String(native.unit).toLowerCase().includes("degree")) {
      warnings.push(
        `native pixel size metadata (${round(native.mean, 2)} ${native.unit}) differs from bounds-derived cell size (${round(sourceCellSizeM.mean, 2)} m); verify projection and clipping metadata`
      );
    }
  }
  if (source.rasterizedVector && sourceCellSizeM?.mean && targetCellSizeM?.mean && sourceCellSizeM.mean > targetCellSizeM.mean * 1.5) {
    warnings.push("vector polygons were rasterized coarser than the model grid; increase rasterWidth/rasterHeight for sharper boundaries");
  }
  if (key === "dem" && !source.verticalUnit && !source.valueUnit) {
    warnings.push("DEM vertical unit is not declared; assuming elevation values are meters");
  }
  return {
    sourceCellSizeM,
    targetCellSizeM,
    sourceAreaKm2,
    targetAreaKm2,
    overlapAreaKm2,
    resampling,
    warnings
  };
}

function boundsCellSizeM(bounds, widthCells, heightCells) {
  if (!Array.isArray(bounds) || bounds.length < 4) return null;
  const [x0, y0, x1, y1] = bounds.map(Number);
  const width = Number(widthCells);
  const height = Number(heightCells);
  if (![x0, y0, x1, y1, width, height].every(Number.isFinite) || width <= 0 || height <= 0) return null;
  const x = (Math.abs(x1 - x0) * 1000) / width;
  const y = (Math.abs(y1 - y0) * 1000) / height;
  return { x, y, mean: (x + y) / 2 };
}

function boundsAreaKm2(bounds) {
  if (!Array.isArray(bounds) || bounds.length < 4) return null;
  const [x0, y0, x1, y1] = bounds.map(Number);
  if (![x0, y0, x1, y1].every(Number.isFinite)) return null;
  return Math.abs((x1 - x0) * (y1 - y0));
}

function boundsOverlapAreaKm2(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b) || a.length < 4 || b.length < 4) return null;
  const [ax0, ay0, ax1, ay1] = a.map(Number);
  const [bx0, by0, bx1, by1] = b.map(Number);
  if (![ax0, ay0, ax1, ay1, bx0, by0, bx1, by1].every(Number.isFinite)) return null;
  const x = Math.max(0, Math.min(ax1, bx1) - Math.max(ax0, bx0));
  const y = Math.max(0, Math.min(ay1, by1) - Math.max(ay0, by0));
  return x * y;
}

function normalizeCellSizeObject(value) {
  if (!value) return null;
  let x = Number.NaN;
  let y = Number.NaN;
  let unit = null;
  if (typeof value === "number" || typeof value === "string") {
    x = Number(value);
    y = Number(value);
  } else if (Array.isArray(value) || typeof value.length === "number") {
    x = Math.abs(Number(value[0]));
    y = Math.abs(Number(value[1] ?? value[0]));
  } else if (typeof value === "object") {
    x = Math.abs(Number(value.x ?? value.width ?? value.mean));
    y = Math.abs(Number(value.y ?? value.height ?? value.mean ?? x));
    unit = value.unit || value.units || null;
  }
  if (!Number.isFinite(x) || x <= 0 || !Number.isFinite(y) || y <= 0) return null;
  return { x, y, mean: (x + y) / 2, unit };
}

function finiteCoverage(data) {
  let count = 0;
  for (let i = 0; i < data.length; i += 1) {
    if (Number.isFinite(data[i])) count += 1;
  }
  return data.length ? count / data.length : 0;
}

function fillFloat(length, value) {
  const data = new Float32Array(length);
  data.fill(Number.isFinite(value) ? value : 0);
  return data;
}

function estimatePotentialEvapotranspiration(tempC, latitude, elevation) {
  const heat = Math.max(0, tempC + 5);
  const daylight = clamp(1.14 - Math.abs(latitude) / 140, 0.62, 1.16);
  const elevationDrying = 1 + clamp(elevation / MAX_TERRAIN_ELEVATION_M, 0, 1) * 0.16;
  return clamp(heat * 33.5 * daylight * elevationDrying, 0, 2300);
}

function inferLandCover(elevation, slope, moisture, warmth, index, seed) {
  const noise = hash01(index % 4096, Math.floor(index / 4096), Number(seed) + 515);
  if (moisture > 0.88 && slope < 8 && noise > 0.66) return noise > 0.84 ? 90 : 95;
  if (slope > 33 || (moisture < 0.18 && warmth < 0.4)) return 31;
  if (moisture > 0.56 && warmth > 0.36) return noise > 0.55 ? 41 : 43;
  if (moisture > 0.48 && warmth <= 0.36) return 42;
  if (moisture > 0.34) return noise > 0.62 ? 52 : 71;
  if (elevation < 420 && slope < 6 && noise > 0.72) return noise > 0.88 ? 21 : 82;
  return moisture < 0.22 ? 52 : 71;
}

function nearestLandCover(code) {
  if (code >= 90) return 90;
  if (code >= 80) return 82;
  if (code >= 70) return 71;
  if (code >= 50) return 52;
  if (code >= 40) return 43;
  if (code >= 30) return 31;
  if (code >= 20) return 21;
  if (code >= 10) return 11;
  return 0;
}

function inferSoilGroup(slope, elevation, moisture, index, seed) {
  const noise = hash01(index % 2048, Math.floor(index / 2048), Number(seed) + 751);
  if (moisture > 0.82 || slope < 2) return noise > 0.55 ? 4 : 3;
  if (slope > 26 || elevation > 1500) return noise > 0.35 ? 2 : 1;
  if (moisture < 0.28) return noise > 0.52 ? 1 : 2;
  return noise > 0.58 ? 3 : 2;
}

function soilHydrologyFromGroup(group) {
  if (group === 1) return { infiltration: 0.86, ksatMmHr: 34, availableWaterMm: 115, rootDepthM: 1.55 };
  if (group === 2) return { infiltration: 0.64, ksatMmHr: 13, availableWaterMm: 155, rootDepthM: 1.35 };
  if (group === 3) return { infiltration: 0.38, ksatMmHr: 4.2, availableWaterMm: 145, rootDepthM: 1.05 };
  if (group === 4) return { infiltration: 0.16, ksatMmHr: 1.1, availableWaterMm: 105, rootDepthM: 0.72 };
  return { infiltration: 0.5, ksatMmHr: 8, availableWaterMm: 130, rootDepthM: 1.1 };
}

function normalizeHydraulicConductivity(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return Number.NaN;
  return clamp(n, 0.02, 220);
}

function normalizeRootDepth(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return Number.NaN;
  if (n > 50) return clamp(n / 1000, 0.05, 5);
  if (n > 6) return clamp(n / 100, 0.05, 5);
  return clamp(n, 0.05, 5);
}

function normalizeAvailableWater(value, rootDepthM = 1) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return Number.NaN;
  if (n <= 1) return clamp(n * Math.max(0.1, rootDepthM) * 1000, 10, 420);
  return clamp(n, 10, 420);
}

function normalizeFraction(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n < 0) return Number.NaN;
  return clamp(n > 1 ? n / 100 : n, 0, 1);
}

function landCoverRootFactor(code) {
  if (code === 41 || code === 42 || code === 43 || code === 90) return 1.28;
  if (code === 52) return 1.02;
  if (code === 71 || code === 81) return 0.88;
  if (code === 82) return 0.72;
  if (code === 21 || code === 22) return 0.46;
  if (code === 31) return 0.55;
  if (code === 95) return 0.82;
  return 0.78;
}

function vegetationTypeRecord(value) {
  return VEGETATION_TYPES[Math.round(Number(value) || 0)] || VEGETATION_TYPES[0];
}

function inferVegetationType(landCoverCode, cover, canopyHeightM, leafAreaIndex, impervious, moisture, index, seed) {
  if (landCoverCode === 11 || cover <= 0.025) return 0;
  if (impervious > 0.34 && cover > 0.18) return 8;
  if (cover < 0.12 || (landCoverCode === 31 && canopyHeightM < 0.8 && leafAreaIndex < 0.6)) return 9;
  if (landCoverCode === 90 || landCoverCode === 95) return 7;
  if (landCoverCode === 82) return 6;
  if (landCoverCode === 71 || landCoverCode === 81) return 5;
  if (landCoverCode === 52) return 4;
  if (landCoverCode === 41) return 1;
  if (landCoverCode === 42) return 2;
  if (landCoverCode === 43) return 3;
  if (landCoverCode === 21 || landCoverCode === 22) return cover > 0.34 ? 8 : 9;
  if (canopyHeightM > 8 && cover > 0.55) {
    const coniferSignal = hash01(index % 4096, Math.floor(index / 4096), Number(seed) + 433) + (0.55 - moisture) * 0.35;
    if (coniferSignal > 0.68) return 2;
    if (coniferSignal < 0.28) return 1;
    return 3;
  }
  if (canopyHeightM > 2.4 || leafAreaIndex > 2.2) return 4;
  if (cover > 0.28) return 5;
  return 9;
}

function estimateBiomassCarbonKgM2(vegetationInfo, cover, canopyHeightM, leafAreaIndex, rootDepthM, impervious) {
  return clamp(
    cover * (canopyHeightM * 0.26 + leafAreaIndex * 0.55 + rootDepthM * 0.95) * vegetationInfo.biomassFactor * (1 - impervious * 0.58),
    0,
    48
  );
}

function inferImperviousFraction(code, slope, vegetation) {
  let base = 0.02;
  if (code === 21) base = 0.22;
  else if (code === 22) base = 0.46;
  else if (code === 82) base = 0.05;
  else if (code === 31) base = 0.03;
  else if (code === 11) base = 1;
  return clamp(base + Math.max(0, 0.18 - vegetation * 0.18) + Math.max(0, slope - 28) * 0.002, 0, 0.95);
}

function applyTerrainPresetColor(baseColor, model, params, i, t) {
  const plan = terrainPresetMaterialPlan(params, model.stats);
  if (!plan.active || plan.blend <= 0) return baseColor;
  const material = TERRAIN_PRESET_MATERIALS[plan.geomorphologyPreset] || TERRAIN_PRESET_MATERIALS.custom;
  const slopeNorm = clamp((model.slope?.[i] ?? 0) / 48, 0, 1);
  const roughMax = Math.max(120, model.stats?.maxRoughness ?? 180);
  const roughNorm = clamp((model.terrainDiagnostics?.roughness?.[i] ?? 0) / roughMax, 0, 1);
  const wetNorm = clamp((model.wetnessIndex?.[i] ?? 0) / 15, 0, 1);
  const vegetation = clamp(model.surface?.vegetation?.[i] ?? 0, 0, 1);
  const n = Math.max(1, model.n || 1);
  const x = (i % n) / n;
  const y = Math.floor(i / n) / n;
  const seed = (Number(params.seed) || 1) * 0.00017;
  const windRadians = ((Number(params.windDirection) || 0) * Math.PI) / 180;
  const windProjected = x * Math.cos(windRadians) + y * Math.sin(windRadians);
  const band = 0.5 + 0.5 * Math.sin((t * material.bandFrequency + windProjected * 3.2 + seed) * Math.PI * 2);
  let preset = ramp(t, 0, 1, material.stops);

  if (plan.geomorphologyPreset === "canyon_plateau") {
    preset = blendRgb(preset, [104, 58, 50], 0.12 + band * 0.2 + roughNorm * 0.08);
    preset = blendRgb(preset, [236, 208, 158], clamp((1 - slopeNorm) * t * 0.18, 0, 0.18));
  } else if (plan.geomorphologyPreset === "karst_towers") {
    preset = blendRgb(preset, [225, 224, 205], clamp(slopeNorm * 0.32 + roughNorm * 0.26, 0, 0.46));
    preset = blendRgb(preset, [38, 105, 70], clamp((1 - t) * vegetation * 0.28 + wetNorm * 0.16, 0, 0.34));
  } else if (plan.geomorphologyPreset === "alpine_glacier") {
    const snow = smoothstep(0.56, 0.9, t) * 0.55 + clamp(slopeNorm * 0.16, 0, 0.16);
    preset = blendRgb(preset, [245, 248, 248], clamp(snow, 0, 0.72));
    preset = blendRgb(preset, [145, 187, 205], clamp((1 - vegetation) * wetNorm * smoothstep(0.36, 0.72, t) * 0.24, 0, 0.24));
  } else if (plan.geomorphologyPreset === "volcanic_island") {
    preset = blendRgb(preset, [38, 42, 43], clamp(0.22 + roughNorm * 0.28, 0, 0.48));
    preset = blendRgb(preset, [182, 76, 48], clamp(t * roughNorm * 0.22 + band * 0.08, 0, 0.28));
  } else if (plan.geomorphologyPreset === "delta_wetland") {
    preset = blendRgb(preset, [61, 132, 124], clamp(wetNorm * 0.38, 0, 0.38));
    preset = blendRgb(preset, [42, 110, 74], clamp(vegetation * (1 - t) * 0.3, 0, 0.3));
  } else if (plan.geomorphologyPreset === "desert_dune") {
    const dune = 0.5 + 0.5 * Math.sin((windProjected * 22 + t * 5 + seed) * Math.PI * 2);
    preset = blendRgb(preset, [244, 218, 156], clamp(dune * 0.24 + (1 - wetNorm) * 0.12, 0, 0.34));
    preset = blendRgb(preset, [154, 97, 61], clamp(roughNorm * 0.18, 0, 0.18));
  } else if (plan.geomorphologyPreset === "fjord_coast") {
    preset = blendRgb(preset, [42, 58, 63], clamp(slopeNorm * 0.24 + roughNorm * 0.2, 0, 0.38));
    preset = blendRgb(preset, [230, 237, 238], clamp(smoothstep(0.62, 0.93, t) * 0.52, 0, 0.52));
    preset = blendRgb(preset, [73, 112, 83], clamp(wetNorm * vegetation * 0.22, 0, 0.22));
  } else if (plan.geomorphologyPreset === "danxia_mesa") {
    const strata = 0.5 + 0.5 * Math.sin((t * 28 + y * 8 + seed) * Math.PI * 2);
    preset = blendRgb(preset, [126, 58, 64], clamp(strata * 0.26 + roughNorm * 0.08, 0, 0.34));
    preset = blendRgb(preset, [226, 186, 82], clamp((1 - strata) * 0.2, 0, 0.2));
  } else if (plan.geomorphologyPreset === "loess_plateau") {
    preset = blendRgb(preset, [104, 78, 55], clamp(roughNorm * slopeNorm * 0.34, 0, 0.34));
    preset = blendRgb(preset, [226, 190, 112], clamp((1 - roughNorm) * 0.18 + band * 0.08, 0, 0.25));
  } else if (plan.geomorphologyPreset === "badlands_coulee") {
    const rill = 0.5 + 0.5 * Math.sin((x * 26 - y * 31 + seed) * Math.PI * 2);
    preset = blendRgb(preset, [92, 70, 62], clamp(roughNorm * 0.24 + slopeNorm * 0.18, 0, 0.36));
    preset = blendRgb(preset, [217, 181, 130], clamp(Math.pow(rill, 3) * 0.18 + (1 - vegetation) * 0.1, 0, 0.26));
  } else if (plan.geomorphologyPreset === "braided_outwash") {
    const braid = 0.5 + 0.5 * Math.sin((x * 34 + y * 18 + seed) * Math.PI * 2);
    preset = blendRgb(preset, [85, 118, 117], clamp(wetNorm * 0.24 + braid * wetNorm * 0.16, 0, 0.34));
    preset = blendRgb(preset, [198, 186, 148], clamp((1 - slopeNorm) * 0.16 + roughNorm * 0.08, 0, 0.24));
  } else if (plan.geomorphologyPreset === "coastal_cliff") {
    const surf = smoothstep(0.62, 0.95, y);
    preset = blendRgb(preset, [46, 71, 80], clamp(surf * wetNorm * 0.34 + slopeNorm * 0.12, 0, 0.38));
    preset = blendRgb(preset, [221, 205, 168], clamp((1 - slopeNorm) * surf * 0.2, 0, 0.22));
  } else if (plan.geomorphologyPreset === "resurgent_caldera") {
    const ring = 0.5 + 0.5 * Math.sin((Math.hypot(x - 0.5, y - 0.52) * 22 + seed) * Math.PI * 2);
    const hydro = Math.max(
      Math.exp(-Math.pow(Math.hypot(x - 0.38, y - 0.62) * 13, 2)),
      Math.exp(-Math.pow(Math.hypot(x - 0.62, y - 0.42) * 14, 2))
    );
    preset = blendRgb(preset, [60, 62, 63], clamp(roughNorm * 0.18 + slopeNorm * 0.12, 0, 0.28));
    preset = blendRgb(preset, [235, 214, 132], clamp(hydro * 0.48 + ring * wetNorm * 0.14, 0, 0.5));
    preset = blendRgb(preset, [196, 103, 72], clamp(ring * roughNorm * 0.2, 0, 0.22));
  } else if (plan.geomorphologyPreset === "andes_ridge_terrace") {
    const terrace = 0.5 + 0.5 * Math.sin((y * 34 + x * 7 + seed) * Math.PI * 2);
    const ridgeBand = 0.5 + 0.5 * Math.sin((x * 18 - y * 9 + seed) * Math.PI * 2);
    preset = blendRgb(preset, [42, 93, 70], clamp(vegetation * 0.22 + wetNorm * 0.12, 0, 0.32));
    preset = blendRgb(preset, [216, 211, 188], clamp(terrace * 0.2 + (1 - slopeNorm) * 0.08, 0, 0.28));
    preset = blendRgb(preset, [82, 82, 82], clamp(ridgeBand * roughNorm * slopeNorm * 0.3, 0, 0.26));
  } else if (plan.geomorphologyPreset === "travertine_terrace") {
    const pool = 0.5 + 0.5 * Math.sin((y * 26 + x * 8 + seed) * Math.PI * 2);
    const terraceBand = 0.5 + 0.5 * Math.sin((t * 32 + y * 18 + seed) * Math.PI * 2);
    preset = blendRgb(preset, [249, 247, 232], clamp(0.26 + terraceBand * 0.2 + roughNorm * 0.12, 0, 0.56));
    preset = blendRgb(preset, [128, 190, 184], clamp(wetNorm * Math.pow(pool, 2) * 0.34, 0, 0.34));
    preset = blendRgb(preset, [210, 198, 160], clamp((1 - slopeNorm) * wetNorm * 0.16, 0, 0.18));
  } else if (plan.geomorphologyPreset === "hoodoos_amphitheater") {
    const hoodoo = 0.5 + 0.5 * Math.sin((x * 28 - y * 35 + seed) * Math.PI * 2);
    const frostBand = 0.5 + 0.5 * Math.sin((t * 24 + y * 9 + seed) * Math.PI * 2);
    preset = blendRgb(preset, [224, 190, 147], clamp(0.14 + frostBand * 0.18 + (1 - vegetation) * 0.08, 0, 0.36));
    preset = blendRgb(preset, [151, 91, 78], clamp(roughNorm * slopeNorm * 0.28 + Math.pow(hoodoo, 3) * 0.12, 0, 0.34));
    preset = blendRgb(preset, [242, 232, 205], clamp((1 - slopeNorm) * t * 0.16, 0, 0.18));
  } else if (plan.geomorphologyPreset === "limestone_sea_stacks") {
    const surf = smoothstep(0.58, 0.96, y);
    const stackBand = 0.5 + 0.5 * Math.sin((x * 18 + y * 21 + seed) * Math.PI * 2);
    preset = blendRgb(preset, [52, 82, 89], clamp(surf * wetNorm * 0.32 + slopeNorm * 0.1, 0, 0.38));
    preset = blendRgb(preset, [222, 209, 176], clamp((1 - slopeNorm) * 0.18 + stackBand * 0.12, 0, 0.28));
    preset = blendRgb(preset, [106, 104, 92], clamp(roughNorm * surf * 0.18, 0, 0.2));
  } else if (plan.geomorphologyPreset === "quartz_sandstone_pillars") {
    const pillar = 0.5 + 0.5 * Math.sin((x * 24 + y * 27 + seed) * Math.PI * 2);
    const jointShade = 0.5 + 0.5 * Math.sin((x * 37 - y * 18 + seed) * Math.PI * 2);
    preset = blendRgb(preset, [201, 155, 96], clamp(roughNorm * 0.18 + pillar * 0.16, 0, 0.32));
    preset = blendRgb(preset, [44, 103, 69], clamp(vegetation * wetNorm * (1 - t) * 0.32, 0, 0.34));
    preset = blendRgb(preset, [92, 74, 62], clamp(jointShade * slopeNorm * roughNorm * 0.26, 0, 0.24));
  }

  const blend = clamp(plan.blend + roughNorm * 0.06 + slopeNorm * 0.04, 0, 0.72);
  return blendRgb(baseColor, preset, blend);
}

function elevationColor(t, slope) {
  const base = ramp(t, 0, 1, [
    [55, 112, 93],
    [102, 145, 86],
    [157, 146, 95],
    [132, 119, 109],
    [226, 229, 220]
  ]);
  const shade = clamp(1 - slope / 120, 0.72, 1.04);
  return base.map((v) => Math.round(v * shade));
}

function blendRgb(a, b, t) {
  const k = clamp(t, 0, 1);
  return [
    Math.round(lerp(a[0], b[0], k)),
    Math.round(lerp(a[1], b[1], k)),
    Math.round(lerp(a[2], b[2], k))
  ];
}

function ramp(value, min, max, stops) {
  const t = clamp((value - min) / Math.max(0.0001, max - min), 0, 1);
  const scaled = t * (stops.length - 1);
  const i = Math.min(stops.length - 2, Math.floor(scaled));
  const local = scaled - i;
  return [
    Math.round(lerp(stops[i][0], stops[i + 1][0], local)),
    Math.round(lerp(stops[i][1], stops[i + 1][1], local)),
    Math.round(lerp(stops[i][2], stops[i + 1][2], local))
  ];
}

function diverging(value, min, max, stops) {
  const midpoint = stops[Math.floor(stops.length / 2)];
  if (value < 0) return ramp(value, min, 0, [stops[0], midpoint]);
  return ramp(value, 0, max, [midpoint, stops[stops.length - 1]]);
}

function mix3(a, b, c, t) {
  if (t < 0.58) return ramp(t, 0, 0.58, [a, b]);
  return ramp(t, 0.58, 1, [b, c]);
}

function indexToPoint(index, n, cellSizeKm) {
  const x = index % n;
  const y = Math.floor(index / n);
  return { xKm: x * cellSizeKm, yKm: y * cellSizeKm };
}

function distanceKm(a, b) {
  return Math.hypot(a.xKm - b.xKm, a.yKm - b.yKm);
}

function pointToSegmentProjection(point, from, to) {
  const dx = to.xKm - from.xKm;
  const dy = to.yKm - from.yKm;
  const lenSq = dx * dx + dy * dy;
  if (lenSq <= 0) {
    return { xKm: from.xKm, yKm: from.yKm, distanceKm: distanceKm(point, from), t: 0 };
  }
  const t = clamp(((point.xKm - from.xKm) * dx + (point.yKm - from.yKm) * dy) / lenSq, 0, 1);
  const projected = { xKm: from.xKm + dx * t, yKm: from.yKm + dy * t };
  return { ...projected, distanceKm: distanceKm(point, projected), t };
}

function valueNoise(x, y, seed) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const tx = x - xi;
  const ty = y - yi;
  const sx = tx * tx * (3 - 2 * tx);
  const sy = ty * ty * (3 - 2 * ty);
  const a = hash01(xi, yi, seed);
  const b = hash01(xi + 1, yi, seed);
  const c = hash01(xi, yi + 1, seed);
  const d = hash01(xi + 1, yi + 1, seed);
  return lerp(lerp(a, b, sx), lerp(c, d, sx), sy);
}

function fbm(x, y, seed, octaves, lacunarity, gain) {
  let sum = 0;
  let amplitude = 0.5;
  let frequency = 1;
  let normalization = 0;
  for (let octave = 0; octave < octaves; octave += 1) {
    sum += valueNoise(x * frequency, y * frequency, seed + octave * 37) * amplitude;
    normalization += amplitude;
    amplitude *= gain;
    frequency *= lacunarity;
  }
  return sum / normalization;
}

function hash01(x, y, seed) {
  let h = Math.imul(x, 374761393) ^ Math.imul(y, 668265263) ^ Math.imul(seed, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}

class MinHeap {
  constructor() {
    this.items = [];
  }

  get length() {
    return this.items.length;
  }

  push(index, priority) {
    const node = { index, priority };
    this.items.push(node);
    this.bubbleUp(this.items.length - 1);
  }

  pop() {
    const top = this.items[0];
    const end = this.items.pop();
    if (this.items.length > 0) {
      this.items[0] = end;
      this.sinkDown(0);
    }
    return top;
  }

  bubbleUp(index) {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (this.items[parent].priority <= this.items[index].priority) break;
      [this.items[parent], this.items[index]] = [this.items[index], this.items[parent]];
      index = parent;
    }
  }

  sinkDown(index) {
    const length = this.items.length;
    while (true) {
      let left = index * 2 + 1;
      let right = left + 1;
      let smallest = index;
      if (left < length && this.items[left].priority < this.items[smallest].priority) {
        smallest = left;
      }
      if (right < length && this.items[right].priority < this.items[smallest].priority) {
        smallest = right;
      }
      if (smallest === index) break;
      [this.items[smallest], this.items[index]] = [this.items[index], this.items[smallest]];
      index = smallest;
    }
  }
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function maxFinite(values) {
  let max = 0;
  for (const value of values || []) {
    const n = Number(value);
    if (Number.isFinite(n) && n > max) max = n;
  }
  return max;
}

function meanFiniteArray(values, height = null, seaLevel = -Infinity) {
  if (!values) return 0;
  let sum = 0;
  let count = 0;
  for (let i = 0; i < values.length; i += 1) {
    if (height && height[i] <= seaLevel) continue;
    const n = Number(values[i]);
    if (!Number.isFinite(n)) continue;
    sum += n;
    count += 1;
  }
  return count ? sum / count : 0;
}

function normalizeDegrees(value) {
  return ((value % 360) + 360) % 360;
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function smoothstep(edge0, edge1, x) {
  const t = clamp((x - edge0) / Math.max(0.00001, edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

function round(value, decimals) {
  const f = 10 ** decimals;
  return Math.round(value * f) / f;
}

function pctBias(simulated, observed) {
  const s = Number(simulated);
  const o = Number(observed);
  if (!Number.isFinite(s) || !Number.isFinite(o) || o <= 0) return null;
  return ((s - o) / o) * 100;
}

function flowDurationBiasDiagnostics(simulatedM3s, observedSeries) {
  const simulated = Number(simulatedM3s);
  return {
    recordCount: observedSeries.recordCount || 0,
    startDate: observedSeries.startDate || null,
    endDate: observedSeries.endDate || null,
    simulatedSteadyM3s: Number.isFinite(simulated) ? simulated : null,
    meanBiasPct: pctBias(simulated, observedSeries.meanDischargeM3s),
    medianBiasPct: pctBias(simulated, observedSeries.medianDischargeM3s),
    p10BiasPct: pctBias(simulated, observedSeries.p10DischargeM3s),
    p90BiasPct: pctBias(simulated, observedSeries.p90DischargeM3s),
    interpretation: "steady-annual-flow proxy; use a routed hydrograph before treating duration bias as final"
  };
}

function calibrationHydrographDiagnostics(input) {
  const observed = observedHydrographSamples(input.observedSeries);
  if (observed.length < 14) {
    return {
      status: "insufficient-observed-series",
      method: "daily-conceptual-reservoir",
      pairedCount: observed.length,
      warnings: ["At least 14 dated discharge observations are needed for a hydrograph diagnostic."]
    };
  }

  const forcing = dailyForcingByDate(input.metSummaries);
  const forcedPairs = observed.filter((sample) => forcing.has(sample.date));
  if (forcedPairs.length < Math.max(14, observed.length * 0.45)) {
    return {
      status: "missing-daily-forcing",
      method: "daily-conceptual-reservoir",
      observedCount: observed.length,
      pairedCount: forcedPairs.length,
      forcingRecordCount: forcing.size,
      warnings: ["Daily meteorology forcing does not overlap enough dated discharge observations for routed hydrograph scoring."]
    };
  }

  const modelSeries = runConceptualDailyHydrograph({
    observed: forcedPairs,
    forcing,
    targetMeanM3s: input.comparison?.simulatedM3s,
    meanPrecipitationMm: input.meanPrecipitationMm,
    meanActualEtMm: input.meanActualEtMm,
    meanRunoffCoefficient: input.meanRunoffCoefficient,
    meanInfiltrationCapacity: input.meanInfiltrationCapacity,
    meanAvailableWaterCapacityMm: input.meanAvailableWaterCapacityMm,
    meanImperviousFraction: input.meanImperviousFraction,
    meanVegetation: input.meanVegetation,
    meanLeafAreaIndex: input.meanLeafAreaIndex
  });
  const metrics = hydrographSkillMetrics(modelSeries);
  const observedValues = modelSeries.map((row) => row.observedM3s).sort((a, b) => a - b);
  const simulatedValues = modelSeries.map((row) => row.simulatedM3s).sort((a, b) => a - b);
  const first = modelSeries[0];
  const last = modelSeries[modelSeries.length - 1];

  return {
    status: "ready",
    method: "daily-conceptual-reservoir",
    forcing: {
      sourceName: forcing.sourceName || null,
      forcingRecordCount: forcing.size,
      pairedCount: modelSeries.length
    },
    period: {
      startDate: first?.date || null,
      endDate: last?.date || null
    },
    metrics,
    flowDuration: {
      observedP10M3s: percentileSorted(observedValues, 0.1),
      observedP50M3s: percentileSorted(observedValues, 0.5),
      observedP90M3s: percentileSorted(observedValues, 0.9),
      simulatedP10M3s: percentileSorted(simulatedValues, 0.1),
      simulatedP50M3s: percentileSorted(simulatedValues, 0.5),
      simulatedP90M3s: percentileSorted(simulatedValues, 0.9)
    },
    samplePreview: modelSeries.slice(0, 12),
    warnings: hydrographWarnings(metrics)
  };
}

function observedHydrographSamples(observedSeries) {
  const source = Array.isArray(observedSeries?.samples) ? observedSeries.samples : [];
  return source
    .map((sample) => ({
      date: normalizedDate(sample.date),
      observedM3s: Number(sample.dischargeM3s ?? sample.value ?? sample.flowM3s),
      year: Number(sample.year)
    }))
    .filter((sample) => sample.date && Number.isFinite(sample.observedM3s) && sample.observedM3s >= 0)
    .sort((a, b) => a.date.localeCompare(b.date));
}

function dailyForcingByDate(metSummaries) {
  const forcing = new Map();
  for (const summary of metSummaries || []) {
    for (const row of summary?.dailySeries || []) {
      const date = normalizedDate(row.date);
      if (!date) continue;
      const current = forcing.get(date) || { date, precipitationMm: 0, temperatureValues: [], sourceNames: new Set() };
      const precipitation = Number(row.precipitationMm);
      if (Number.isFinite(precipitation) && precipitation > 0) current.precipitationMm += precipitation;
      const temperature = Number(row.temperatureC);
      if (Number.isFinite(temperature)) current.temperatureValues.push(temperature);
      if (summary.sourceName) current.sourceNames.add(summary.sourceName);
      forcing.set(date, current);
    }
  }
  const compact = new Map();
  const sourceNames = new Set();
  for (const [date, row] of forcing.entries()) {
    for (const name of row.sourceNames) sourceNames.add(name);
    compact.set(date, {
      date,
      precipitationMm: row.precipitationMm,
      temperatureC: row.temperatureValues.length ? hydroMean(row.temperatureValues) : null
    });
  }
  compact.sourceName = Array.from(sourceNames).join(" + ");
  return compact;
}

function runConceptualDailyHydrograph(input) {
  const targetMean = Number(input.targetMeanM3s);
  const meanObserved = hydroMean(input.observed.map((row) => row.observedM3s));
  const outletMean = Number.isFinite(targetMean) && targetMean > 0 ? targetMean : meanObserved;
  const annualPrecipMm = Math.max(1, Number(input.meanPrecipitationMm) || 900);
  const annualEtMm = Math.max(0, Number(input.meanActualEtMm) || annualPrecipMm * 0.42);
  const awcMm = clamp(Number(input.meanAvailableWaterCapacityMm) || 120, 25, 420);
  const runoffCoefficient = clamp(Number(input.meanRunoffCoefficient) || 0.25, 0.03, 0.95);
  const infiltration = clamp(Number(input.meanInfiltrationCapacity) || 0.35, 0, 1);
  const impervious = clamp(Number(input.meanImperviousFraction) || 0.05, 0, 0.98);
  const vegetation = clamp(Number(input.meanVegetation) || 0.45, 0, 1);
  const lai = clamp(Number(input.meanLeafAreaIndex) || 1.5, 0, 8);
  const quickFraction = clamp(0.08 + runoffCoefficient * 0.42 + impervious * 0.34 - infiltration * 0.18 - vegetation * 0.08, 0.03, 0.82);
  const recession = clamp(0.72 + infiltration * 0.18 + vegetation * 0.04 - impervious * 0.12, 0.55, 0.94);
  const baseRechargeFraction = clamp(0.06 + infiltration * 0.18 + lai * 0.01, 0.04, 0.34);
  let soilStore = awcMm * 0.45;
  let baseStore = outletMean * 0.4;
  const raw = [];

  for (const sample of input.observed) {
    const forcing = input.forcing.get(sample.date);
    const precip = Math.max(0, Number(forcing?.precipitationMm) || 0);
    const temp = Number(forcing?.temperatureC);
    const temperatureFactor = Number.isFinite(temp) ? clamp((temp + 5) / 28, 0.15, 1.55) : 1;
    const dailyEt = (annualEtMm / 365) * temperatureFactor * clamp(0.72 + vegetation * 0.34 + lai * 0.035, 0.5, 1.45);
    soilStore = clamp(soilStore + precip * (1 - quickFraction * 0.35) - dailyEt, 0, awcMm * 1.8);
    const saturation = clamp(soilStore / Math.max(1, awcMm), 0, 1.8);
    const excess = Math.max(0, soilStore - awcMm);
    const eventRunoffMm = precip * quickFraction * (0.45 + saturation * 0.55) + excess * 0.28;
    soilStore = Math.max(0, soilStore - excess * 0.28);
    const rechargeMm = Math.max(0, precip - eventRunoffMm) * baseRechargeFraction * clamp(0.8 + saturation * 0.25, 0.7, 1.35);
    baseStore = baseStore * recession + rechargeMm * runoffCoefficient;
    const index = Math.max(0.000001, eventRunoffMm + baseStore * 0.06 + (annualPrecipMm / 365) * runoffCoefficient * 0.05);
    raw.push({
      date: sample.date,
      observedM3s: sample.observedM3s,
      forcingPrecipMm: round(precip, 3),
      forcingTempC: Number.isFinite(temp) ? round(temp, 2) : null,
      responseIndex: index
    });
  }

  const indexMean = hydroMean(raw.map((row) => row.responseIndex));
  const scale = outletMean / Math.max(0.000001, indexMean);
  return raw.map((row) => ({
    date: row.date,
    observedM3s: round(row.observedM3s, 4),
    simulatedM3s: round(row.responseIndex * scale, 4),
    forcingPrecipMm: row.forcingPrecipMm,
    forcingTempC: row.forcingTempC
  }));
}

function hydrographSkillMetrics(series) {
  const observed = series.map((row) => Number(row.observedM3s));
  const simulated = series.map((row) => Number(row.simulatedM3s));
  const meanObserved = hydroMean(observed);
  const meanSimulated = hydroMean(simulated);
  const stdObserved = hydroStd(observed, meanObserved);
  const stdSimulated = hydroStd(simulated, meanSimulated);
  const correlation = hydroCorrelation(observed, simulated, meanObserved, meanSimulated, stdObserved, stdSimulated);
  const alpha = stdObserved > 0 ? stdSimulated / stdObserved : null;
  const beta = meanObserved > 0 ? meanSimulated / meanObserved : null;
  const kge = Number.isFinite(correlation) && Number.isFinite(alpha) && Number.isFinite(beta)
    ? 1 - Math.sqrt((correlation - 1) ** 2 + (alpha - 1) ** 2 + (beta - 1) ** 2)
    : null;
  const nse = hydroNse(observed, simulated, meanObserved);
  const rmse = Math.sqrt(hydroMean(observed.map((value, index) => (simulated[index] - value) ** 2)));
  return {
    pairedCount: series.length,
    meanObservedM3s: round(meanObserved, 4),
    meanSimulatedM3s: round(meanSimulated, 4),
    biasPct: pctBias(meanSimulated, meanObserved),
    correlation: Number.isFinite(correlation) ? round(correlation, 4) : null,
    variabilityRatio: Number.isFinite(alpha) ? round(alpha, 4) : null,
    biasRatio: Number.isFinite(beta) ? round(beta, 4) : null,
    kge: Number.isFinite(kge) ? round(kge, 4) : null,
    nse: Number.isFinite(nse) ? round(nse, 4) : null,
    rmseM3s: round(rmse, 4),
    rmsePctOfMean: meanObserved > 0 ? round((rmse / meanObserved) * 100, 2) : null
  };
}

function hydrographWarnings(metrics) {
  const warnings = [];
  if (Number.isFinite(Number(metrics.kge)) && metrics.kge < 0.3) {
    warnings.push("Daily hydrograph KGE is low; timing, variability, or water-balance bias requires forcing/routing review.");
  }
  if (Number.isFinite(Number(metrics.nse)) && metrics.nse < 0) {
    warnings.push("Daily hydrograph NSE is below zero; the simulated time series is weaker than using the observed mean.");
  }
  if (Number.isFinite(Number(metrics.rmsePctOfMean)) && metrics.rmsePctOfMean > 80) {
    warnings.push("Daily hydrograph RMSE is high relative to mean discharge.");
  }
  return warnings;
}

function hydrographScore(hydrograph) {
  if (!hydrograph || hydrograph.status !== "ready") return 0.28;
  const kge = Number(hydrograph.metrics?.kge);
  if (!Number.isFinite(kge)) return 0.3;
  return clamp((kge + 0.41) / 1.41, 0.05, 1);
}

function hydroMean(values) {
  const finite = values.map(Number).filter(Number.isFinite);
  if (!finite.length) return Number.NaN;
  return finite.reduce((sum, value) => sum + value, 0) / finite.length;
}

function hydroStd(values, meanValue = hydroMean(values)) {
  const finite = values.map(Number).filter(Number.isFinite);
  if (finite.length < 2 || !Number.isFinite(meanValue)) return 0;
  const variance = finite.reduce((sum, value) => sum + (value - meanValue) ** 2, 0) / (finite.length - 1);
  return Math.sqrt(Math.max(0, variance));
}

function hydroCorrelation(a, b, meanA, meanB, stdA, stdB) {
  if (a.length !== b.length || a.length < 2 || stdA <= 0 || stdB <= 0) return null;
  let sum = 0;
  for (let i = 0; i < a.length; i += 1) sum += (a[i] - meanA) * (b[i] - meanB);
  return sum / ((a.length - 1) * stdA * stdB);
}

function hydroNse(observed, simulated, meanObserved) {
  if (observed.length !== simulated.length || observed.length < 2 || !Number.isFinite(meanObserved)) return null;
  let numerator = 0;
  let denominator = 0;
  for (let i = 0; i < observed.length; i += 1) {
    numerator += (simulated[i] - observed[i]) ** 2;
    denominator += (observed[i] - meanObserved) ** 2;
  }
  return denominator > 0 ? 1 - numerator / denominator : null;
}

function normalizedDate(value) {
  if (!value) return null;
  const match = String(value).match(/^(\d{4}-\d{2}-\d{2})/);
  return match ? match[1] : null;
}

function calibrationComparisonDiagnostics(input) {
  const observedM3s = Number(input.observedDischargeM3s);
  const observedAnnualM3 = Number(input.observedAnnualM3);
  const outletAnnualM3 = Number(input.simulatedOutletAnnualM3);
  const outletM3s = Number.isFinite(outletAnnualM3) ? outletAnnualM3 / SECONDS_PER_YEAR : Number.NaN;
  const gageAnnualM3 = Number(input.gageLocation?.nearestRiverDischargeAnnualM3);
  const gageM3s = Number.isFinite(gageAnnualM3) ? gageAnnualM3 / SECONDS_PER_YEAR : Number.NaN;
  const canCompareObserved = Number.isFinite(observedM3s) && observedM3s > 0;
  const canUseGage = canUseGageCalibrationComparison(input.gageLocation);
  const comparisonSource = canUseGage ? "nearest-modeled-channel" : "model-outlet";
  const simulatedAnnualM3 = canUseGage ? gageAnnualM3 : outletAnnualM3;
  const simulatedM3s = canUseGage ? gageM3s : outletM3s;
  const comparisonAreaBiasPct = canUseGage
    ? finiteNumber(input.gageLocation?.nearestRiverAreaBiasPct)
    : finiteNumber(input.drainageArea?.areaBiasPct);
  const spatialComparability = calibrationSpatialComparability({
    source: comparisonSource,
    drainageArea: input.drainageArea,
    gageLocation: input.gageLocation,
    comparisonAreaBiasPct
  });
  const biasPct = canCompareObserved ? pctBias(simulatedM3s, observedM3s) : null;
  const outletBiasPct = canCompareObserved ? pctBias(outletM3s, observedM3s) : null;
  const gageBiasPct = canCompareObserved ? pctBias(gageM3s, observedM3s) : null;
  const hasSimulated = Number.isFinite(simulatedM3s) && simulatedM3s > 0;

  return {
    status: canCompareObserved ? "ready" : "missing-observed-discharge",
    comparisonSource,
    reason: canUseGage
      ? "calibration gage is close enough to a modeled channel and catchment area is comparable"
      : "using model outlet because the gage-to-channel match is missing, distant, or not area-comparable",
    observedDischargeM3s: canCompareObserved ? observedM3s : null,
    observedAnnualM3: Number.isFinite(observedAnnualM3) ? observedAnnualM3 : null,
    simulatedAnnualM3: Number.isFinite(simulatedAnnualM3) ? simulatedAnnualM3 : null,
    simulatedM3s: Number.isFinite(simulatedM3s) ? simulatedM3s : null,
    biasM3s: canCompareObserved && Number.isFinite(simulatedM3s) ? simulatedM3s - observedM3s : null,
    biasPct,
    outletSimulatedAnnualM3: Number.isFinite(outletAnnualM3) ? outletAnnualM3 : null,
    outletSimulatedM3s: Number.isFinite(outletM3s) ? outletM3s : null,
    outletBiasM3s: canCompareObserved && Number.isFinite(outletM3s) ? outletM3s - observedM3s : null,
    outletBiasPct,
    nearestChannelSimulatedAnnualM3: Number.isFinite(gageAnnualM3) ? gageAnnualM3 : null,
    nearestChannelSimulatedM3s: Number.isFinite(gageM3s) ? gageM3s : null,
    nearestChannelBiasPct: gageBiasPct,
    comparisonAreaBiasPct,
    spatialComparability,
    automaticUpdateAllowed: canCompareObserved && hasSimulated && spatialComparability.score >= 0.55
  };
}

function canUseGageCalibrationComparison(gageLocation) {
  if (!gageLocation || gageLocation.insideAoi === false) return false;
  if (!["on-modeled-channel", "near-modeled-channel"].includes(gageLocation.status)) return false;
  if (!Number.isFinite(Number(gageLocation.nearestRiverDischargeAnnualM3))) return false;
  const areaBias = Number(gageLocation.nearestRiverAreaBiasPct);
  return !Number.isFinite(areaBias) || Math.abs(areaBias) <= 35;
}

function calibrationSpatialComparability(input) {
  const areaBiasAbs = Number.isFinite(Number(input.comparisonAreaBiasPct)) ? Math.abs(Number(input.comparisonAreaBiasPct)) : null;
  if (input.source === "nearest-modeled-channel") {
    const status = input.gageLocation?.status || "missing-site-location";
    if (status === "on-modeled-channel" && (areaBiasAbs === null || areaBiasAbs <= 15)) {
      return { class: "good", score: 1, status, areaBiasPct: input.comparisonAreaBiasPct };
    }
    if (["on-modeled-channel", "near-modeled-channel"].includes(status) && (areaBiasAbs === null || areaBiasAbs <= 35)) {
      return { class: "usable-with-caution", score: 0.72, status, areaBiasPct: input.comparisonAreaBiasPct };
    }
    return { class: "poor-match", score: 0.12, status, areaBiasPct: input.comparisonAreaBiasPct };
  }

  const comparability = input.drainageArea?.comparability || "missing-gage-area";
  const scoreByClass = {
    good: 0.88,
    "usable-with-caution": 0.66,
    "missing-gage-area": 0.34,
    "poor-match": 0.12
  };
  return {
    class: comparability,
    score: scoreByClass[comparability] ?? 0.25,
    status: input.gageLocation?.status || "outlet-only",
    areaBiasPct: input.comparisonAreaBiasPct
  };
}

function calibrationAdvisorDiagnostics(input) {
  const comparison = input.comparison || {};
  if (comparison.status !== "ready") {
    return {
      status: "not-calibrated",
      qualityClass: "no-observed-discharge",
      overallScore: null,
      comparisonSource: comparison.comparisonSource || null,
      componentScores: {},
      parameterSuggestion: null,
      warnings: ["Observed discharge is missing; import a scalar or time-series discharge record before calibration."],
      nextChecks: ["Add gage discharge, drainage area, and station latitude/longitude metadata."]
    };
  }

  const componentScores = {
    dischargeBias: scorePercentError(comparison.biasPct, 10, 25, 70),
    drainageArea: comparison.spatialComparability?.score ?? 0.25,
    stationLocation: stationLocationScore(input.gageLocation),
    recordLength: calibrationRecordScore(input.observedSeries),
    flowDurationShape: flowDurationScore(input.durationBias),
    hydrographShape: hydrographScore(input.hydrograph),
    waterBudgetClosure: waterBudgetScore(input.waterBudget)
  };
  const overallScore = weightedScore([
    [componentScores.dischargeBias, 0.26],
    [componentScores.drainageArea, 0.18],
    [componentScores.stationLocation, 0.16],
    [componentScores.recordLength, 0.12],
    [componentScores.flowDurationShape, 0.08],
    [componentScores.hydrographShape, 0.1],
    [componentScores.waterBudgetClosure, 0.1]
  ]);
  const parameterSuggestion = calibrationParameterSuggestion(input.calibrationSource, comparison, input.calibrationStrength);
  const warnings = calibrationAdvisorWarnings(input, componentScores, parameterSuggestion);
  const qualityClass = calibrationQualityClass(overallScore, comparison, warnings);

  return {
    status: comparison.automaticUpdateAllowed ? "calibratable" : "diagnostic-only",
    qualityClass,
    overallScore: round(overallScore, 3),
    comparisonSource: comparison.comparisonSource,
    componentScores: mapScoreObject(componentScores),
    recommendedAction: calibrationRecommendedAction(qualityClass, comparison),
    parameterSuggestion,
    warnings,
    nextChecks: calibrationNextChecks(input, componentScores)
  };
}

function calibrationParameterSuggestion(calibrationSource, comparison, calibrationStrength = 1) {
  const observed = Number(comparison.observedDischargeM3s);
  const simulated = Number(comparison.simulatedM3s);
  if (!Number.isFinite(observed) || !Number.isFinite(simulated) || observed <= 0 || simulated <= 0) return null;
  const correctionFactor = observed / simulated;
  const currentRunoffMultiplier = firstFinite(calibrationSource?.runoffMultiplier, 1);
  const currentDischargeScale = firstFinite(calibrationSource?.dischargeScale, 1);
  const strength = clamp(Number(calibrationStrength ?? 1), 0, 1);
  const effectiveRunoffMultiplier = lerp(1, currentRunoffMultiplier, strength);
  const effectiveDischargeScale = lerp(1, currentDischargeScale, strength);
  const split = Math.sqrt(correctionFactor);
  const dischargeScaleOnly = sourceScaleForCalibrationStrength(effectiveDischargeScale * correctionFactor, strength, currentDischargeScale, 0.05, 12);
  const splitRunoffMultiplier = sourceScaleForCalibrationStrength(effectiveRunoffMultiplier * split, strength, currentRunoffMultiplier, 0.2, 5);
  const splitDischargeScale = sourceScaleForCalibrationStrength(effectiveDischargeScale * split, strength, currentDischargeScale, 0.05, 12);
  return {
    correctionFactor: round(correctionFactor, 4),
    calibrationStrength: round(strength, 4),
    current: {
      runoffMultiplier: round(currentRunoffMultiplier, 4),
      dischargeScale: round(currentDischargeScale, 4),
      effectiveRunoffMultiplier: round(effectiveRunoffMultiplier, 4),
      effectiveDischargeScale: round(effectiveDischargeScale, 4)
    },
    dischargeScaleOnly: {
      runoffMultiplier: round(currentRunoffMultiplier, 4),
      dischargeScale: round(dischargeScaleOnly, 4),
      effectiveDischargeScale: round(lerp(1, dischargeScaleOnly, strength), 4)
    },
    splitRunoffAndRouting: {
      runoffMultiplier: round(splitRunoffMultiplier, 4),
      dischargeScale: round(splitDischargeScale, 4),
      effectiveRunoffMultiplier: round(lerp(1, splitRunoffMultiplier, strength), 4),
      effectiveDischargeScale: round(lerp(1, splitDischargeScale, strength), 4)
    },
    boundsHit: dischargeScaleOnly === 0.05 || dischargeScaleOnly === 12 || splitRunoffMultiplier === 0.2 || splitRunoffMultiplier === 5 || splitDischargeScale === 0.05 || splitDischargeScale === 12,
    note: "Use dischargeScaleOnly for a conservative outlet scalar; use splitRunoffAndRouting only after checking precipitation, soil, land cover, and withdrawals."
  };
}

function sourceScaleForCalibrationStrength(targetEffectiveScale, strength, fallback, min, max) {
  if (!Number.isFinite(targetEffectiveScale) || !Number.isFinite(strength) || strength <= 0) return clamp(fallback, min, max);
  return clamp(1 + (targetEffectiveScale - 1) / strength, min, max);
}

function calibrationAdvisorWarnings(input, scores, suggestion) {
  const warnings = [];
  const comparison = input.comparison || {};
  if (!comparison.automaticUpdateAllowed) {
    warnings.push("Automatic scalar update is not advised until the comparison catchment and station match are defensible.");
  }
  if (Number.isFinite(Number(comparison.biasPct)) && Math.abs(Number(comparison.biasPct)) > 35) {
    warnings.push("Discharge bias exceeds 35%; treat a scalar correction as first-pass screening, not final calibration.");
  }
  if ((scores.flowDurationShape ?? 1) < 0.45) {
    warnings.push("Flow-duration mismatch is large for a steady annual model; add routed time-step hydrology before using peak/low-flow diagnostics.");
  }
  if (input.hydrograph?.status === "missing-daily-forcing") {
    warnings.push("Daily hydrograph scoring is unavailable because daily meteorology forcing does not overlap the observed discharge record.");
  }
  if (input.hydrograph?.status === "ready" && (scores.hydrographShape ?? 1) < 0.45) {
    warnings.push("Daily hydrograph shape score is weak; inspect precipitation timing, soil storage, recession, and routing assumptions.");
  }
  if ((scores.waterBudgetClosure ?? 1) < 0.4) {
    warnings.push("Water-budget closure is weak; inspect precipitation, ET, withdrawals, retention, and outlet selection before parameter fitting.");
  }
  if (suggestion?.boundsHit) {
    warnings.push("Suggested scalar reached a guardrail; the error is likely structural rather than a simple multiplier.");
  }
  return warnings;
}

function calibrationNextChecks(input, scores) {
  const checks = [];
  if ((scores.drainageArea ?? 0) < 0.55) checks.push("Clip the model to the gage watershed or select a gage with comparable drainage area.");
  if ((scores.stationLocation ?? 0) < 0.55) checks.push("Verify AOI bounds, station coordinates, river threshold, and flowline constraints.");
  if ((scores.recordLength ?? 0) < 0.55) checks.push("Use at least 90 daily records, and preferably multiple complete water years.");
  if (!input.hydrograph || input.hydrograph.status !== "ready") checks.push("Import overlapping daily meteorology and discharge records for hydrograph KGE/NSE diagnostics.");
  if (!Number.isFinite(Number(input.calibrationSource?.siteLatitude)) || !Number.isFinite(Number(input.calibrationSource?.siteLongitude))) {
    checks.push("Provide station latitude and longitude for gage-to-channel matching.");
  }
  if (!Number.isFinite(Number(input.calibrationSource?.drainageAreaKm2)) && !Number.isFinite(Number(input.calibrationSource?.contributingDrainageAreaKm2))) {
    checks.push("Provide drainageAreaKm2 or contributingDrainageAreaKm2 with calibration data.");
  }
  return checks;
}

function calibrationRecommendedAction(qualityClass, comparison) {
  if (qualityClass === "research-ready") return "Bias and spatial checks are strong; scalar calibration can be used as a baseline before event hydrographs.";
  if (qualityClass === "usable-with-caution") return "Use the suggested scalar only with the listed diagnostics attached to the report.";
  if (comparison.spatialComparability?.score < 0.55) return "Fix watershed/station comparability before fitting hydrologic parameters.";
  return "Keep this as a diagnostic run and improve forcing, soil, land-cover, and calibration records.";
}

function calibrationQualityClass(score, comparison, warnings) {
  if (comparison.spatialComparability?.score < 0.25) return "invalid-comparison";
  if (score >= 0.78 && warnings.length <= 1) return "research-ready";
  if (score >= 0.6) return "usable-with-caution";
  if (score >= 0.42) return "screening-only";
  return "diagnostic-only";
}

function scorePercentError(value, good, usable, poor) {
  const abs = Math.abs(Number(value));
  if (!Number.isFinite(abs)) return 0.25;
  if (abs <= good) return 1;
  if (abs <= usable) return lerp(0.82, 1, (usable - abs) / Math.max(1, usable - good));
  if (abs <= poor) return lerp(0.35, 0.82, (poor - abs) / Math.max(1, poor - usable));
  return clamp(0.35 - (abs - poor) / 220, 0.05, 0.35);
}

function stationLocationScore(gageLocation) {
  const status = gageLocation?.status || "missing-site-location";
  if (status === "on-modeled-channel") return 1;
  if (status === "near-modeled-channel") return 0.72;
  if (status === "far-from-modeled-channel") return 0.25;
  if (status === "missing-site-location") return 0.34;
  if (status === "outside-aoi") return 0.05;
  if (status === "no-modeled-river") return 0.18;
  return 0.28;
}

function calibrationRecordScore(observedSeries) {
  const count = Number(observedSeries?.recordCount);
  if (!Number.isFinite(count) || count <= 0) return 0.35;
  if (count >= 3650) return 1;
  if (count >= 730) return 0.9;
  if (count >= 365) return 0.78;
  if (count >= 90) return 0.58;
  if (count >= 30) return 0.38;
  return 0.16;
}

function flowDurationScore(durationBias) {
  if (!durationBias) return 0.35;
  const biases = [
    durationBias.meanBiasPct,
    durationBias.medianBiasPct,
    durationBias.p10BiasPct,
    durationBias.p90BiasPct
  ].filter((value) => Number.isFinite(Number(value))).map((value) => Math.abs(Number(value)));
  if (!biases.length) return 0.3;
  return scorePercentError(biases.reduce((sum, value) => sum + value, 0) / biases.length, 20, 55, 130);
}

function waterBudgetScore(waterBudget) {
  if (!waterBudget) return 0.35;
  const closure = waterBudget.closureClass;
  if (closure === "tight") return 1;
  if (closure === "storage-or-groundwater-dominated") return 0.72;
  if (closure === "loose") return 0.45;
  if (closure === "physically-suspect") return 0.12;
  return 0.3;
}

function weightedScore(pairs) {
  let total = 0;
  let weightSum = 0;
  for (const [score, weight] of pairs) {
    if (!Number.isFinite(Number(score)) || !Number.isFinite(Number(weight)) || weight <= 0) continue;
    total += Number(score) * Number(weight);
    weightSum += Number(weight);
  }
  return weightSum > 0 ? total / weightSum : 0;
}

function mapScoreObject(scores) {
  return Object.fromEntries(Object.entries(scores).map(([key, value]) => [key, round(value, 3)]));
}

function calibrationLocationDiagnostics(calibrationSource, model, params) {
  const lat = Number(calibrationSource?.siteLatitude);
  const lon = Number(calibrationSource?.siteLongitude);
  const warnings = [];
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
    return {
      status: "missing-site-location",
      siteLatitude: null,
      siteLongitude: null,
      warnings: ["Calibration gage latitude/longitude is missing; spatial comparability cannot be checked."]
    };
  }

  const spatialContext = model.spatialContext || params.spatialContext || getSpatialContext(params);
  const localKm = wgs84PointToLocalKm(lat, lon, spatialContext);
  if (!localKm) {
    return {
      status: "missing-aoi-context",
      siteLatitude: lat,
      siteLongitude: lon,
      warnings: ["AOI WGS84 bounds are missing; calibration gage could not be projected into the model grid."]
    };
  }

  const sizeKm = model.sizeKm || MAP_SIZE_KM;
  const insideAoi = localKm.xKm >= 0 && localKm.xKm <= sizeKm && localKm.yKm >= 0 && localKm.yKm <= sizeKm;
  const gridX = clamp(Math.round(localKm.xKm / model.cellSizeKm), 0, model.n - 1);
  const gridY = clamp(Math.round(localKm.yKm / model.cellSizeKm), 0, model.n - 1);
  const gridIndex = gridY * model.n + gridX;
  const hasRiverSegments = Array.isArray(model.riverSegments) && model.riverSegments.length > 0;
  const nearest = hasRiverSegments
    ? nearestRiverSegmentDiagnostics(model, localKm)
    : maxFlowCellDiagnostics(model, localKm);
  const referenceAreaKm2 = calibrationReferenceDrainageAreaKm2(calibrationSource);
  const nearestRiverCatchmentKm2 = Number.isFinite(nearest?.catchmentKm2) ? nearest.catchmentKm2 : null;
  const gageCellCatchmentKm2 = Number.isFinite(model.flowAccumulation?.[gridIndex]) ? model.flowAccumulation[gridIndex] : null;
  const nearestRiverAreaBiasPct = pctBias(nearestRiverCatchmentKm2, referenceAreaKm2);
  const gageCellAreaBiasPct = pctBias(gageCellCatchmentKm2, referenceAreaKm2);
  const nearestRiverDistanceKm = Number.isFinite(nearest?.distanceKm) ? nearest.distanceKm : null;
  const nearestRiverDistanceCells = Number.isFinite(nearestRiverDistanceKm) ? nearestRiverDistanceKm / model.cellSizeKm : null;

  let status = "missing-channel";
  if (!insideAoi) {
    status = "outside-aoi";
    warnings.push("Calibration gage lies outside the current AOI; gage-vs-model bias is not spatially comparable.");
  } else if (!hasRiverSegments) {
    status = "no-modeled-river";
    warnings.push("No modeled river segment exceeded the extraction threshold; lower the river threshold or increase resolution before using gage calibration.");
  } else if (!Number.isFinite(nearestRiverDistanceKm)) {
    status = "missing-channel";
    warnings.push("Nearest modeled river segment could not be measured; verify flow routing and river extraction outputs.");
  } else if (nearestRiverDistanceKm <= Math.max(model.cellSizeKm * 1.5, 0.5)) {
    status = "on-modeled-channel";
  } else if (nearestRiverDistanceKm <= Math.max(model.cellSizeKm * 6, 3)) {
    status = "near-modeled-channel";
  } else {
    status = "far-from-modeled-channel";
    warnings.push(`Calibration gage is ${round(nearestRiverDistanceKm, 2)} km from the nearest modeled river segment; verify AOI, DEM alignment, and river threshold.`);
  }

  if (Number.isFinite(nearestRiverAreaBiasPct) && Math.abs(nearestRiverAreaBiasPct) > 35) {
    warnings.push(`Nearest modeled channel catchment differs from the gage reference area by ${round(nearestRiverAreaBiasPct, 1)}%.`);
  }

  return {
    status,
    siteLatitude: lat,
    siteLongitude: lon,
    insideAoi,
    localKm: { x: round(localKm.xKm, 4), y: round(localKm.yKm, 4) },
    grid: {
      x: gridX,
      y: gridY,
      index: gridIndex,
      cellSizeKm: model.cellSizeKm
    },
    gageCellCatchmentKm2,
    gageCellDischargeAnnualM3: Number.isFinite(model.discharge?.[gridIndex]) ? model.discharge[gridIndex] : null,
    gageCellStreamOrder: Number.isFinite(model.streamOrder?.[gridIndex]) ? model.streamOrder[gridIndex] : null,
    gageCellAreaBiasPct,
    referenceAreaKm2: Number.isFinite(referenceAreaKm2) ? referenceAreaKm2 : null,
    nearestRiverDistanceKm,
    nearestRiverDistanceCells,
    nearestRiverCatchmentKm2,
    nearestRiverDischargeAnnualM3: Number.isFinite(nearest?.dischargeAnnualM3) ? nearest.dischargeAnnualM3 : null,
    nearestRiverStreamOrder: Number.isFinite(nearest?.streamOrder) ? nearest.streamOrder : null,
    nearestRiverAreaBiasPct,
    nearestModeledChannel: nearest,
    warnings
  };
}

function wgs84PointToLocalKm(lat, lon, spatialContext) {
  if (!spatialContext?.bboxWgs84) return null;
  const [west, south, east, north] = spatialContext.bboxWgs84.map(Number);
  const widthDeg = east - west;
  const heightDeg = north - south;
  if (!Number.isFinite(widthDeg) || !Number.isFinite(heightDeg) || widthDeg === 0 || heightDeg === 0) return null;
  const sizeKm = Number(spatialContext.sizeKm) || MAP_SIZE_KM;
  return {
    xKm: ((lon - west) / widthDeg) * sizeKm,
    yKm: ((north - lat) / heightDeg) * sizeKm
  };
}

function nearestRiverSegmentDiagnostics(model, point) {
  let best = null;
  for (const segment of model.riverSegments || []) {
    const from = indexToPoint(segment.from, model.n, model.cellSizeKm);
    const to = indexToPoint(segment.to, model.n, model.cellSizeKm);
    const projected = pointToSegmentProjection(point, from, to);
    if (!best || projected.distanceKm < best.distanceKm) {
      const fromDistance = distanceKm(point, from);
      const toDistance = distanceKm(point, to);
      const nearestCellIndex = fromDistance <= toDistance ? segment.from : segment.to;
      best = {
        source: "river-segment",
        distanceKm: projected.distanceKm,
        projectedKm: { x: round(projected.xKm, 4), y: round(projected.yKm, 4) },
        segmentT: projected.t,
        fromIndex: segment.from,
        toIndex: segment.to,
        nearestCellIndex,
        nearestCellKm: indexToPoint(nearestCellIndex, model.n, model.cellSizeKm),
        catchmentKm2: Number(segment.catchment),
        dischargeAnnualM3: Number(segment.discharge),
        streamOrder: Number(segment.order)
      };
    }
  }
  return best;
}

function maxFlowCellDiagnostics(model, point) {
  let maxIndex = -1;
  let maxCatchment = -Infinity;
  for (let i = 0; i < (model.flowAccumulation?.length || 0); i += 1) {
    const catchment = Number(model.flowAccumulation[i]);
    if (Number.isFinite(catchment) && catchment > maxCatchment) {
      maxCatchment = catchment;
      maxIndex = i;
    }
  }
  if (maxIndex < 0) return null;
  const cell = indexToPoint(maxIndex, model.n, model.cellSizeKm);
  return {
    source: "max-flow-cell",
    distanceKm: distanceKm(point, cell),
    projectedKm: { x: round(cell.xKm, 4), y: round(cell.yKm, 4) },
    nearestCellIndex: maxIndex,
    nearestCellKm: cell,
    catchmentKm2: maxCatchment,
    dischargeAnnualM3: Number(model.discharge?.[maxIndex]),
    streamOrder: Number(model.streamOrder?.[maxIndex])
  };
}

function calibrationReferenceDrainageAreaKm2(calibrationSource) {
  const gageDrainageAreaKm2 = Number(calibrationSource?.drainageAreaKm2);
  const contributingDrainageAreaKm2 = Number(calibrationSource?.contributingDrainageAreaKm2);
  return Number.isFinite(contributingDrainageAreaKm2) && contributingDrainageAreaKm2 > 0
    ? contributingDrainageAreaKm2
    : gageDrainageAreaKm2;
}

function calibrationDrainageAreaDiagnostics(calibrationSource, modelOutletCatchmentKm2, aoiAreaKm2) {
  const gageDrainageAreaKm2 = Number(calibrationSource?.drainageAreaKm2);
  const contributingDrainageAreaKm2 = Number(calibrationSource?.contributingDrainageAreaKm2);
  const referenceAreaKm2 = calibrationReferenceDrainageAreaKm2(calibrationSource);
  const areaBiasPct = pctBias(modelOutletCatchmentKm2, referenceAreaKm2);
  const ratio = Number.isFinite(referenceAreaKm2) && referenceAreaKm2 > 0 ? modelOutletCatchmentKm2 / referenceAreaKm2 : null;
  return {
    gageDrainageAreaKm2: Number.isFinite(gageDrainageAreaKm2) ? gageDrainageAreaKm2 : null,
    contributingDrainageAreaKm2: Number.isFinite(contributingDrainageAreaKm2) ? contributingDrainageAreaKm2 : null,
    referenceAreaKm2: Number.isFinite(referenceAreaKm2) ? referenceAreaKm2 : null,
    modelOutletCatchmentKm2,
    aoiAreaKm2,
    modelToGageAreaRatio: Number.isFinite(ratio) ? ratio : null,
    areaBiasPct,
    comparability: drainageAreaComparability(areaBiasPct)
  };
}

function drainageAreaComparability(areaBiasPct) {
  if (!Number.isFinite(Number(areaBiasPct))) return "missing-gage-area";
  const abs = Math.abs(Number(areaBiasPct));
  if (abs <= 15) return "good";
  if (abs <= 35) return "usable-with-caution";
  return "poor-match";
}

function normalizeEnsembleParams(params, resolution) {
  const defaults = createDefaultParams();
  return {
    ...defaults,
    ...(params || {}),
    resolution,
    precipitationScale: firstFinite(params?.precipitationScale, 1),
    temperatureOffsetC: firstFinite(params?.temperatureOffsetC, 0),
    vegetationCoverScale: firstFinite(params?.vegetationCoverScale, 1),
    soilHydraulicConductivityScale: firstFinite(params?.soilHydraulicConductivityScale, 1),
    availableWaterCapacityScale: firstFinite(params?.availableWaterCapacityScale, 1),
    rootDepthScale: firstFinite(params?.rootDepthScale, 1),
    imperviousFractionScale: firstFinite(params?.imperviousFractionScale, 1),
    externalLayers: params?.externalLayers || null
  };
}

function uncertaintyRunSnapshot(variant, params, model, runtimeMs) {
  const stats = model.stats || {};
  const climate = CLIMATES[stats.dominantClimate] || null;
  return {
    id: variant.id || "variant",
    label: variant.label || variant.id || "Variant",
    description: variant.description || "",
    perturbations: variant.perturbations || {},
    resolution: model.n,
    cellSizeM: model.cellSizeKm * 1000,
    runtimeMs,
    params: uncertaintyParamSnapshot(params),
    dominantClimate: climate ? { code: climate.code, name: climate.name } : null,
    metrics: collectUncertaintyMetrics(stats),
    waterBudget: stats.waterBudget
      ? {
          generatedRunoffCoefficientByVolume: stats.waterBudget.generatedRunoffCoefficientByVolume,
          outletRunoffCoefficientByVolume: stats.waterBudget.outletRunoffCoefficientByVolume,
          outletFractionOfGeneratedRunoff: stats.waterBudget.outletFractionOfGeneratedRunoff,
          residualPctOfInput: stats.waterBudget.residualPctOfInput,
          closureClass: stats.waterBudget.closureClass
        }
      : null,
    calibration: stats.calibration
      ? {
          biasPct: stats.calibration.biasPct,
          simulatedOutletM3s: stats.calibration.simulatedOutletM3s,
          observedDischargeM3s: stats.calibration.observedDischargeM3s,
          comparison: stats.calibration.comparison,
          advisor: stats.calibration.advisor,
          hydrograph: stats.calibration.hydrograph,
          drainageArea: stats.calibration.drainageArea,
          gageLocation: stats.calibration.gageLocation
        }
      : null,
    meteorologyBoundary: stats.meteorologyBoundary
      ? {
          selectedYear: stats.meteorologyBoundary.selectedYear,
          currentState: stats.meteorologyBoundary.currentState,
          extremes: stats.meteorologyBoundary.extremes,
          hazardMultipliers: stats.meteorologyBoundary.hazardMultipliers,
          quality: stats.meteorologyBoundary.quality
        }
      : null,
    infrastructureBudget: stats.infrastructureBudget
      ? {
          demandToSupplyRatio: stats.infrastructureBudget.demandToSupplyRatio,
          retainedFlowAnnualM3: stats.infrastructureBudget.retainedFlowAnnualM3,
          affectedAreaKm2: stats.infrastructureBudget.affectedAreaKm2,
          imperviousFractionEquivalent: stats.infrastructureBudget.imperviousFractionEquivalent
        }
      : null
  };
}

function uncertaintyParamSnapshot(params) {
  const keys = [
    "seed",
    "resolution",
    "flowRouting",
    "riverThreshold",
    "permeability",
    "humidity",
    "windSpeed",
    "baseTemperature",
    "lapseRate",
    "vegetationFeedback",
    "externalDataWeight",
    "calibrationStrength",
    "precipitationScale",
    "temperatureOffsetC",
    "vegetationCoverScale",
    "soilHydraulicConductivityScale",
    "availableWaterCapacityScale",
    "rootDepthScale",
    "imperviousFractionScale",
    "infrastructureImperviousScale",
    "infrastructureRunoffScale",
    "infrastructureHeatScale",
    "infrastructureStorageScale",
    "infrastructureRetentionScale",
    "infrastructureIrrigationScale",
    "infrastructureDemandScale"
  ];
  return keys.reduce((acc, key) => {
    if (params[key] !== undefined) acc[key] = params[key];
    return acc;
  }, {});
}

function collectUncertaintyMetrics(stats) {
  return UNCERTAINTY_METRICS.reduce((acc, spec) => {
    const value = finiteNumber(uncertaintyMetricValue(stats, spec.key));
    if (value !== null) acc[spec.key] = value;
    return acc;
  }, {});
}

function uncertaintyMetricValue(stats, key) {
  if (!stats) return null;
  if (key === "generatedRunoffCoefficientByVolume") return stats.waterBudget?.generatedRunoffCoefficientByVolume;
  if (key === "outletRunoffCoefficientByVolume") return stats.waterBudget?.outletRunoffCoefficientByVolume;
  if (key === "residualPctOfInput") return stats.waterBudget?.residualPctOfInput;
  if (key === "outletCatchmentFractionOfLand") return stats.waterBudget?.outletCatchmentFractionOfLand;
  if (key === "simulatedOutletM3s") return stats.calibration?.simulatedOutletM3s;
  if (key === "calibrationBiasPct") return stats.calibration?.biasPct;
  if (key === "calibrationHydrographKge") return stats.calibration?.hydrograph?.metrics?.kge;
  if (key === "infrastructureDemandToSupplyRatio") return stats.infrastructureBudget?.demandToSupplyRatio;
  if (key === "infrastructureRetainedFlowAnnualM3") return stats.infrastructureBudget?.retainedFlowAnnualM3;
  if (key === "meanChannelVelocityMs") return stats.hydraulicDiagnostics?.meanChannelVelocityMs;
  if (key === "maxShearStressPa") return stats.hydraulicDiagnostics?.maxShearStressPa;
  if (key === "meanErosionRisk") return stats.hydraulicDiagnostics?.meanErosionRisk;
  if (key === "highErosionAreaKm2") return stats.hydraulicDiagnostics?.highErosionAreaKm2;
  if (key === "meanCompositeHazard") return stats.hazards?.meanCompositeHazard;
  if (key === "highCompositeHazardAreaKm2") return stats.hazards?.highCompositeHazardAreaKm2;
  if (key === "meanCumulativeErosionM") return stats.timeProgression?.meanCumulativeErosionM;
  return stats[key];
}

function summarizeUncertaintyMetrics(runs, baseline) {
  const summary = {};
  for (const spec of UNCERTAINTY_METRICS) {
    const values = runs
      .map((run) => finiteNumber(run.metrics?.[spec.key]))
      .filter((value) => value !== null)
      .sort((a, b) => a - b);
    if (!values.length) continue;
    const baselineValue = finiteNumber(baseline?.metrics?.[spec.key]);
    const p10 = percentileSorted(values, 0.1);
    const p50 = percentileSorted(values, 0.5);
    const p90 = percentileSorted(values, 0.9);
    const spread = p90 - p10;
    summary[spec.key] = {
      label: spec.label,
      unit: spec.unit,
      count: values.length,
      baseline: baselineValue,
      min: values[0],
      p10,
      p50,
      p90,
      max: values[values.length - 1],
      spreadP10P90: spread,
      relativeSpread: baselineValue !== null && Math.abs(baselineValue) > 1e-9 ? Math.abs(spread) / Math.abs(baselineValue) : null
    };
  }
  return summary;
}

function summarizeVariantSensitivity(runs, baseline) {
  if (!baseline) return [];
  const rows = [];
  for (const run of runs) {
    if (run.id === baseline.id) continue;
    const effects = {};
    let impactScore = 0;
    for (const spec of UNCERTAINTY_METRICS) {
      const value = finiteNumber(run.metrics?.[spec.key]);
      const base = finiteNumber(baseline.metrics?.[spec.key]);
      if (value === null || base === null) continue;
      const delta = value - base;
      const pctDelta = Math.abs(base) > 1e-9 ? (delta / Math.abs(base)) * 100 : null;
      effects[spec.key] = { delta, pctDelta };
      if (pctDelta !== null && ["generatedRunoffCoefficientByVolume", "outletRunoffCoefficientByVolume", "meanActualEvapotranspiration", "residualPctOfInput", "meanErosionRisk", "maxShearStressPa"].includes(spec.key)) {
        impactScore = Math.max(impactScore, Math.abs(pctDelta));
      }
    }
    rows.push({
      id: run.id,
      label: run.label,
      perturbations: run.perturbations,
      impactScore,
      effects
    });
  }
  return rows.sort((a, b) => b.impactScore - a.impactScore);
}

function uncertaintyWarnings({ metrics, requestedResolution, diagnosticResolution, baseParams }) {
  const warnings = [];
  if (requestedResolution > diagnosticResolution) {
    warnings.push(`Ensemble capped at ${diagnosticResolution}² for responsiveness; re-run at ${requestedResolution}² offline before publishing final uncertainty bounds.`);
  }
  if (!baseParams?.externalLayers) {
    warnings.push("No external DEM, soil, land-cover, meteorological, flowline, infrastructure, or calibration layers were present in the ensemble input.");
  }
  if (!metrics.calibrationBiasPct) {
    warnings.push("Calibration bias spread is unavailable because observed discharge calibration was not loaded.");
  }
  const generatedRunoff = metrics.generatedRunoffCoefficientByVolume;
  if (Number.isFinite(generatedRunoff?.relativeSpread) && generatedRunoff.relativeSpread > 0.25) {
    warnings.push(`Generated runoff coefficient has a high P10-P90 spread (${round(generatedRunoff.relativeSpread * 100, 1)}% of baseline).`);
  }
  const outletRunoff = metrics.outletRunoffCoefficientByVolume;
  if (Number.isFinite(outletRunoff?.relativeSpread) && outletRunoff.relativeSpread > 0.35) {
    warnings.push(`Outlet runoff coefficient is highly sensitive (${round(outletRunoff.relativeSpread * 100, 1)}% P10-P90 spread).`);
  }
  const residual = metrics.residualPctOfInput;
  if (absoluteMetricEnvelope(residual) > 80) {
    warnings.push("At least one ensemble quantile has a physically suspect water-budget residual above 80% of annual input.");
  }
  const builtDemand = metrics.infrastructureDemandToSupplyRatio;
  if (Number.isFinite(builtDemand?.p90) && builtDemand.p90 > 3) {
    warnings.push("Infrastructure demand/supply ratio exceeds 3 in the upper ensemble quantile.");
  }
  return warnings;
}

function classifyUncertainty(metrics) {
  const runoffSpread = metrics.generatedRunoffCoefficientByVolume?.relativeSpread ?? metrics.outletRunoffCoefficientByVolume?.relativeSpread ?? Infinity;
  const residualEnvelope = absoluteMetricEnvelope(metrics.residualPctOfInput);
  if (runoffSpread <= 0.15 && residualEnvelope <= 45) return "well-constrained";
  if (runoffSpread <= 0.35 && residualEnvelope <= 80) return "moderate";
  return "high-uncertainty";
}

function absoluteMetricEnvelope(metric) {
  if (!metric) return Infinity;
  const values = [metric.min, metric.p10, metric.p50, metric.p90, metric.max].map(finiteNumber).filter((value) => value !== null);
  return values.length ? Math.max(...values.map((value) => Math.abs(value))) : Infinity;
}

function percentileSorted(values, p) {
  if (!values.length) return null;
  if (values.length === 1) return values[0];
  const index = clamp(p, 0, 1) * (values.length - 1);
  const lo = Math.floor(index);
  const hi = Math.ceil(index);
  if (lo === hi) return values[lo];
  return lerp(values[lo], values[hi], index - lo);
}

function finiteNumber(value) {
  if (value === null || value === undefined || value === "") return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function clampInteger(value, min, max, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.round(clamp(n, min, max));
}

function waterBudgetDiagnostics(input) {
  const landAreaKm2 = input.landCells * input.cellAreaKm2;
  const totalWaterInputM3 = input.precipitationVolumeM3 + input.infrastructureSupplyVolumeM3;
  const residualStorageOrDeepLossM3 =
    input.precipitationVolumeM3 +
    input.infrastructureSupplyVolumeM3 -
    input.infrastructureDemandVolumeM3 -
    input.actualEtVolumeM3 -
    input.generatedRunoffAnnualM3;
  return {
    landAreaKm2,
    outletCatchmentAreaKm2: input.outletCatchmentAreaKm2,
    outletCatchmentFractionOfLand: ratio(input.outletCatchmentAreaKm2, landAreaKm2),
    precipitationVolumeM3: input.precipitationVolumeM3,
    infrastructureSupplyVolumeM3: input.infrastructureSupplyVolumeM3,
    totalWaterInputM3,
    actualEvapotranspirationVolumeM3: input.actualEtVolumeM3,
    infrastructureDemandVolumeM3: input.infrastructureDemandVolumeM3,
    generatedRunoffAnnualM3: input.generatedRunoffAnnualM3,
    outletRunoffAnnualM3: input.outletRunoffAnnualM3,
    retainedFlowAnnualM3: input.retainedFlowAnnualM3,
    infrastructureStorageCapacityM3: input.infrastructureStorageCapacityM3,
    surfaceWaterBalanceVolumeM3: input.surfaceWaterBalanceVolumeM3,
    residualStorageOrDeepLossM3,
    residualPctOfInput: pctOf(residualStorageOrDeepLossM3, totalWaterInputM3),
    outletRunoffCoefficientByVolume: ratio(input.outletRunoffAnnualM3, totalWaterInputM3),
    generatedRunoffCoefficientByVolume: ratio(input.generatedRunoffAnnualM3, totalWaterInputM3),
    outletFractionOfGeneratedRunoff: ratio(input.outletRunoffAnnualM3, input.generatedRunoffAnnualM3),
    evapotranspirationRatio: ratio(input.actualEtVolumeM3, totalWaterInputM3),
    demandRatio: ratio(input.infrastructureDemandVolumeM3, totalWaterInputM3),
    retainedFlowRatioOfGeneratedRunoff: ratio(input.retainedFlowAnnualM3, input.generatedRunoffAnnualM3),
    closureClass: waterBudgetClosureClass(residualStorageOrDeepLossM3, totalWaterInputM3)
  };
}

function createBuiltResilienceGroup(type) {
  return {
    type,
    cells: 0,
    buildingCellCount: 0,
    sumBuildingDensity: 0,
    sumBuildingHeightM: 0,
    maxBuildingHeightM: 0,
    sumFloorCount: 0,
    sumImperviousFraction: 0,
    sumStructuralVulnerability: 0,
    sumFloodExposure: 0,
    sumWildfireExposure: 0,
    sumLandslideExposure: 0,
    sumHeatDroughtExposure: 0,
    sumFloodDamage: 0,
    sumWildfireDamage: 0,
    sumLandslideDamage: 0,
    sumHeatDroughtDamage: 0,
    sumCombinedDamage: 0,
    sumCurrentDamage: 0,
    sumServiceLossYears: 0,
    sumRecoveryPressure: 0,
    sumSubsurfaceRisk: 0,
    hazardCounts: new Uint32Array(5)
  };
}

function addBuiltResilienceCell(group, model, influence, resilience, i, cellAreaKm2) {
  group.cells += 1;
  const buildingDensity = atlasNumberAt(influence.buildingDensity, i);
  const buildingHeightM = Math.max(atlasNumberAt(influence.buildingHeightM, i), atlasNumberAt(influence.landmarkHeightM, i));
  const floorCount = atlasNumberAt(influence.floorCount, i);
  const impervious = clamp(atlasNumberAt(model.surface?.imperviousFraction, i) || atlasNumberAt(influence.imperviousFraction, i), 0, 1);
  const floodExposure = atlasNumberAt(model.hazards?.currentFloodHazard ?? model.hazards?.floodHazard, i);
  const wildfireExposure = atlasNumberAt(model.hazards?.currentWildfireRisk ?? model.hazards?.wildfireRisk, i);
  const landslideExposure = atlasNumberAt(model.hazards?.currentLandslideRisk ?? model.hazards?.landslideRisk, i);
  const droughtExposure = atlasNumberAt(model.hazards?.currentDroughtStress ?? model.hazards?.droughtStress, i);
  const heatExposure = clamp((model.temperature?.[i] ?? 0) / 42 + (influence.temperatureDeltaC?.[i] ?? 0) / 8, 0, 1);
  const heatDroughtExposure = clamp(droughtExposure * 0.64 + heatExposure * 0.36, 0, 1);
  const subsurfaceRisk = clamp(
    subsurfaceColumnValue(model, "columnEngineeringRisk", i, 0) * 0.72 +
      subsurfaceColumnValue(model, "columnLiquefactionRisk", i, 0) * 0.22 +
      subsurfaceColumnValue(model, "columnFractureRisk", i, 0) * 0.16,
    0,
    1
  );
  if (buildingDensity > 0.02 || buildingHeightM > 1 || floorCount > 0) {
    group.buildingCellCount += 1;
    group.sumBuildingDensity += buildingDensity;
    group.sumBuildingHeightM += buildingHeightM;
    group.sumFloorCount += floorCount;
    group.maxBuildingHeightM = Math.max(group.maxBuildingHeightM, buildingHeightM);
  }
  group.sumImperviousFraction += impervious;
  group.sumStructuralVulnerability += atlasNumberAt(resilience.structuralVulnerability, i);
  group.sumFloodExposure += floodExposure;
  group.sumWildfireExposure += wildfireExposure;
  group.sumLandslideExposure += landslideExposure;
  group.sumHeatDroughtExposure += heatDroughtExposure;
  group.sumFloodDamage += atlasNumberAt(resilience.floodDamageIndex, i);
  group.sumWildfireDamage += atlasNumberAt(resilience.wildfireDamageIndex, i);
  group.sumLandslideDamage += atlasNumberAt(resilience.landslideDamageIndex, i);
  group.sumHeatDroughtDamage += atlasNumberAt(resilience.heatDroughtDamageIndex, i);
  group.sumCombinedDamage += atlasNumberAt(resilience.combinedDamageIndex, i);
  group.sumCurrentDamage += atlasNumberAt(resilience.currentDamageIndex, i);
  group.sumServiceLossYears += atlasNumberAt(resilience.expectedServiceLossYears, i);
  group.sumRecoveryPressure += atlasNumberAt(resilience.recoveryPressure, i);
  group.sumSubsurfaceRisk += subsurfaceRisk;
  group.hazardCounts[Math.min(4, Math.max(0, resilience.dominantHazardCode?.[i] ?? 0))] += 1;
}

function finalizeBuiltResilienceRow(group, context) {
  const areaKm2 = group.cells * context.cellAreaKm2;
  const buildingDivisor = Math.max(1, group.buildingCellCount);
  const cellDivisor = Math.max(1, group.cells);
  const row = {
    type: group.type,
    label_zh: infrastructureTypeLabelZh(group.type),
    cells: group.cells,
    area_km2: round(areaKm2, 6),
    building_cell_count: group.buildingCellCount,
    mean_building_density: atlasMean(group.sumBuildingDensity, buildingDivisor, 6),
    mean_building_height_m: atlasMean(group.sumBuildingHeightM, buildingDivisor, 3),
    max_building_height_m: round(group.maxBuildingHeightM, 3),
    mean_floor_count: atlasMean(group.sumFloorCount, buildingDivisor, 3),
    mean_impervious_fraction: atlasMean(group.sumImperviousFraction, cellDivisor, 6),
    structural_vulnerability: atlasMean(group.sumStructuralVulnerability, cellDivisor, 6),
    mean_flood_exposure: atlasMean(group.sumFloodExposure, cellDivisor, 6),
    mean_wildfire_exposure: atlasMean(group.sumWildfireExposure, cellDivisor, 6),
    mean_landslide_exposure: atlasMean(group.sumLandslideExposure, cellDivisor, 6),
    mean_heat_drought_exposure: atlasMean(group.sumHeatDroughtExposure, cellDivisor, 6),
    flood_damage_index: atlasMean(group.sumFloodDamage, cellDivisor, 6),
    wildfire_damage_index: atlasMean(group.sumWildfireDamage, cellDivisor, 6),
    landslide_damage_index: atlasMean(group.sumLandslideDamage, cellDivisor, 6),
    heat_drought_damage_index: atlasMean(group.sumHeatDroughtDamage, cellDivisor, 6),
    combined_damage_index: atlasMean(group.sumCombinedDamage, cellDivisor, 6),
    current_damage_index: atlasMean(group.sumCurrentDamage, cellDivisor, 6),
    expected_service_loss_years: atlasMean(group.sumServiceLossYears, cellDivisor, 4),
    recovery_pressure: atlasMean(group.sumRecoveryPressure, cellDivisor, 6),
    subsurface_risk_coupling: atlasMean(group.sumSubsurfaceRisk, cellDivisor, 6),
    dominant_hazard: dominantBuiltHazardName(group.hazardCounts),
    recovery_priority: "routine-monitoring",
    priority_action_zh: ""
  };
  row.recovery_priority = builtRecoveryPriority(row, group.type);
  row.priority_action_zh = builtResilienceNextAction(row);
  return row;
}

function builtResilienceSummary(rows, resilience, context) {
  const buildingCellCount = rows.reduce((sum, row) => sum + row.building_cell_count, 0);
  const areaKm2 = rows.reduce((sum, row) => sum + row.area_km2, 0);
  const weighted = (key) => {
    const divisor = Math.max(1, areaKm2);
    return rows.reduce((sum, row) => sum + row[key] * row.area_km2, 0) / divisor;
  };
  const highPriority = rows.find((row) => row.recovery_priority === "critical-intervention") ||
    rows.find((row) => row.recovery_priority === "priority-retrofit") ||
    maxAtlasRow(rows, "combined_damage_index");
  return {
    status: rows.length ? "ready" : "no-built-environment",
    sourceName: context.sourceName,
    featureCount: context.featureCount,
    appliedFeatureCount: context.appliedFeatureCount,
    typeCount: rows.length,
    buildingCellCount,
    builtAreaKm2: round(areaKm2, 6),
    builtAreaFractionOfAoi: atlasRatio(areaKm2, context.totalAreaKm2),
    timeHorizonYears: resilience.years,
    currentYear: resilience.currentYear,
    progress: resilience.progress,
    meanStructuralVulnerability: round(weighted("structural_vulnerability"), 6),
    meanCombinedDamageIndex: round(weighted("combined_damage_index"), 6),
    meanCurrentDamageIndex: round(weighted("current_damage_index"), 6),
    expectedServiceLossYears: round(weighted("expected_service_loss_years"), 4),
    meanRecoveryPressure: round(weighted("recovery_pressure"), 6),
    highPriorityType: highPriority?.type || null,
    highPriorityClass: highPriority?.recovery_priority || null,
    dominantHazard: dominantHazardAcrossRows(rows),
    highPriorityCellCount: resilience.summary?.highPriorityCellCount ?? 0,
    nextActions: dedupeStrings(rows.map((row) => row.priority_action_zh)).slice(0, 12)
  };
}

function builtRecoveryCells(model, resilience, params = {}) {
  const influence = model.infrastructureInfluence || {};
  const seaLevel = Number(params.seaLevel ?? 0);
  const cells = [];
  if (!influence.mask) return cells;
  for (let i = 0; i < model.height.length; i += 1) {
    if (!influence.mask[i] || model.height[i] <= seaLevel) continue;
    const buildingDensity = clamp(influence.buildingDensity?.[i] ?? 0, 0, 1);
    const buildingHeightM = Math.max(influence.buildingHeightM?.[i] ?? 0, influence.landmarkHeightM?.[i] ?? 0);
    const floorCount = clamp(influence.floorCount?.[i] ?? (buildingHeightM > 0 ? buildingHeightM / 3.2 : 0), 0, 220);
    if (buildingDensity <= 0.02 && buildingHeightM <= 1 && floorCount <= 0) continue;
    const type = INFRASTRUCTURE_CODE_TYPES[influence.typeCode?.[i] || 0] || "custom";
    const structural = clamp(resilience.structuralVulnerability?.[i] ?? builtTypeVulnerability(type), 0, 1);
    cells.push({
      index: i,
      type,
      buildingDensity,
      buildingHeightM,
      floorCount,
      impervious: clamp(model.surface?.imperviousFraction?.[i] ?? influence.imperviousFraction?.[i] ?? 0, 0, 1),
      criticality: typeCriticality(type),
      structural,
      floodDamage: clamp(resilience.floodDamageIndex?.[i] ?? 0, 0, 1),
      wildfireDamage: clamp(resilience.wildfireDamageIndex?.[i] ?? 0, 0, 1),
      landslideDamage: clamp(resilience.landslideDamageIndex?.[i] ?? 0, 0, 1),
      heatDroughtDamage: clamp(resilience.heatDroughtDamageIndex?.[i] ?? 0, 0, 1),
      recoveryPressure: clamp(resilience.recoveryPressure?.[i] ?? 0, 0, 1),
      subsurfaceRisk: clamp(
        subsurfaceColumnValue(model, "columnEngineeringRisk", i, 0) * 0.72 +
          subsurfaceColumnValue(model, "columnLiquefactionRisk", i, 0) * 0.22 +
          subsurfaceColumnValue(model, "columnFractureRisk", i, 0) * 0.16,
        0,
        1
      ),
      flowRetention: clamp(influence.flowRetention?.[i] ?? 0, 0, 0.95),
      storageNorm: clamp((influence.storageMm?.[i] ?? 0) / 1100, 0, 1)
    });
  }
  return cells;
}

function advanceBuiltRecoveryYear(model, params, cells, damageState, recoveryState, year, targetYears) {
  const pulses = builtRecoveryYearPulses(params, model.boundaryForcing, year);
  let floodSum = 0;
  let wildfireSum = 0;
  let landslideSum = 0;
  let heatDroughtSum = 0;
  let eventSum = 0;
  let repairSum = 0;
  let unrepairedSum = 0;
  let vulnerabilitySum = 0;
  let annualServiceLoss = 0;
  let highPriorityCells = 0;
  let backlogSum = 0;
  const hazardWeights = new Float64Array(5);

  for (let c = 0; c < cells.length; c += 1) {
    const cell = cells[c];
    const flood = clamp(cell.floodDamage * pulses.flood * (1 - cell.flowRetention * 0.22 - cell.storageNorm * 0.1), 0, 1);
    const wildfire = clamp(cell.wildfireDamage * pulses.wildfire * (1 - cell.storageNorm * 0.04), 0, 1);
    const landslide = clamp(cell.landslideDamage * pulses.landslide * (1 + cell.subsurfaceRisk * 0.18), 0, 1);
    const heatDrought = clamp(cell.heatDroughtDamage * pulses.heatDrought * (1 - cell.storageNorm * 0.08), 0, 1);
    const eventDamage = clamp(
      Math.max(flood, wildfire, landslide, heatDrought) * 0.66 +
        (flood + wildfire + landslide + heatDrought) * 0.075 +
        cell.structural * 0.035,
      0,
      1
    );
    const previous = damageState[c];
    const repairCapacity = builtAnnualRepairCapacity(cell, eventDamage, pulses);
    const naturalDecay = 0.012 + (1 - cell.structural) * 0.018;
    const repair = Math.min(previous + eventDamage * 0.18, repairCapacity + previous * naturalDecay);
    const nextDamage = clamp(previous * (1 - naturalDecay) + eventDamage * (1 - previous * 0.22) - repair, 0, 1);
    damageState[c] = nextDamage;
    const serviceLoss = nextDamage * (0.26 + cell.structural * 0.46 + cell.criticality * 0.28);
    const backlog = nextDamage * (1 + cell.criticality * 0.42 + cell.recoveryPressure * 0.22);
    floodSum += flood;
    wildfireSum += wildfire;
    landslideSum += landslide;
    heatDroughtSum += heatDrought;
    eventSum += eventDamage;
    repairSum += repair;
    unrepairedSum += nextDamage;
    vulnerabilitySum += cell.structural;
    annualServiceLoss += serviceLoss;
    backlogSum += backlog;
    if (nextDamage >= 0.48 || backlog >= 0.62) highPriorityCells += 1;
    hazardWeights[1] += flood;
    hazardWeights[2] += wildfire;
    hazardWeights[3] += landslide;
    hazardWeights[4] += heatDrought;
  }

  const divisor = Math.max(1, cells.length);
  recoveryState.cumulativeEventDamage += eventSum / divisor;
  recoveryState.cumulativeRepair += repairSum / divisor;
  recoveryState.cumulativeServiceLossYears += annualServiceLoss / divisor;
  recoveryState.lastAnnual = {
    flood: floodSum / divisor,
    wildfire: wildfireSum / divisor,
    landslide: landslideSum / divisor,
    heatDrought: heatDroughtSum / divisor,
    eventDamage: eventSum / divisor,
    repair: repairSum / divisor,
    unrepaired: unrepairedSum / divisor,
    vulnerability: vulnerabilitySum / divisor,
    serviceLoss: annualServiceLoss / divisor,
    highPriorityCells,
    backlog: backlogSum / divisor,
    dominantHazard: dominantBuiltHazardName(hazardWeights)
  };
  return builtRecoveryRowFromState(model, params, cells, damageState, recoveryState, year, targetYears);
}

function builtRecoveryRowFromState(model, params, cells, damageState, recoveryState, year, targetYears) {
  const divisor = Math.max(1, cells.length);
  let unrepaired = 0;
  for (let i = 0; i < damageState.length; i += 1) unrepaired += damageState[i];
  const last = recoveryState.lastAnnual || {
    flood: 0,
    wildfire: 0,
    landslide: 0,
    heatDrought: 0,
    eventDamage: 0,
    repair: 0,
    unrepaired: 0,
    vulnerability: cells.reduce((sum, cell) => sum + cell.structural, 0) / divisor,
    serviceLoss: 0,
    highPriorityCells: 0,
    backlog: 0,
    dominantHazard: "none"
  };
  const cellAreaKm2 = modelCellSupportAreaKm2(model);
  return {
    year,
    progress_fraction: targetYears > 0 ? round(year / targetYears, 6) : 0,
    built_cell_count: cells.length,
    built_area_km2: round(cells.length * cellAreaKm2, 6),
    mean_structural_vulnerability: round(last.vulnerability, 6),
    annual_flood_damage_index: round(last.flood, 6),
    annual_wildfire_damage_index: round(last.wildfire, 6),
    annual_landslide_damage_index: round(last.landslide, 6),
    annual_heat_drought_damage_index: round(last.heatDrought, 6),
    annual_event_damage_index: round(last.eventDamage, 6),
    annual_repair_index: round(last.repair, 6),
    repaired_damage_index: round(recoveryState.cumulativeRepair, 6),
    mean_unrepaired_damage_index: round(unrepaired / divisor, 6),
    cumulative_event_damage_index: round(recoveryState.cumulativeEventDamage, 6),
    cumulative_repair_index: round(recoveryState.cumulativeRepair, 6),
    cumulative_service_loss_years: round(recoveryState.cumulativeServiceLossYears, 6),
    expected_annual_service_loss_years: round(last.serviceLoss, 6),
    high_priority_built_area_km2: round((last.highPriorityCells || 0) * cellAreaKm2, 6),
    recovery_backlog_index: round(Math.max(last.backlog || 0, unrepaired / divisor), 6),
    dominant_hazard: last.dominantHazard || "none"
  };
}

function builtRecoveryYearPulses(params, boundaryForcing, year) {
  const weights = disasterModeWeights(params.disasterMode, Number(params.disasterIntensity ?? 0));
  const seedPhase = ((Number(params.seed) || 0) % 10000) / 10000;
  const wetCycle = Math.sin((year + seedPhase * 9.7) * (Math.PI * 2 / 9.3));
  const dryCycle = Math.sin((year + seedPhase * 13.1 + 2.4) * (Math.PI * 2 / 13.7));
  const stormPulse = Math.max(0, wetCycle);
  const dryPulse = Math.max(0, dryCycle);
  const multipliers = boundaryForcing?.hazardMultipliers || {};
  const floodDrive = clamp(weights.flood + Number(multipliers.flood || 0), 0, 3);
  const droughtDrive = clamp(weights.drought + weights.heat * 0.35 + Number(multipliers.drought || 0) + Number(multipliers.heat || 0) * 0.35, 0, 3);
  const wildfireDrive = clamp(weights.wildfire + Number(multipliers.wildfire || 0) + Number(multipliers.wind || 0) * 0.18, 0, 3);
  const landslideDrive = clamp(weights.quake + Number(multipliers.landslide || 0), 0, 3);
  return {
    flood: clamp(0.42 + stormPulse * 0.62 + floodDrive * 0.28, 0.12, 1.85),
    wildfire: clamp(0.36 + dryPulse * 0.5 + wildfireDrive * 0.3 + droughtDrive * 0.08, 0.1, 1.75),
    landslide: clamp(0.34 + stormPulse * 0.26 + landslideDrive * 0.36 + floodDrive * 0.08, 0.1, 1.7),
    heatDrought: clamp(0.38 + dryPulse * 0.58 + droughtDrive * 0.3, 0.1, 1.8),
    calm: clamp(1 - Math.max(stormPulse, dryPulse) * 0.42, 0.45, 1)
  };
}

function builtAnnualRepairCapacity(cell, eventDamage, pulses) {
  const criticalBoost = 1 + cell.criticality * 0.55;
  const accessPenalty = clamp(eventDamage * 0.36 + cell.recoveryPressure * 0.12, 0, 0.52);
  const complexityPenalty = clamp(cell.structural * 0.16 + Math.log1p(cell.buildingHeightM) / Math.log1p(500) * 0.12 + cell.subsurfaceRisk * 0.08, 0, 0.34);
  const waterSupport = clamp(cell.storageNorm * 0.025 + cell.flowRetention * 0.018, 0, 0.04);
  return clamp((0.032 + (1 - cell.structural) * 0.032 + cell.criticality * 0.018 + waterSupport) * criticalBoost * pulses.calm - accessPenalty * 0.035 - complexityPenalty * 0.026, 0.006, 0.18);
}

