function dominantBuiltHazardCode(floodDamage, wildfireDamage, landslideDamage, heatDroughtDamage) {
  const values = [0, floodDamage, wildfireDamage, landslideDamage, heatDroughtDamage];
  let best = 0;
  let bestValue = 0;
  for (let i = 1; i < values.length; i += 1) {
    if (values[i] > bestValue) {
      bestValue = values[i];
      best = i;
    }
  }
  return bestValue > 0.02 ? best : 0;
}

function dominantBuiltHazardName(counts) {
  const names = ["none", "flood", "wildfire", "landslide", "heat-drought"];
  let best = 0;
  let bestCount = -1;
  for (let i = 0; i < counts.length; i += 1) {
    if (counts[i] > bestCount) {
      bestCount = counts[i];
      best = i;
    }
  }
  return names[best] || "none";
}

function dominantHazardAcrossRows(rows) {
  const weights = {};
  for (const row of rows) {
    if (!row.dominant_hazard || row.dominant_hazard === "none") continue;
    weights[row.dominant_hazard] = (weights[row.dominant_hazard] || 0) + row.combined_damage_index * Math.max(1, row.area_km2);
  }
  let best = null;
  let bestWeight = -1;
  for (const [hazard, weight] of Object.entries(weights)) {
    if (weight > bestWeight) {
      bestWeight = weight;
      best = hazard;
    }
  }
  return best;
}

function builtRecoveryPriority(row, type) {
  const criticality = typeCriticality(type);
  const priorityScore = clamp(row.current_damage_index * 0.44 + row.recovery_pressure * 0.32 + criticality * 0.18 + row.structural_vulnerability * 0.12, 0, 1);
  if (priorityScore >= 0.68 || row.expected_service_loss_years >= 8) return "critical-intervention";
  if (priorityScore >= 0.48 || row.combined_damage_index >= 0.38) return "priority-retrofit";
  if (priorityScore >= 0.28 || row.combined_damage_index >= 0.2) return "targeted-inspection";
  return "routine-monitoring";
}

function builtResilienceNextAction(row) {
  if (row.recovery_priority === "critical-intervention") {
    return "优先进行结构复核、避灾通道、关键功能备援和灾后服务恢复方案校准。";
  }
  if (row.dominant_hazard === "flood") {
    return "补充首层标高、排水能力、防洪挡板、泵站和地下空间倒灌参数，细化洪水损伤曲线。";
  }
  if (row.dominant_hazard === "wildfire") {
    return "补充建筑耐火等级、周边可燃物缓冲带、风场与疏散路径，细化野火暴露。";
  }
  if (row.dominant_hazard === "landslide") {
    return "补充边坡工程、地基类型、地下裂隙/液化观测和挡护结构参数，细化滑坡与地基风险。";
  }
  if (row.dominant_hazard === "heat-drought") {
    return "补充建筑冷负荷、供水冗余、绿化遮阴和热岛实测，细化热旱服务中断风险。";
  }
  if (row.recovery_priority === "priority-retrofit") {
    return "优先补充真实建筑轮廓、层数、材料、人口/资产暴露和维修恢复时间参数。";
  }
  return "维持常规监测，并在下一轮导入真实建筑轮廓、材料和关键设施服务范围。";
}

function createInfrastructureAtlasGroup(type) {
  return {
    type,
    cells: 0,
    buildingCellCount: 0,
    landmarkCellCount: 0,
    heatCells: 0,
    highCompositeCells: 0,
    sumBuildingDensity: 0,
    sumBuildingHeightM: 0,
    maxBuildingHeightM: 0,
    sumFloorCount: 0,
    maxLandmarkHeightM: 0,
    sumImperviousFraction: 0,
    imperviousAreaKm2: 0,
    sumRunoffDelta: 0,
    runoffDeltaAreaIndex: 0,
    sumRoughnessDelta: 0,
    sumTemperatureDeltaC: 0,
    storageVolumeM3: 0,
    supplyVolumeM3: 0,
    demandVolumeM3: 0,
    retainedFlowAnnualM3: 0,
    sumFlowRetention: 0,
    sumIrrigationMm: 0,
    sumWaterDemandMm: 0,
    sumVegetationDelta: 0,
    vegetationDeltaAreaIndex: 0,
    sumFloodHazard: 0,
    sumDroughtStress: 0,
    sumWildfireRisk: 0,
    sumLandslideRisk: 0,
    sumCompositeHazard: 0,
    builtExposureIndex: 0,
    sumRunoffCoefficient: 0,
    sumLocalRunoffM3Yr: 0,
    sumDischargeM3Yr: 0,
    sumFlowVelocityMs: 0,
    erosionRiskAreaIndex: 0
  };
}

function addInfrastructureAtlasCell(group, model, influence, i, cellAreaKm2, cellAreaM2, highCompositeThreshold) {
  group.cells += 1;
  const impervious = atlasNumberAt(influence.imperviousFraction, i);
  const runoffDelta = atlasNumberAt(influence.runoffDelta, i);
  const roughnessDelta = atlasNumberAt(influence.roughnessDelta, i);
  const temperatureDeltaC = atlasNumberAt(influence.temperatureDeltaC, i);
  const storageMm = atlasNumberAt(influence.storageMm, i);
  const flowRetention = atlasNumberAt(influence.flowRetention, i);
  const irrigationMm = atlasNumberAt(influence.irrigationMm, i);
  const waterDemandMm = atlasNumberAt(influence.waterDemandMm, i);
  const vegetationDelta = atlasNumberAt(influence.vegetationDelta, i);
  const buildingDensity = atlasNumberAt(influence.buildingDensity, i);
  const buildingHeightM = Math.max(atlasNumberAt(influence.buildingHeightM, i), atlasNumberAt(influence.landmarkHeightM, i));
  const floorCount = atlasNumberAt(influence.floorCount, i);
  const landmarkHeightM = atlasNumberAt(influence.landmarkHeightM, i);
  const flood = atlasNumberAt(model.hazards?.currentFloodHazard ?? model.hazards?.floodHazard, i);
  const drought = atlasNumberAt(model.hazards?.currentDroughtStress ?? model.hazards?.droughtStress, i);
  const wildfire = atlasNumberAt(model.hazards?.currentWildfireRisk ?? model.hazards?.wildfireRisk, i);
  const landslide = atlasNumberAt(model.hazards?.currentLandslideRisk ?? model.hazards?.landslideRisk, i);
  const composite = atlasNumberAt(model.hazards?.currentHazardIndex ?? model.hazards?.hazardIndex, i);
  const erosion = atlasNumberAt(model.hydraulics?.erosionRisk, i);

  group.sumImperviousFraction += impervious;
  group.imperviousAreaKm2 += impervious * cellAreaKm2;
  group.sumRunoffDelta += runoffDelta;
  group.runoffDeltaAreaIndex += runoffDelta * cellAreaKm2;
  group.sumRoughnessDelta += roughnessDelta;
  group.sumTemperatureDeltaC += temperatureDeltaC;
  if (Math.abs(temperatureDeltaC) > 0.05) group.heatCells += 1;
  group.storageVolumeM3 += (storageMm / 1000) * cellAreaM2;
  group.supplyVolumeM3 += ((irrigationMm + storageMm * 0.05) / 1000) * cellAreaM2;
  group.demandVolumeM3 += (waterDemandMm / 1000) * cellAreaM2;
  group.retainedFlowAnnualM3 += atlasNumberAt(model.retainedFlowAnnualM3, i);
  group.sumFlowRetention += flowRetention;
  group.sumIrrigationMm += irrigationMm;
  group.sumWaterDemandMm += waterDemandMm;
  group.sumVegetationDelta += vegetationDelta;
  group.vegetationDeltaAreaIndex += vegetationDelta * cellAreaKm2;
  group.sumFloodHazard += flood;
  group.sumDroughtStress += drought;
  group.sumWildfireRisk += wildfire;
  group.sumLandslideRisk += landslide;
  group.sumCompositeHazard += composite;
  if (composite >= highCompositeThreshold) group.highCompositeCells += 1;
  group.sumRunoffCoefficient += atlasNumberAt(model.runoffCoefficient, i);
  group.sumLocalRunoffM3Yr += atlasNumberAt(model.localRunoffAnnualM3, i);
  group.sumDischargeM3Yr += atlasNumberAt(model.discharge, i);
  group.sumFlowVelocityMs += atlasNumberAt(model.hydraulics?.flowVelocity, i);
  group.erosionRiskAreaIndex += erosion * cellAreaKm2;

  if (buildingDensity > 0.02 || buildingHeightM > 1 || floorCount > 0) {
    group.buildingCellCount += 1;
    group.sumBuildingDensity += buildingDensity;
    group.sumBuildingHeightM += buildingHeightM;
    group.sumFloorCount += floorCount;
    group.maxBuildingHeightM = Math.max(group.maxBuildingHeightM, buildingHeightM);
  }
  if (landmarkHeightM > 1) {
    group.landmarkCellCount += 1;
    group.maxLandmarkHeightM = Math.max(group.maxLandmarkHeightM, landmarkHeightM);
  }

  const exposureWeight = clamp(0.22 + impervious * 0.28 + buildingDensity * 0.34 + clamp(buildingHeightM / 260, 0, 1) * 0.16, 0, 1);
  group.builtExposureIndex += composite * exposureWeight * cellAreaKm2;
}

function finalizeInfrastructureAtlasRow(group, context) {
  const areaKm2 = group.cells * context.cellAreaKm2;
  const buildingDivisor = Math.max(1, group.buildingCellCount);
  const row = {
    type: group.type,
    label_zh: infrastructureTypeLabelZh(group.type),
    feedback_class: "mixed",
    feedback_class_zh: "复合反馈",
    cells: group.cells,
    area_km2: round(areaKm2, 6),
    area_fraction_of_infrastructure: atlasRatio(areaKm2, context.affectedAreaKm2),
    area_fraction_of_aoi: atlasRatio(areaKm2, context.totalAreaKm2),
    building_cell_count: group.buildingCellCount,
    mean_building_density: atlasMean(group.sumBuildingDensity, buildingDivisor, 6),
    mean_building_height_m: atlasMean(group.sumBuildingHeightM, buildingDivisor, 3),
    max_building_height_m: round(group.maxBuildingHeightM, 3),
    mean_floor_count: atlasMean(group.sumFloorCount, buildingDivisor, 3),
    landmark_cell_count: group.landmarkCellCount,
    max_landmark_height_m: round(group.maxLandmarkHeightM, 3),
    mean_impervious_fraction: atlasMean(group.sumImperviousFraction, group.cells, 6),
    impervious_area_km2: round(group.imperviousAreaKm2, 6),
    mean_runoff_delta: atlasMean(group.sumRunoffDelta, group.cells, 6),
    runoff_delta_area_index: round(group.runoffDeltaAreaIndex, 6),
    mean_roughness_delta: atlasMean(group.sumRoughnessDelta, group.cells, 6),
    mean_temperature_delta_c: atlasMean(group.sumTemperatureDeltaC, group.cells, 4),
    heat_area_km2: round(group.heatCells * context.cellAreaKm2, 6),
    storage_volume_m3: round(group.storageVolumeM3, 3),
    supply_volume_m3: round(group.supplyVolumeM3, 3),
    demand_volume_m3: round(group.demandVolumeM3, 3),
    demand_to_supply_ratio: atlasRatio(group.demandVolumeM3, group.supplyVolumeM3),
    retained_flow_annual_m3: round(group.retainedFlowAnnualM3, 3),
    mean_flow_retention: atlasMean(group.sumFlowRetention, group.cells, 6),
    mean_irrigation_mm: atlasMean(group.sumIrrigationMm, group.cells, 3),
    mean_water_demand_mm: atlasMean(group.sumWaterDemandMm, group.cells, 3),
    mean_vegetation_delta: atlasMean(group.sumVegetationDelta, group.cells, 6),
    vegetation_delta_area_index: round(group.vegetationDeltaAreaIndex, 6),
    mean_flood_hazard: atlasMean(group.sumFloodHazard, group.cells, 6),
    mean_drought_stress: atlasMean(group.sumDroughtStress, group.cells, 6),
    mean_wildfire_risk: atlasMean(group.sumWildfireRisk, group.cells, 6),
    mean_landslide_risk: atlasMean(group.sumLandslideRisk, group.cells, 6),
    mean_composite_hazard: atlasMean(group.sumCompositeHazard, group.cells, 6),
    high_composite_hazard_area_km2: round(group.highCompositeCells * context.cellAreaKm2, 6),
    built_exposure_index: round(group.builtExposureIndex, 6),
    mean_runoff_coefficient: atlasMean(group.sumRunoffCoefficient, group.cells, 6),
    mean_local_runoff_m3_yr: atlasMean(group.sumLocalRunoffM3Yr, group.cells, 3),
    mean_discharge_m3_yr: atlasMean(group.sumDischargeM3Yr, group.cells, 3),
    mean_flow_velocity_ms: atlasMean(group.sumFlowVelocityMs, group.cells, 6),
    erosion_risk_area_index: round(group.erosionRiskAreaIndex, 6),
    next_action_zh: ""
  };
  row.feedback_class = infrastructureFeedbackClass(row);
  row.feedback_class_zh = infrastructureFeedbackClassZh(row.feedback_class);
  row.next_action_zh = infrastructureAtlasNextAction(row);
  return row;
}

function infrastructureAtlasSummary(rows, influence, context) {
  const storage = rows.reduce((sum, row) => sum + row.storage_volume_m3, 0);
  const supply = rows.reduce((sum, row) => sum + row.supply_volume_m3, 0);
  const demand = rows.reduce((sum, row) => sum + row.demand_volume_m3, 0);
  const retained = rows.reduce((sum, row) => sum + row.retained_flow_annual_m3, 0);
  const impervious = rows.reduce((sum, row) => sum + row.impervious_area_km2, 0);
  const heat = rows.reduce((sum, row) => sum + row.heat_area_km2, 0);
  const exposure = rows.reduce((sum, row) => sum + row.built_exposure_index, 0);
  const dominant = rows[0] || null;
  return {
    status: rows.length ? "ready" : "no-infrastructure",
    sourceName: influence?.sourceName || null,
    featureCount: influence?.featureCount || 0,
    appliedFeatureCount: influence?.appliedFeatureCount || 0,
    affectedCellCount: context.affectedCellCount,
    affectedAreaKm2: round(context.affectedAreaKm2, 6),
    affectedAreaFractionOfAoi: atlasRatio(context.affectedAreaKm2, context.totalAreaKm2),
    typeCount: rows.length,
    dominantType: atlasTypeMarker(dominant, "area_km2"),
    highestHazardType: atlasTypeMarker(maxAtlasRow(rows, "mean_composite_hazard"), "mean_composite_hazard"),
    highestDemandType: atlasTypeMarker(maxAtlasRow(rows, "demand_volume_m3"), "demand_volume_m3"),
    highestRetentionType: atlasTypeMarker(maxAtlasRow(rows, "retained_flow_annual_m3"), "retained_flow_annual_m3"),
    highestHeatType: atlasTypeMarker(maxAtlasRow(rows, "mean_temperature_delta_c"), "mean_temperature_delta_c"),
    totalStorageVolumeM3: round(storage, 3),
    totalSupplyVolumeM3: round(supply, 3),
    totalDemandVolumeM3: round(demand, 3),
    aggregateDemandToSupplyRatio: atlasRatio(demand, supply),
    totalRetainedFlowAnnualM3: round(retained, 3),
    totalImperviousAreaKm2: round(impervious, 6),
    totalHeatModifiedAreaKm2: round(heat, 6),
    totalBuiltExposureIndex: round(exposure, 6),
    nextActions: dedupeStrings(rows.map((row) => row.next_action_zh)).slice(0, 12),
    noteZh: rows.length
      ? "设施影响图谱已按类型汇总，可作为明天继续做精细设施校准、3D 体量细化和灾害情景联动的入口。"
      : "当前模型未加载人造设施；可先手工添加城镇、水库、大坝、道路或导入 OSM/工程设施 GeoJSON。"
  };
}

function infrastructureFeedbackClass(row) {
  if (row.mean_flow_retention >= 0.18 || row.storage_volume_m3 > 0) return "water-control";
  if (row.demand_to_supply_ratio !== null && row.demand_to_supply_ratio > 1.15) return "resource-demand";
  if (row.mean_impervious_fraction >= 0.45 || row.mean_temperature_delta_c >= 1.1 || row.mean_runoff_delta >= 0.1) return "urban-heat-runoff";
  if (row.mean_building_density >= 0.25 || row.mean_building_height_m >= 18) return "built-exposure";
  if (row.mean_vegetation_delta > 0.05 || ["park", "solar_farm", "wind_farm"].includes(row.type)) return "low-impact-greening";
  return "mixed";
}

function infrastructureFeedbackClassZh(value) {
  if (value === "water-control") return "水利调蓄反馈";
  if (value === "resource-demand") return "资源需求压力";
  if (value === "urban-heat-runoff") return "城市热-径流反馈";
  if (value === "built-exposure") return "建成暴露反馈";
  if (value === "low-impact-greening") return "低影响/绿化反馈";
  return "复合反馈";
}

function infrastructureAtlasNextAction(row) {
  if (row.demand_to_supply_ratio !== null && row.demand_to_supply_ratio > 1.25) {
    return "优先校核供水、再生水或灌溉来源，避免设施用水需求超过当前可调度供给。";
  }
  if (row.mean_composite_hazard >= 0.65 && row.building_cell_count > 0) {
    return "优先叠加更精细建筑轮廓、人口/资产暴露和避灾通道，细化高暴露设施的灾害情景。";
  }
  if (row.mean_flood_hazard >= 0.6 && row.storage_volume_m3 <= row.area_km2 * 25_000) {
    return "补充排水、滞洪、堤防或泵站参数，并用降雨-径流事件校核洪水削减效果。";
  }
  if (row.feedback_class === "water-control") {
    return "核查库容、闸坝调度、渠道输水和下游生态流量，作为下一轮水利设施校准重点。";
  }
  if (row.feedback_class === "urban-heat-runoff") {
    return "增加透水铺装、绿蓝基础设施和街区形态参数，继续细化热岛与快流响应。";
  }
  if (row.feedback_class === "low-impact-greening") {
    return "保留为生态缓冲或低影响开发基线，并补充植被养护、土壤和蒸散实测约束。";
  }
  return "保留为后续精细建模入口，下一步可补充真实轮廓、高度、材料、人口或工程调度数据。";
}

function atlasNumberAt(values, index) {
  const number = Number(values?.[index]);
  return Number.isFinite(number) ? number : 0;
}

function atlasMean(sum, count, decimals) {
  const divisor = Math.max(1, count);
  return round(sum / divisor, decimals);
}

function atlasRatio(numerator, denominator) {
  const value = ratio(numerator, denominator);
  return value === null ? null : round(value, 6);
}

const INFRASTRUCTURE_TYPE_LABEL_OVERRIDES_ZH = Object.freeze({
  data_center: "\u6570\u636e\u4e2d\u5fc3",
  market: "\u96c6\u5e02/\u5546\u4e1a\u8857",
  terrace_farm: "\u68af\u7530\u519c\u4e1a",
  substation: "\u53d8\u7535\u7ad9",
  clinic: "\u8bca\u6240/\u6025\u8bca\u70b9",
  library: "\u56fe\u4e66\u9986",
  community_center: "\u793e\u533a\u4e2d\u5fc3",
  bus_terminal: "\u516c\u4ea4\u67a2\u7ebd",
  water_tower: "\u6c34\u5854/\u9ad8\u4f4d\u6c34\u6c60",
  observatory: "\u5929\u6587\u53f0/\u89c2\u6d4b\u7ad9",
  cable_car_station: "\u7d22\u9053\u7ad9/\u7f06\u8f66\u7ad9",
  flood_pump_station: "\u6392\u6d9d\u6cf5\u7ad9",
  desalination_plant: "\u6d77\u6c34\u6de1\u5316\u5382",
  hydropower_plant: "\u6c34\u7535\u7ad9",
  geothermal_plant: "\u5730\u70ed\u7535\u7ad9",
  water_treatment_plant: "\u51c0\u6c34\u5382",
  mountain_refuge: "\u5c71\u5730\u907f\u96be\u6240",
  ferry_terminal: "\u6e21\u8f6e\u7801\u5934",
  fire_watch_tower: "\u68ee\u6797\u706b\u60c5\u77ad\u671b\u5854",
  visitor_center: "\u6e38\u5ba2\u4e2d\u5fc3",
  scenic_overlook: "\u89c2\u666f\u53f0/\u77ad\u671b\u70b9",
  trailhead: "\u767b\u5c71\u53e3/\u6b65\u9053\u5165\u53e3",
  ranger_station: "\u62a4\u6797/\u666f\u533a\u7ba1\u7406\u7ad9",
  gauging_station: "\u6c34\u6587\u6d4b\u7ad9"
});

function infrastructureTypeLabelZh(type) {
  return INFRASTRUCTURE_TYPE_LABEL_OVERRIDES_ZH[type] || INFRASTRUCTURE_TYPE_LABELS_ZH[type] || type || "未知设施";
}

function maxAtlasRow(rows, key) {
  let best = null;
  for (const row of rows) {
    if (!best || Number(row[key] ?? -Infinity) > Number(best[key] ?? -Infinity)) best = row;
  }
  return best;
}

function atlasTypeMarker(row, metricKey) {
  if (!row) return null;
  const marker = {
    type: row.type,
    labelZh: row.label_zh
  };
  if (metricKey) marker[metricKey] = row[metricKey];
  return marker;
}

function infrastructureBudgetDiagnostics(input) {
  const affectedAreaKm2 = input.affectedCells * input.cellAreaKm2;
  return {
    sourceName: input.influence.sourceName,
    featureCount: input.influence.featureCount,
    appliedFeatureCount: input.influence.appliedFeatureCount,
    affectedAreaKm2,
    affectedCellCount: input.affectedCells,
    classCellCounts: input.influence.classCellCounts,
    equivalentImperviousAreaKm2: input.infrastructureImperviousAreaKm2,
    heatModifiedAreaKm2: input.infrastructureHeatAreaKm2,
    waterSupplyVolumeM3: input.infrastructureSupplyVolumeM3,
    waterDemandVolumeM3: input.infrastructureDemandVolumeM3,
    storageCapacityM3: input.infrastructureStorageCapacityM3,
    retainedFlowAnnualM3: input.retainedFlowAnnualM3,
    demandToSupplyRatio: ratio(input.infrastructureDemandVolumeM3, input.infrastructureSupplyVolumeM3),
    storagePerAffectedAreaMm: affectedAreaKm2 > 0 ? input.infrastructureStorageCapacityM3 / (affectedAreaKm2 * 1_000_000) * 1000 : null,
    imperviousFractionEquivalent: ratio(input.infrastructureImperviousAreaKm2, affectedAreaKm2)
  };
}

function waterBudgetClosureClass(residual, input) {
  const value = pctOf(residual, input);
  if (value === null) return "missing-input";
  const pct = Math.abs(Number(value));
  if (pct <= 20) return "tight";
  if (pct <= 45) return "storage-or-groundwater-dominated";
  if (pct <= 80) return "loose";
  return "physically-suspect";
}

function ratio(numerator, denominator) {
  const n = Number(numerator);
  const d = Number(denominator);
  if (!Number.isFinite(n) || !Number.isFinite(d) || d <= 0) return null;
  return n / d;
}

function pctOf(numerator, denominator) {
  const value = ratio(numerator, denominator);
  return value === null ? null : value * 100;
}
